const PROTOCOLO = [{"paso": 1, "titulo": "Sorteo de la tarjeta", "dur": null, "durTexto": "Sin tiempo asignado", "estudiante": "Acredita su identidad ante el tribunal y extrae al azar una tarjeta del banco: las generales y las rojas de su carrera.", "tribunal": "Conforma el banco según la carrera del estudiante y registra el código de la tarjeta en la Ficha FI-AM1-01."}, {"paso": 2, "titulo": "Tiempo de organización", "dur": 600, "durTexto": "10 minutos", "estudiante": "En una mesa auxiliar analiza el problema, esboza hipótesis, desarrolla las deducciones teóricas, grafica en borrador y estructura su exposición. Puede usar calculadora, tablas, Mathematica y GeoGebra.", "tribunal": "Controla el tiempo sin intervenir."}, {"paso": 3, "titulo": "Entrevista estructurada", "dur": 600, "durTexto": "5 a 10 minutos", "estudiante": "Expone la solución analítica y la fundamentación teórica de su tarjeta y responde las preguntas guía.", "tribunal": "Evalúa la claridad, el rigor en el uso de la simbología, la precisión de las demostraciones y el manejo del cálculo diferencial e integral en el pizarrón."}, {"paso": 4, "titulo": "Pregunta integradora obligatoria", "dur": null, "durTexto": "Al cierre de la entrevista", "estudiante": "Responde al menos una pregunta conceptual que vincula su tarjeta con un eje distinto del programa.", "tribunal": "Formula la pregunta integradora indicada en la tarjeta u otra equivalente de un eje distinto."}, {"paso": 5, "titulo": "Calificación y registro", "dur": null, "durTexto": "Sin exposición", "estudiante": "Concluye su intervención.", "tribunal": "Delibera, consigna los puntajes en la rúbrica, asienta el resultado en la Ficha FI-AM1-01 y firma el acta."}];
const FICHA = "FI-AM1-01";
const TARJETAS = [{"id": "AM-01", "eje": "1", "tipo": "Consigna matemática", "titulo": "Composición de funciones y dominio", "temas": ["Operaciones con funciones", "Composición", "Dominio e imagen", "Función inversa"], "consigna": "Dadas f(x) = √(x − 1), g(x) = 1/(x − 3) y h(x) = x² + 1, estudiar las funciones compuestas f∘h, h∘f, g∘f y f∘g: obtener su expresión y su dominio. Luego decidir cuáles de las funciones f, g y h admiten inversa en su dominio natural. Derivar f∘h aplicando la regla de la cadena y calcular ∫₋₁¹ (f∘h)(x) dx.", "teorema": {"nombre": "Condición de existencia de la función compuesta", "consigna": "Enunciar la condición que deben cumplir la imagen de g y el dominio de f para que exista f∘g, y justificar con ella el dominio de cada composición."}, "capacidades": ["Determinar el dominio de una composición a partir de sus condiciones de existencia", "Reconocer funciones inyectivas y obtener su inversa"], "preguntas": [{"c": "dominio", "t": "¿Por qué h∘f(x) = x no tiene dominio ℝ? ¿Son iguales h∘f y la función identidad?"}, {"c": "dominio", "t": "¿Qué propiedad debe tener una función para admitir inversa? ¿Por qué h no la tiene en ℝ y cómo podría restringirse su dominio?"}, {"c": "planteo", "t": "Derivar f∘h con la regla de la cadena e indicar qué hipótesis de la regla falla en x = 0. Calcular ∫₋₁¹ (f∘h)(x) dx e interpretarla como área."}, {"c": "planteo", "t": "Obtener f⁻¹ y g⁻¹, indicar dominio e imagen de cada una y verificar que f(f⁻¹(x)) = x."}, {"c": "lenguaje", "t": "Expresar los dominios obtenidos en notación de intervalos y en notación de conjuntos."}], "articulacion": {"eje": "2", "t": "¿Es continua f∘g en todo su dominio? ¿Qué ocurre con g∘f cuando x → 10?"}, "clave": "f∘h = |x|, dominio ℝ. h∘f = x, dominio [1, +∞). g∘f = 1/(√(x − 1) − 3), dominio [1, +∞) − {10}, con asíntota vertical en x = 10. f∘g = √(1/(x − 3) − 1), dominio (3, 4]. f⁻¹(x) = x² + 1 con x ≥ 0; g⁻¹(x) = 3 + 1/x; h no es inyectiva en ℝ (es par). (f∘h)′(x) = x/|x| para x ≠ 0; en x = 0 la regla no se aplica porque f no es derivable en h(0) = 1: punto anguloso. ∫₋₁¹ |x| dx = 1.", "ref": "Zill, Matemáticas 1, §2.2 y §2.5"}, {"id": "AM-02", "eje": "1", "tipo": "Problema aplicado", "titulo": "Tarifa eléctrica por bloques", "temas": ["Función definida por partes", "Dominio e imagen", "Función inversa"], "consigna": "Una distribuidora eléctrica factura el consumo mensual x (en kWh) con un cargo fijo F y un precio por bloques: p₁ por cada kWh hasta 150 kWh, p₂ por cada kWh entre 150 y 300 kWh y p₃ por cada kWh por encima de 300 kWh, con p₁ < p₂ < p₃. Un usuario recibe una factura de importe I y quiere reconstruir cuánto consumió. Expresar el importe como C(x) = F + ∫₀ˣ p(s) ds, con p(s) el precio por kWh vigente en cada bloque, y analizar en qué consumos C es derivable y qué representa C′(x).", "teorema": {"nombre": "Inyectividad de las funciones estrictamente monótonas", "consigna": "Enunciar y demostrar que toda función estrictamente creciente es inyectiva, y justificar por qué eso permite reconstruir el consumo a partir del importe."}, "capacidades": ["Modelizar una regla tarifaria como función definida por partes", "Determinar la existencia y la expresión de la función inversa en cada tramo"], "preguntas": [{"c": "dominio", "t": "Indicar la imagen de C. ¿En qué consumos es C derivable? Calcular C′ en cada tramo e interpretar su significado para el usuario."}, {"c": "dominio", "t": "¿Qué condición debe cumplir una función para tener inversa? ¿La cumple C(x)? Justificar sin recurrir al gráfico."}, {"c": "planteo", "t": "Escribir C(x) por tramos a partir de C(x) = F + ∫₀ˣ p(s) ds. ¿Por qué la integral produce una función continua aunque p(s) tenga saltos?"}, {"c": "planteo", "t": "Obtener la función inversa x = C⁻¹(I) por tramos e indicar en qué intervalo de importes vale cada expresión."}, {"c": "lenguaje", "t": "Explicar en un párrafo dirigido al usuario por qué, con esta regla, un aumento de consumo nunca reduce el importe."}], "articulacion": {"eje": "2", "t": "Si se facturara todo el consumo al precio del bloque alcanzado, ¿qué tipo de discontinuidad aparecería en x = 150? ¿Qué consecuencia tendría para quien consume 151 kWh?"}, "clave": "C(x) = F + p₁x en [0, 150]; F + 150p₁ + p₂(x − 150) en (150, 300]; F + 150p₁ + 150p₂ + p₃(x − 300) para x > 300. Imagen [F, +∞). Estrictamente creciente ⇒ inyectiva ⇒ invertible sobre su imagen. La otra regla genera un salto en x = 150. C′(x) = p₁, p₂ o p₃ según el tramo; C no es derivable en x = 150 ni en x = 300 (derivadas laterales distintas). La integral de la función escalonada p(s) es continua: el importe no salta.", "ref": "Zill, Matemáticas 1, §2.1 y §2.5"}, {"id": "AM-03", "eje": "1", "tipo": "Problema aplicado", "titulo": "Enfriamiento del mosto", "temas": ["Función exponencial", "Función logarítmica", "Función inversa", "Modelos matemáticos"], "consigna": "En una bodega, un tanque de mosto a 30 °C se ingresa a una cámara que se mantiene a 10 °C. La temperatura del mosto responde al modelo T(t) = 10 + 20·e^(−kt), con t en horas. Una hora después del ingreso se miden 24 °C. El enólogo necesita que el mosto llegue a 14 °C antes de inocular las levaduras. Calcular la velocidad de enfriamiento T′(t) una hora después del ingreso y, con una integral definida, la temperatura media del mosto durante las primeras 4 horas.", "teorema": {"nombre": "La exponencial y el logaritmo natural como funciones inversas", "consigna": "Enunciar las propiedades que hacen de y = eˣ una biyección de ℝ en (0, +∞) y justificar por qué ln es su inversa."}, "capacidades": ["Calibrar los parámetros de un modelo exponencial con un dato medido", "Usar la función logarítmica para despejar el tiempo en un modelo exponencial"], "preguntas": [{"c": "dominio", "t": "Calcular T′(t) y justificar con su signo la monotonía de T. ¿Qué representan los números 10 y 20 del modelo?"}, {"c": "dominio", "t": "¿Por qué es válido aplicar ln a ambos miembros de una igualdad entre exponenciales? ¿Qué propiedad lo garantiza?"}, {"c": "planteo", "t": "Calcular k a partir de la medición a la hora y luego el tiempo necesario para alcanzar 14 °C."}, {"c": "planteo", "t": "Calcular la temperatura media en [0, 4] con la integral definida. ¿Por qué no coincide con el promedio entre T(0) y T(4)?"}, {"c": "lenguaje", "t": "Expresar el tiempo obtenido con la precisión que admiten los datos y redactarlo como instrucción operativa."}], "articulacion": {"eje": "5", "t": "El modelo es solución de la ecuación diferencial dT/dt = −k·(T − 10). Verificarlo por derivación e indicar el orden y el tipo de la ecuación."}, "clave": "k = −ln 0,7 ≈ 0,357 h⁻¹; t = ln 0,2 / ln 0,7 ≈ 4,5 h. T′(t) = −20k·e^(−kt) < 0; T′(1) ≈ −5,0 °C/h. Temperatura media en [0, 4]: 10 + (5/k)·(1 − 0,7⁴) ≈ 20,7 °C, menor que (T(0) + T(4))/2 ≈ 22,4 °C porque T es convexa. EDO de primer orden, lineal, a variables separables.", "ref": "Zill, Matemáticas 1, §2.6"}, {"id": "AM-04", "eje": "1", "tipo": "Problema aplicado", "titulo": "Riesgo de helada en un viñedo", "temas": ["Funciones trigonométricas", "Período, amplitud y desfase", "Inecuaciones trigonométricas", "Funciones trigonométricas inversas"], "consigna": "Para un día de primavera en un viñedo del sur mendocino, la temperatura del aire a nivel de brotes se modela con T(h) = 6 + 7·sen(π(h − 9)/12), con h en horas desde la medianoche y T en °C. El sistema de defensa contra heladas debe funcionar mientras la temperatura sea inferior a 2 °C. Derivar T(h) para obtener la hora en que el descenso de temperatura es más rápido y calcular con una integral la temperatura media del día.", "teorema": {"nombre": "Inversa de una función restringida", "consigna": "Explicar por qué y = sen x no es invertible en ℝ, cómo se restringe su dominio para definir arcsen y justificar la elección del intervalo [−π/2, π/2]."}, "capacidades": ["Interpretar amplitud, período y desfase de un modelo sinusoidal", "Resolver una inecuación trigonométrica usando funciones inversas y periodicidad"], "preguntas": [{"c": "dominio", "t": "Identificar amplitud, período, desfase y valor medio del modelo. ¿A qué hora se produce la mínima y cuánto vale?"}, {"c": "dominio", "t": "¿Por qué arcsen devuelve un único ángulo si la ecuación sen u = c tiene infinitas soluciones? ¿Cómo se obtienen las demás?"}, {"c": "planteo", "t": "Plantear y resolver la inecuación T(h) < 2. ¿Entre qué horas debe funcionar el sistema y durante cuánto tiempo?"}, {"c": "planteo", "t": "Derivar T(h) y hallar la hora de descenso más rápido y su valor en °C/h. ¿Qué limitación tiene un modelo periódico de 24 h para una noche real?"}, {"c": "articulacion", "t": "Calcular la temperatura media diaria con la integral definida. ¿Por qué coincide con el término constante del modelo?"}], "articulacion": {"eje": "2", "t": "¿Es T(h) continua en ℝ? Explicar, con la continuidad y el teorema de Bolzano, por qué el conjunto en que T(h) < 2 está limitado por las soluciones de T(h) = 2."}, "clave": "Período 24 h; mínima −1 °C a las 3 h. T < 2 °C ⇔ sen(π(h − 9)/12) < −4/7 ⇔ h ∈ (−0,68; 6,68): desde ≈ 23:19 hasta ≈ 06:41, unas 7,4 h. Media diaria 6 °C. Descenso máximo a las 21 h: −7π/12 ≈ −1,83 °C/h. T′(h) = (7π/12)·cos(π(h − 9)/12). Media diaria: (1/24)·∫₀²⁴ T(h) dh = 6 °C, porque la integral del seno en un período es nula.", "ref": "Zill, Matemáticas 1, §2.4–2.5"}, {"id": "AM-05", "eje": "1", "tipo": "Consigna matemática", "titulo": "Afirmaciones sobre funciones", "temas": ["Valor absoluto e inecuaciones", "Funciones pares e impares", "Función cuadrática", "Función inversa"], "consigna": "Analizar justificadamente si cada afirmación es verdadera o falsa. (a) f(x) = −x² + 2x + 8 es positiva en (−2, 4) y su valor máximo es 9. (b) g(x) = x³ − x + 1 es una función impar. (c) El conjunto solución de |2x − 3| < 5 es (−1, 4). (d) h(x) = (2x − 1)/(x + 3) es inyectiva y su inversa es h⁻¹(x) = (3x + 1)/(2 − x). (e) La recta tangente a la gráfica de f en x = 1 es horizontal y el área de la región entre esa gráfica y el eje x en [−2, 4] vale 36.", "teorema": {"nombre": "Propiedades del valor absoluto", "consigna": "Enunciar la equivalencia |u| < a ⇔ −a < u < a (con a > 0) y la desigualdad triangular, y justificar con ellas la afirmación (c)."}, "capacidades": ["Justificar o refutar afirmaciones sobre funciones con argumentos analíticos", "Resolver inecuaciones con valor absoluto y reconocer simetrías"], "preguntas": [{"c": "dominio", "t": "¿Qué significa que una función sea par o impar? ¿Cómo se reconoce en la gráfica? ¿Puede una función ser par e impar a la vez?"}, {"c": "dominio", "t": "¿Qué basta para refutar una afirmación general y qué hace falta para probarla?"}, {"c": "planteo", "t": "Resolver la inecuación de (c) y expresar el conjunto solución como entorno: ¿cuál es su centro y cuál su radio?"}, {"c": "planteo", "t": "Verificar (d) componiendo h con la inversa propuesta y justificar (e) con la derivada de f y con la regla de Barrow. ¿Qué relación hay entre la tangente horizontal de (e) y el máximo de (a)?"}, {"c": "lenguaje", "t": "Redactar la justificación de (b) con notación precisa, sin apoyarse en el gráfico."}], "articulacion": {"eje": "2", "t": "h(x) tiene una asíntota vertical y una horizontal. Indicarlas y explicar su relación con el dominio y la imagen de h⁻¹."}, "clave": "(a) V: f = −(x − 4)(x + 2), máximo f(1) = 9. (b) F: g(0) = 1 ≠ 0, imposible en una función impar definida en 0. (c) V: −1 < x < 4, entorno de centro 1,5 y radio 2,5. (d) V. Asíntotas de h: x = −3 e y = 2; dominio de h⁻¹: ℝ − {2}; imagen: ℝ − {−3}. (e) V: f′(x) = −2x + 2 se anula en x = 1; ∫₋₂⁴ (−x² + 2x + 8) dx = 36 y f ≥ 0 en [−2, 4]. h′(x) = 7/(x + 3)² > 0 confirma la inyectividad de (d).", "ref": "Zill, Matemáticas 1, §1.5 y §2.1"}, {"id": "AM-06", "eje": "1", "tipo": "Problema aplicado", "titulo": "Población de truchas en un lago", "temas": ["Función cuadrática", "Dominio natural y contextual", "Inecuaciones", "Modelos matemáticos"], "consigna": "En un lago artificial se sembraron 400 truchas. Un estudio estima que la población, en cientos de ejemplares, evoluciona según N(t) = −0,25t² + 3t + 4, con t en años desde la siembra. Se necesita saber cuándo la población es máxima, en qué período supera los 1 000 ejemplares y si llegará a extinguirse. Calcular la tasa de variación de la población en el momento de la siembra y, con una integral definida, la población media durante los primeros 6 años.", "teorema": {"nombre": "Extremo de la función cuadrática", "consigna": "Justificar, completando cuadrados, que f(x) = ax² + bx + c con a < 0 alcanza su máximo en x = −b/(2a)."}, "capacidades": ["Distinguir dominio natural y dominio contextual de un modelo", "Interpretar ceros, vértice y signo de una función cuadrática en un problema"], "preguntas": [{"c": "dominio", "t": "¿Qué diferencia hay entre dominio natural y dominio contextual? Indicar ambos para N(t)."}, {"c": "dominio", "t": "¿Qué representa N′(t)? Calcular N′(0) e interpretar el signo de N′ antes y después del máximo."}, {"c": "planteo", "t": "Calcular la población máxima y el instante en que se alcanza, y la población media de los primeros 6 años con la integral definida."}, {"c": "planteo", "t": "Determinar en qué período la población supera los 1 000 ejemplares y en qué momento se extingue."}, {"c": "lenguaje", "t": "Expresar los resultados en años y meses, con la precisión que admite el modelo."}], "articulacion": {"eje": "2", "t": "¿Qué valor da el modelo para N(t) cuando t → +∞? ¿Por qué el dominio contextual impide esa lectura?"}, "clave": "Dominio contextual [0; 6 + 2√13] ≈ [0; 13,2] años. Máximo N(6) = 13 (1 300 truchas). N > 10 entre t ≈ 2,5 y t ≈ 9,5 años. Extinción en t = 6 + 2√13 ≈ 13,2 años. N′(0) = 3: 300 truchas por año. N′(t) = −0,5t + 3: positiva hasta t = 6 y negativa después. Población media en [0, 6]: (1/6)·∫₀⁶ N(t) dt = 10 (1 000 truchas).", "ref": "Zill, Matemáticas 1, §2.3 y §2.7"}, {"id": "AM-43", "eje": "1", "origen": "T-02", "tipo": "Problema aplicado", "titulo": "Concentración en un reactor de mezcla", "temas": ["Función racional", "Función inversa", "Asíntotas", "Valor medio"], "consigna": "La concentración de un reactivo en un tanque de mezcla evoluciona según C(t) = (5t + 2)/(t + 1) g/L, con t en minutos desde la inyección. Escribir C como transformación de y = 1/x, indicar dominio contextual, imagen y monotonía, y obtener la función inversa para calcular cuándo la concentración alcanza 4,5 g/L. Calcular con la derivada la velocidad de variación de la concentración al inicio y, con una integral definida, la concentración media en los primeros 10 minutos.", "teorema": {"nombre": "Función inversa de una función inyectiva", "consigna": "Enunciar la condición para que una función admita inversa y justificar que C la cumple en [0, +∞)."}, "capacidades": ["Analizar una función racional por transformaciones de una función elemental", "Obtener e interpretar la función inversa en un contexto"], "preguntas": [{"c": "dominio", "t": "¿Qué condición debe cumplir una función para tener inversa? Justificar que C la cumple usando el signo de C′."}, {"c": "dominio", "t": "Indicar las asíntotas de la gráfica de C y su imagen en [0, +∞). ¿Qué representa la asíntota horizontal en el proceso?"}, {"c": "planteo", "t": "Obtener C⁻¹ y calcular el instante en que la concentración alcanza 4,5 g/L. ¿Se alcanzan 5 g/L?"}, {"c": "planteo", "t": "Calcular C′(0) y la concentración media (1/10)·∫₀¹⁰ C(t) dt escribiendo C(t) = 5 − 3/(t + 1)."}, {"c": "lenguaje", "t": "Expresar el dominio y la imagen de C y de C⁻¹ en notación de intervalos."}], "articulacion": {"eje": "2", "t": "Enunciar el teorema de Bolzano. ¿Puede aplicarse a C en [0, 10] para asegurar un cero? ¿Por qué?"}, "clave": "C = 5 − 3/(t + 1): traslación de y = −3/x. Dominio contextual [0, +∞); C(0) = 2; C′ = 3/(t + 1)² > 0: creciente; imagen [2, 5); asíntotas t = −1 (fuera del dominio) y C = 5. C⁻¹(c) = (c − 2)/(5 − c); C = 4,5 en t = 5 min; 5 g/L no se alcanza. C′(0) = 3 g/(L·min). Media en [0, 10]: 5 − 0,3·ln 11 ≈ 4,28 g/L. Bolzano no concluye: C > 0 en [0, 10].", "ref": ""}, {"id": "AM-07", "eje": "2", "tipo": "Problema aplicado", "titulo": "Velocidad límite de un paquete", "temas": ["Límite al infinito", "Asíntota horizontal", "Propiedades de los límites", "Modelos con exponencial"], "consigna": "Un paquete de insumos se lanza desde un helicóptero sanitario con un paracaídas de frenado. Con resistencia del aire proporcional a la velocidad, la velocidad de caída es v(t) = (mg/c)·(1 − e^(−ct/m)), con m = 20 kg, c = 40 kg/s y g = 9,8 m/s². El embalaje resiste un impacto a menos de 5,5 m/s. Calcular la aceleración inicial del paquete a partir de v′(t) y, integrando la velocidad, la distancia recorrida en los primeros 3 s.", "teorema": {"nombre": "Definición de límite al infinito y unicidad del límite", "consigna": "Enunciar la definición de lím v(t) = L cuando t → +∞ (con ε y M) y justificar que ese límite, si existe, es único."}, "capacidades": ["Calcular e interpretar el límite al infinito de un modelo físico", "Vincular la asíntota horizontal con un valor estacionario del sistema"], "preguntas": [{"c": "dominio", "t": "Calcular lím v(t) para t → +∞ justificando cada paso con las propiedades de los límites, y decidir si resiste el embalaje. ¿Qué representa la recta v = mg/c?"}, {"c": "dominio", "t": "¿Alcanza el paquete la velocidad límite? Explicar la diferencia entre «tender a» y «alcanzar» con la definición de límite."}, {"c": "planteo", "t": "Para ε = 0,05·(mg/c), hallar a partir de qué instante M la velocidad difiere de la velocidad límite en menos de ε."}, {"c": "planteo", "t": "Calcular v′(t) e interpretar v′(0) y lím v′(t) para t → +∞. Calcular la distancia recorrida en los primeros 3 s como ∫₀³ v(t) dt."}, {"c": "articulacion", "t": "¿Cómo cambia el modelo si se desprecia la resistencia del aire? Relacionar ambos casos con el límite de v(t) cuando c → 0."}], "articulacion": {"eje": "5", "t": "v(t) es solución de m·dv/dt = mg − cv. Mostrar que es una ecuación diferencial a variables separables y resolverla con v(0) = 0."}, "clave": "v∞ = mg/c = 4,9 m/s < 5,5 m/s: resiste. |v − v∞| < 0,05·v∞ para t > (m/c)·ln 20 ≈ 1,5 s. Para c → 0, v(t) → g·t. v′(t) = g·e^(−ct/m): v′(0) = 9,8 m/s² y v′ → 0. Distancia en 3 s: ∫₀³ 4,9·(1 − e^(−2t)) dt = 4,9·(3 − (1 − e^(−6))/2) ≈ 12,3 m.", "ref": "Zill, Matemáticas 1, §3.5–3.6"}, {"id": "AM-08", "eje": "2", "tipo": "Problema aplicado", "titulo": "Costo de tratar efluentes", "temas": ["Límites laterales", "Límite infinito", "Asíntota vertical", "Función racional"], "consigna": "Se estima que el costo de remover el p % de la carga orgánica de los efluentes de una bodega es C(p) = 800·p/(100 − p), en miles de pesos, para 0 ≤ p < 100. La autoridad ambiental exige una remoción mínima del 90 % y una organización vecinal reclama «vertido cero», es decir, remoción del 100 %. Calcular el costo marginal C′(p) para p = 90 y el valor medio de C′ entre 90 % y 99 %.", "teorema": {"nombre": "Límite infinito y asíntota vertical", "consigna": "Enunciar la definición de lím f(x) = +∞ cuando x → a⁻ y justificar con ella que p = 100 es asíntota vertical del modelo."}, "capacidades": ["Interpretar una asíntota vertical como límite técnico y económico de un proceso", "Calcular límites laterales y relacionarlos con el dominio del modelo"], "preguntas": [{"c": "dominio", "t": "Calcular lím C(p) para p → 100⁻. ¿Tiene sentido analizar p → 100⁺? Justificar con el dominio y con el problema."}, {"c": "dominio", "t": "Distinguir límite infinito de límite en el infinito. ¿Cuál aparece en esta consigna?"}, {"c": "planteo", "t": "Comparar el costo de pasar de 90 % a 95 % con el de pasar de 95 % a 99 %. ¿Qué indica sobre el reclamo de «vertido cero»?"}, {"c": "planteo", "t": "Calcular C′(p) y C′(90). Mostrar con la regla de Barrow que el valor medio de C′ en [90, 99] es (C(99) − C(90))/9 e interpretarlo."}, {"c": "lenguaje", "t": "Redactar una conclusión técnica de dos oraciones para la autoridad ambiental que use con propiedad la noción de asíntota."}], "articulacion": {"eje": "7", "t": "Si la remoción se hiciera en etapas sucesivas y cada una eliminara el 50 % de la carga remanente, ¿qué porcentaje se alcanzaría tras n etapas? ¿A qué valor tiende y con qué serie se relaciona?"}, "clave": "C(90) = 7 200; C(95) = 15 200; C(99) = 79 200 (miles de $). C′(p) = 80 000/(100 − p)²; C′(90) = 800 miles de $ por punto porcentual; C′ → +∞ si p → 100⁻. Valor medio de C′ en [90, 99]: (1/9)·∫₉₀⁹⁹ C′(p) dp = (C(99) − C(90))/9 = 8 000 miles de $ por punto. Con 20 000: p = 2 000/20,8 ≈ 96,2 %. Por etapas: 1 − 0,5ⁿ → 1, sin alcanzarlo.", "ref": "Zill, Matemáticas 1, §3.5"}, {"id": "AM-09", "eje": "2", "tipo": "Consigna matemática", "titulo": "Dos funciones racionales", "temas": ["Función racional", "Asíntotas vertical, horizontal y oblicua", "Discontinuidad evitable e infinita"], "consigna": "Dadas f(x) = (x² − 1)/(x − 2) y g(x) = (x² − 1)/(x² − x − 2), determinar dominio, ceros y ordenada al origen de cada una; analizar la existencia de asíntotas; clasificar sus discontinuidades y representarlas en forma aproximada, en coherencia con el análisis. Obtener f′ y los extremos relativos de f, y calcular el área de la región limitada por la gráfica de g y los ejes coordenados.", "teorema": {"nombre": "Continuidad en un punto y clasificación de discontinuidades", "consigna": "Definir continuidad en un punto mediante sus tres condiciones y justificar con ellas la clasificación de las discontinuidades de f y de g."}, "capacidades": ["Determinar y justificar las asíntotas de funciones racionales mediante límites", "Clasificar discontinuidades y redefinir una función con discontinuidad evitable"], "preguntas": [{"c": "dominio", "t": "Definir asíntota vertical, horizontal y oblicua en términos de límites."}, {"c": "dominio", "t": "¿Por qué g presenta una discontinuidad evitable en x = −1 y no una asíntota vertical, aunque allí se anule el denominador?"}, {"c": "planteo", "t": "Calcular los límites laterales de f en x = 2 y su asíntota oblicua. Obtener f′, sus valores críticos y los extremos relativos."}, {"c": "planteo", "t": "Redefinir g para que sea continua en x = −1 y calcular el área entre su gráfica y los ejes, escribiendo g como 1 + 1/(x − 2)."}, {"c": "lenguaje", "t": "Expresar con notación de límites el comportamiento de f respecto de su asíntota oblicua cuando x → +∞."}], "articulacion": {"eje": "1", "t": "Escribir g como transformación de y = 1/x e indicar las traslaciones que intervienen. ¿Es g invertible en su dominio? Obtener su inversa."}, "clave": "f: dominio ℝ − {2}; ceros ±1; f(0) = 1/2; f → −∞ si x → 2⁻ y f → +∞ si x → 2⁺; oblicua y = x + 2. g = (x − 1)/(x − 2) para x ≠ −1: evitable en x = −1 (límite 2/3), infinita en x = 2, horizontal y = 1, cero en x = 1. f′ = (x² − 4x + 1)/(x − 2)² = 0 en x = 2 ± √3: máximo relativo en 2 − √3 y mínimo relativo en 2 + √3. Área entre g y los ejes: ∫₀¹ (1 + 1/(x − 2)) dx = 1 − ln 2 ≈ 0,307. g⁻¹(x) = 2 + 1/(x − 1).", "ref": "Zill, Matemáticas 1, §3.3 y §3.5"}, {"id": "AM-10", "eje": "2", "tipo": "Consigna matemática", "titulo": "Continuidad de una función por partes", "temas": ["Función definida por partes", "Continuidad en un punto", "Límites laterales", "Discontinuidad de salto"], "consigna": "Dada f(x) = a·x − 1 si x < 1; f(x) = x² + b si 1 ≤ x < 3; f(x) = 2x + 5 si x ≥ 3, determinar los valores de a y b que hacen continua a f en ℝ. Luego, para a = 2 y b = 2, analizar qué tipo de discontinuidad presenta f en x = 1. Para a = 4 y b = 2, analizar la derivabilidad de f en x = 1 y en x = 3 y calcular ∫₀³ f(x) dx.", "teorema": {"nombre": "Continuidad en un punto y en un intervalo cerrado", "consigna": "Enunciar las tres condiciones de continuidad en un punto y la definición de continuidad en un intervalo cerrado, y justificar con ellas el sistema que determina a y b."}, "capacidades": ["Analizar la continuidad de funciones por partes mediante límites laterales", "Determinar parámetros que garantizan la continuidad"], "preguntas": [{"c": "dominio", "t": "¿Cuál de las tres condiciones de continuidad falla en una discontinuidad de salto y cuál en una evitable?"}, {"c": "dominio", "t": "¿Qué significa que f sea continua en un intervalo cerrado [a, b]? ¿Qué se exige en los extremos?"}, {"c": "planteo", "t": "Plantear el sistema que surge de las condiciones de continuidad en x = 1 y x = 3 y resolverlo."}, {"c": "planteo", "t": "Con a = 4 y b = 2, calcular las derivadas laterales en x = 1 y x = 3, y ∫₀³ f(x) dx aplicando la aditividad respecto del intervalo."}, {"c": "lenguaje", "t": "Representar f para a = 2 y b = 2 indicando con la convención usual los extremos incluidos y excluidos de cada tramo."}], "articulacion": {"eje": "1", "t": "Para a = 4 y b = 2, determinar la imagen de cada tramo y de f. ¿Es f inyectiva? Justificar."}, "clave": "En x = 3: 9 + b = 11 ⇒ b = 2. En x = 1: a − 1 = 1 + b ⇒ a = 4. Con a = 2: límites laterales 1 y 3 en x = 1, salto finito. Raíz en x = 1/4 (f(0) = −1 y f(1) = 3). No derivable en x = 1 (laterales 4 y 2) ni en x = 3 (6 y 2). ∫₀³ f = ∫₀¹ (4x − 1) dx + ∫₁³ (x² + 2) dx = 1 + 38/3 = 41/3 ≈ 13,67. Con a = 4 y b = 2, f es estrictamente creciente, inyectiva y de imagen ℝ.", "ref": "Zill, Matemáticas 1, §3.3"}, {"id": "AM-11", "eje": "2", "tipo": "Consigna matemática", "titulo": "El valor de sen(x)/x en el origen", "temas": ["Límites notables", "Discontinuidad evitable", "Infinitésimos equivalentes", "Clasificación de discontinuidades"], "consigna": "Al graficar f(x) = sen(x)/x con GeoGebra, la curva aparece continua y toma un valor cercano a 1 junto al origen; al evaluarla en x = 0 con una calculadora, se obtiene un error. Analizar el comportamiento de f en x = 0 y el de otras funciones con indeterminaciones del mismo tipo. Con la función redefinida, calcular f′(0) por definición y estimar ∫₀¹ sen(x)/x dx.", "teorema": {"nombre": "Teorema de intercalación", "consigna": "Enunciar el teorema de intercalación y usarlo para justificar que lím sen(x)/x = 1 cuando x → 0, explicando el origen de las desigualdades que acotan la función."}, "capacidades": ["Clasificar una discontinuidad y redefinir la función para hacerla continua", "Utilizar infinitésimos equivalentes en el cálculo de límites indeterminados"], "preguntas": [{"c": "dominio", "t": "Clasificar la discontinuidad de f en x = 0. ¿Qué la diferencia de una discontinuidad de salto y de una infinita? Dar un ejemplo de cada una."}, {"c": "dominio", "t": "¿Qué significa que sen x y x sean infinitésimos equivalentes cuando x → 0? ¿Para qué sirve en el cálculo de límites?"}, {"c": "planteo", "t": "Redefinir f para que sea continua en ℝ y calcular f′(0) por definición. ¿Por qué el software y la calculadora muestran resultados distintos?"}, {"c": "planteo", "t": "Explicar por qué ∫₀¹ sen(x)/x dx existe aunque el integrando original no esté definido en 0, y estimar su valor."}, {"c": "lenguaje", "t": "Explicar por qué «el límite vale 1» y «la función vale 1 en el origen» no son la misma afirmación."}], "articulacion": {"eje": "7", "t": "El desarrollo de Maclaurin de sen x permite escribir sen(x)/x como serie de potencias. Escribir sus primeros términos y explicar por qué muestra que 1 es el valor natural en x = 0."}, "clave": "Discontinuidad evitable; se redefine f(0) = 1. f′(0) = lím (sen h − h)/h² = 0. sen(x)/x = 1 − x²/6 + x⁴/120 − …; ∫₀¹ sen(x)/x dx ≈ 1 − 1/18 + 1/600 ≈ 0,9461: la discontinuidad evitable no afecta la integrabilidad. lím (1 − cos x)/x² = 1/2.", "ref": "Zill, Matemáticas 1, §3.3–3.4"}, {"id": "AM-12", "eje": "2", "tipo": "Problema aplicado", "titulo": "Subida y bajada a un mirador", "temas": ["Continuidad en un intervalo cerrado", "Teorema de Bolzano", "Modelización con funciones"], "consigna": "Un ciclista sube un sábado desde la ciudad hasta un mirador en la montaña: sale a las 8:00 y llega a las 12:00. El domingo baja por el mismo camino: sale del mirador a las 8:00 y llega a la ciudad a las 11:00. Un compañero afirma que hubo necesariamente un punto del camino por el que pasó a la misma hora ambos días, aunque no se sepa cuál. Para la subida se dispone además del registro de velocidad v₁(t) = (45/16)·(t − 8)·(12 − t) km/h: verificar que el camino mide 30 km, obtener por integración la posición s₁(t) y calcular la aceleración del ciclista a las 9:00.", "teorema": {"nombre": "Teorema de Bolzano", "consigna": "Enunciar el teorema de Bolzano con sus hipótesis y justificar con él la afirmación del compañero."}, "capacidades": ["Modelizar una situación con funciones continuas y aplicar el teorema de Bolzano", "Distinguir la existencia de un valor de su cálculo efectivo"], "preguntas": [{"c": "dominio", "t": "Enunciar el teorema de Bolzano y el de los valores intermedios. ¿Qué relación hay entre ambos?"}, {"c": "dominio", "t": "¿Falla alguna hipótesis si el ciclista se detiene a descansar? ¿Y si baja por otro camino?"}, {"c": "planteo", "t": "Definir las funciones posición de cada día y la función auxiliar h(t). Verificar las hipótesis en el intervalo adecuado."}, {"c": "planteo", "t": "Obtener s₁(t) = ∫₈ᵗ v₁(u) du, verificar que s₁(12) = 30 km y calcular v₁′(9). Suponiendo la bajada a 10 km/h constantes, estimar la hora del encuentro."}, {"c": "lenguaje", "t": "Explicar por qué el teorema garantiza la existencia del punto pero no permite ubicarlo sin más información."}], "articulacion": {"eje": "4", "t": "Si s₁ es derivable, ¿qué asegura el teorema de Lagrange sobre la velocidad del ciclista el sábado? ¿Qué valor debe alcanzar en algún instante?"}, "clave": "h(t) = s₁(t) − s₂(t) en [8, 11]: h(8) = −L < 0 y h(11) = s₁(11) > 0 ⇒ existe c con h(c) = 0. Detenerse no rompe la continuidad. Con w = t − 8: s₁ = (45/16)·(2w² − w³/3) y s₁(12) = 30 km. v₁′(9) = 5,625 km/h². Con bajada a 10 km/h: encuentro hacia las 9:46, a 12,4 km de la ciudad. Lagrange: v₁ = 7,5 km/h en algún instante.", "ref": "Zill, Matemáticas 1, §3.3"}, {"id": "AM-44", "eje": "2", "origen": "T-01", "tipo": "Problema aplicado", "titulo": "Sensor de temperatura en un templado", "temas": ["Continuidad", "Límites laterales", "Teorema de los valores intermedios", "Derivadas laterales"], "consigna": "Un proceso de templado registra la temperatura de las piezas con un sensor que cambia de modelo según el tramo de calentamiento: T(t) = t² + 2 para 0 ≤ t ≤ 3 y T(t) = k·t − 4 para t > 3, con t en minutos y T en cientos de grados Celsius. Determinar k para que T sea continua en t = 3, clasificar la discontinuidad que aparece si k toma otro valor, analizar con derivadas laterales si la velocidad de calentamiento es continua en ese instante y calcular con una integral definida la temperatura media en los primeros 4 minutos.", "teorema": {"nombre": "Continuidad en un punto y límites laterales", "consigna": "Definir continuidad de una función en un punto, enunciar la condición de existencia del límite mediante límites laterales y justificar con ella el valor de k."}, "capacidades": ["Determinar parámetros que aseguran la continuidad de una función definida por tramos", "Distinguir continuidad de derivabilidad en un punto de cambio de tramo"], "preguntas": [{"c": "dominio", "t": "Definir continuidad en un punto. ¿Cuál de las tres condiciones se pierde si k ≠ 5 y qué tipo de discontinuidad resulta?"}, {"c": "dominio", "t": "Enunciar el teorema de los valores intermedios y justificar con él que la temperatura alcanza 1 000 °C en [0, 4]. ¿En qué instante ocurre?"}, {"c": "planteo", "t": "Calcular las derivadas laterales de T en t = 3 con k = 5. ¿Es derivable T allí? ¿Qué significa para el control del horno?"}, {"c": "planteo", "t": "Calcular la temperatura media en [0, 4] aplicando la aditividad de la integral respecto del intervalo."}, {"c": "lenguaje", "t": "Escribir con notación de límites las condiciones de continuidad en t = 3."}], "articulacion": {"eje": "1", "t": "Con k = 5, determinar la imagen de T en [0, 4] y justificar si T admite inversa en ese intervalo."}, "clave": "k = 5 (límites laterales 11 y 3k − 4). Con k ≠ 5, discontinuidad de salto finito. T′₋(3) = 6 y T′₊(3) = 5: T no es derivable en t = 3 (punto anguloso). T(t) = 10 ⇔ t = 2√2 ≈ 2,83 min. Media en [0, 4]: (15 + 13,5)/4 ≈ 7,13 (≈ 713 °C). T es estrictamente creciente: invertible, con imagen [2, 16].", "ref": ""}, {"id": "AM-45", "eje": "2", "origen": "T-04", "tipo": "Problema aplicado", "titulo": "Tolerancia en ejes mecanizados", "temas": ["Definición de límite", "Entornos", "Valor absoluto", "Diferencial"], "consigna": "Un centro de mecanizado produce ejes cilíndricos de longitud L = 10 cm y radio r. La superficie lateral es A(r) = 2πLr y debe quedar dentro de una tolerancia ε = 0,01 cm² respecto del valor objetivo A₀ = 100 cm². Enunciar la definición de límite con ε y δ y determinar δ en función de ε. Verificar que el volumen cumple V(r) = ∫₀ʳ A(s) ds, derivarlo y estimar con la derivada qué tolerancia en r asegura que el volumen no se aparte más de 0,01 cm³ de su valor objetivo.", "teorema": {"nombre": "Definición de límite de una función en un punto", "consigna": "Enunciar la definición de límite en términos de ε y δ y aplicarla para demostrar que lím A(r) = A₀ cuando r → r₀."}, "capacidades": ["Aplicar la definición de límite con ε y δ a una tolerancia de fabricación", "Relacionar una función acumulada con su derivada"], "preguntas": [{"c": "dominio", "t": "¿Qué diferencia hay entre el límite de una función en un punto y el valor de la función en ese punto? ¿Por qué en este caso coinciden?"}, {"c": "dominio", "t": "Interpretar geométricamente ε y δ en la gráfica de A(r). ¿Por qué para una función lineal δ es proporcional a ε?"}, {"c": "planteo", "t": "Calcular r₀ y δ para ε = 0,01 cm² y expresar el intervalo admisible de radios."}, {"c": "planteo", "t": "Mostrar que V′(r) = A(r) y estimar con el diferencial la tolerancia en r para el volumen. ¿Es más o menos exigente que la del área?"}, {"c": "lenguaje", "t": "Escribir la tolerancia del radio como inecuación con valor absoluto, como intervalo y como entorno."}], "articulacion": {"eje": "1", "t": "A(r) es lineal y V(r), cuadrática. Indicar el dominio con sentido físico de cada una y obtener la inversa de V."}, "clave": "r₀ = 100/(20π) ≈ 1,5915 cm. |A − A₀| = 20π·|r − r₀| < ε ⇔ |r − r₀| < ε/(20π): δ ≈ 1,59·10⁻⁴ cm. V(r) = ∫₀ʳ 2πLs ds = πLr², V′ = A. Tolerancia de volumen: dr ≈ 0,01/A(r₀) = 10⁻⁴ cm, más exigente. r(V) = √(V/(10π)), V ≥ 0.", "ref": ""}, {"id": "AM-13", "eje": "3", "tipo": "Problema aplicado", "titulo": "Ascenso del nivel de un dique", "temas": ["Tasa de variación media", "Derivada como límite del cociente incremental", "Recta tangente", "Interpretación geométrica"], "consigna": "Durante una crecida, la cota del pelo de agua de un dique se registra cada hora: en t = 0, 1, 2, 3 y 4 h las cotas son 100,00; 100,12; 100,26; 100,42 y 100,60 m. El operador necesita conocer la velocidad de ascenso del nivel en t = 2 h para decidir la apertura del vertedero, y solo dispone de esta tabla. Estimar además con la regla del trapecio la cota media en las 4 h y verificar que ∫₀⁴ h′(t) dt reproduce el ascenso total registrado.", "teorema": {"nombre": "Derivada en un punto e interpretación geométrica", "consigna": "Definir la derivada como límite del cociente incremental y justificar por qué la pendiente de la recta tangente es el límite de las pendientes de las secantes."}, "capacidades": ["Distinguir tasa de variación media e instantánea y estimar la segunda a partir de datos", "Interpretar geométricamente la derivada como pendiente de la recta tangente"], "preguntas": [{"c": "dominio", "t": "Definir la derivada de h en t₀. ¿Qué relación hay entre las rectas secantes y la recta tangente?"}, {"c": "dominio", "t": "¿Por qué ∫₀⁴ h′(t) dt es igual a h(4) − h(0)? ¿Qué teorema se aplica y qué velocidad media de ascenso resulta?"}, {"c": "planteo", "t": "Estimar h′(2) con el cociente incremental hacia adelante, hacia atrás y centrado. ¿Cuál es más confiable?"}, {"c": "planteo", "t": "Escribir la recta tangente aproximada en t = 2 para estimar la cota a las 2,5 h y estimar la cota media en [0, 4] con la regla del trapecio."}, {"c": "lenguaje", "t": "Indicar las unidades de h′(t) y redactar el dato de velocidad de ascenso como figuraría en el parte de operación."}], "articulacion": {"eje": "7", "t": "La cota puede aproximarse cerca de t = 2 por un polinomio de Taylor de grado 2. ¿Qué datos de la tabla permiten estimar h″(2) y qué valor resulta?"}, "clave": "Adelante 0,16 m/h; atrás 0,14 m/h; centrado 0,15 m/h (el más preciso). Tangente: h ≈ 100,26 + 0,15·(t − 2) ⇒ h(2,5) ≈ 100,335 m. Cota media por trapecio: 401,1/4 ≈ 100,28 m. ∫₀⁴ h′ dt = h(4) − h(0) = 0,60 m: velocidad media 0,15 m/h. h″(2) ≈ 100,42 − 2·100,26 + 100,12 = 0,02 m/h².", "ref": "Zill, Matemáticas 1, §4.1–4.2"}, {"id": "AM-14", "eje": "3", "tipo": "Problema aplicado", "titulo": "Dilatación de una placa circular", "temas": ["Regla de la cadena", "Reglas de derivación", "Razón de cambio"], "consigna": "Una placa circular de acero de radio inicial r₀ = 10 cm se calienta en un horno a razón constante de 5 °C/min. El radio varía con la temperatura según r(T) = r₀·(1 + α·(T − T₀)), con α = 12·10⁻⁶ °C⁻¹. Se necesita la velocidad con que aumenta el área de la placa durante el calentamiento. Calcular el aumento de área tras 20 minutos como ∫₀²⁰ (dA/dt) dt y compararlo con la estimación que supone dA/dt constante.", "teorema": {"nombre": "Regla de la cadena", "consigna": "Enunciar la regla de la cadena con sus hipótesis de derivabilidad y justificar por qué la tasa de variación de una composición es el producto de las tasas intermedias."}, "capacidades": ["Identificar una cadena de dependencias funcionales en un fenómeno físico", "Aplicar la regla de la cadena para obtener una razón de cambio respecto del tiempo"], "preguntas": [{"c": "dominio", "t": "Enunciar la regla de la cadena en notación de Leibniz y en notación funcional. ¿Qué exige sobre cada función?"}, {"c": "dominio", "t": "¿Por qué no alcanza con derivar A = πr² respecto de r para responder la consigna?"}, {"c": "planteo", "t": "Identificar la cadena A(r(T(t))) y calcular dA/dt al inicio del calentamiento, con sus unidades."}, {"c": "planteo", "t": "Calcular ΔA en 20 min con ∫₀²⁰ (dA/dt) dt y la regla de Barrow, y compararlo con 20·dA/dt(0). ¿Por qué la diferencia es tan pequeña?"}, {"c": "articulacion", "t": "El coeficiente de dilatación superficial es aproximadamente 2α. Justificar esa relación con derivadas."}], "articulacion": {"eje": "1", "t": "Si T(t) = T₀ + 5t, escribir la función compuesta A(t) en forma explícita e indicar su dominio con sentido físico."}, "clave": "dA/dt = 2πr·(r₀α)·5 ≈ 2π·10·10·12·10⁻⁶·5 ≈ 0,0377 cm²/min. En 20 min, ΔA ≈ 0,754 cm². Exacto: ∫₀²⁰ (dA/dt) dt = A(20) − A(0) = 100π·((1,0012)² − 1) ≈ 0,7544 cm²; con dA/dt constante, 0,7540 cm²: dA/dt varía muy poco.", "ref": "Zill, Matemáticas 1, §4.6"}, {"id": "AM-15", "eje": "3", "tipo": "Consigna matemática", "titulo": "Derivada por definición", "temas": ["Cociente incremental", "Derivada por definición", "Recta tangente", "Derivabilidad y continuidad"], "consigna": "Dadas f(x) = √x y g(x) = 1/x, calcular por definición f′(4) y g′(1), escribir las rectas tangentes en esos puntos y analizar si f es derivable en x = 0. Calcular el área de la región comprendida entre la gráfica de f, su recta tangente en x = 4 y el eje y.", "teorema": {"nombre": "Derivabilidad implica continuidad", "consigna": "Enunciar y demostrar que toda función derivable en un punto es continua en él, y mostrar con un ejemplo que el recíproco es falso."}, "capacidades": ["Calcular derivadas mediante el límite del cociente incremental", "Relacionar derivabilidad, continuidad y existencia de recta tangente"], "preguntas": [{"c": "dominio", "t": "Escribir la definición de derivada en un punto y explicar qué representa el cociente incremental."}, {"c": "dominio", "t": "f es continua en x = 0. ¿Por qué no es derivable allí? ¿Qué ocurre con la recta tangente?"}, {"c": "planteo", "t": "Calcular f′(4) por definición, racionalizando el cociente incremental, y escribir la recta tangente en (4, 2)."}, {"c": "planteo", "t": "Calcular g′(1) por definición y el área entre la gráfica de f, su tangente en x = 4 y el eje y. ¿Por qué la tangente queda por encima de la curva?"}, {"c": "lenguaje", "t": "Escribir el límite que define f′(0) con notación correcta e interpretar su resultado."}], "articulacion": {"eje": "1", "t": "f y g son funciones potenciales. Indicar dominio, imagen y monotonía de cada una y si admiten inversa."}, "clave": "f′(4) = lím (√(4 + h) − 2)/h = 1/4; tangente y = 2 + (x − 4)/4. g′(1) = lím (1/(1 + h) − 1)/h = −1. En x = 0, (√h − 0)/h = 1/√h → +∞: tangente vertical, f no es derivable. Área: ∫₀⁴ (1 + x/4 − √x) dx = 6 − 16/3 = 2/3; la tangente queda por encima porque f es cóncava.", "ref": "Zill, Matemáticas 1, §4.2"}, {"id": "AM-16", "eje": "3", "tipo": "Consigna matemática", "titulo": "Puntos sin derivada", "temas": ["Derivadas laterales", "Valor absoluto", "Puntos angulosos y de retroceso", "Derivabilidad"], "consigna": "Analizar la derivabilidad de f(x) = |x² − 4|, g(x) = x^(2/3) y h(x) = x·|x| en todo su dominio. Indicar los puntos en que no existe la derivada, calcular las derivadas laterales allí y describir el aspecto de la gráfica en cada uno. Calcular ∫₋₃³ |x² − 4| dx.", "teorema": {"nombre": "Derivadas laterales y existencia de la derivada", "consigna": "Definir las derivadas laterales y justificar que f es derivable en a si y solo si ambas existen, son finitas y coinciden."}, "capacidades": ["Analizar la derivabilidad de funciones con valor absoluto y potencias fraccionarias", "Interpretar geométricamente los puntos donde no existe la derivada"], "preguntas": [{"c": "dominio", "t": "Definir derivada lateral por izquierda y por derecha. ¿Qué condición garantiza la derivabilidad?"}, {"c": "dominio", "t": "¿Qué diferencia hay entre un punto anguloso y un punto de retroceso? Identificar cada caso en las funciones dadas."}, {"c": "planteo", "t": "Escribir f por tramos y calcular sus derivadas laterales en x = 2 y en x = −2."}, {"c": "planteo", "t": "Mostrar que h es derivable en x = 0 y obtener h′(x). Calcular ∫₋₃³ |x² − 4| dx descomponiendo el intervalo según el signo de x² − 4."}, {"c": "lenguaje", "t": "Expresar con notación de límites las derivadas laterales de g en x = 0."}], "articulacion": {"eje": "2", "t": "Las tres funciones son continuas en todo ℝ. Justificarlo y explicar por qué la continuidad no alcanza para asegurar la derivabilidad."}, "clave": "f: no derivable en x = ±2 (en x = 2, laterales −4 y 4): puntos angulosos. g: en x = 0 las laterales tienden a −∞ y +∞: punto de retroceso. h(x) = x|x| es derivable en ℝ con h′(x) = 2|x|; h′(0) = 0. ∫₋₃³ |x² − 4| dx = 2·[∫₀² (4 − x²) dx + ∫₂³ (x² − 4) dx] = 2·(16/3 + 7/3) = 46/3 ≈ 15,33.", "ref": "Zill, Matemáticas 1, §4.2"}, {"id": "AM-17", "eje": "3", "tipo": "Problema aplicado", "titulo": "Altura de un tanque elevado", "temas": ["Diferencial de una función", "Aproximación lineal", "Propagación de errores", "Derivada de funciones trigonométricas"], "consigna": "Para verificar la altura de un tanque elevado, un técnico se ubica a d = 50 m de su base, en terreno horizontal, y mide con un teodolito el ángulo de elevación al punto más alto: θ = 35°. El instrumento tiene una incertidumbre de ±0,5°. La altura se calcula como h = d·tan θ, despreciando la altura del instrumento. Estimar con el diferencial de h el error de la altura y calcular, con la integral definida, el valor medio de h(θ) cuando θ recorre el intervalo de incertidumbre [34,5°; 35,5°] y compararlo con h(35°).", "teorema": {"nombre": "Diferenciabilidad y aproximación lineal", "consigna": "Enunciar que si f es derivable en x₀ entonces Δy = f′(x₀)·Δx + ε·Δx con ε → 0 cuando Δx → 0, y justificar por qué dy aproxima a Δy."}, "capacidades": ["Usar el diferencial para estimar la propagación de un error de medición", "Interpretar geométricamente la diferencia entre Δy y dy"], "preguntas": [{"c": "dominio", "t": "Definir el diferencial dy e interpretarlo geométricamente con la recta tangente. ¿Qué representa Δy − dy?"}, {"c": "planteo", "t": "Calcular el valor medio de h(θ) en [34,5°; 35,5°] con la integral definida, con θ en radianes. ¿Por qué resulta levemente mayor que h(35°)?"}, {"c": "planteo", "t": "Calcular h y estimar con el diferencial los errores absoluto y relativo debidos a la incertidumbre del ángulo."}, {"c": "planteo", "t": "El error relativo es dh/h = dθ/(sen θ·cos θ). ¿Desde qué distancia convendría medir para minimizarlo?"}, {"c": "lenguaje", "t": "Expresar el resultado de la medición con su incertidumbre y la cantidad de cifras significativas adecuada."}], "articulacion": {"eje": "1", "t": "¿Por qué tan θ no es invertible en todo su dominio y cómo se define arctan para despejar θ a partir de h y d?"}, "clave": "h ≈ 35,0 m; dh = d·sec²θ·dθ ≈ 0,65 m (≈ 1,9 %). Resultado: h = (35,0 ± 0,7) m. El error relativo es mínimo para θ = 45°, es decir, d ≈ h ≈ 35 m. Valor medio: (d/Δθ)·ln(cos 34,5°/cos 35,5°) ≈ 35,012 m > h(35°) ≈ 35,010 m porque tan θ es convexa en (0, π/2).", "ref": "Zill, Matemáticas 1, §5.8"}, {"id": "AM-18", "eje": "3", "tipo": "Consigna matemática", "titulo": "Derivación implícita y trascendente", "temas": ["Derivación implícita", "Derivada de funciones trascendentes", "Recta tangente", "Regla de la cadena"], "consigna": "La curva x³ + y³ = 6xy pasa por el punto (3, 3). Obtener y′ por derivación implícita, la recta tangente en (3, 3) y los puntos del primer cuadrante con tangente horizontal. Además, derivar f(x) = e^(−x)·sen(2x) y hallar los valores de x en [0, π] donde f′(x) = 0. Calcular ∫₀^π e^(−x)·sen(2x) dx.", "teorema": {"nombre": "Derivación de funciones definidas implícitamente", "consigna": "Explicar en qué condiciones una ecuación F(x, y) = 0 define y como función derivable de x y justificar el procedimiento de derivar ambos miembros respecto de x."}, "capacidades": ["Derivar funciones definidas implícitamente y obtener rectas tangentes", "Aplicar las reglas de derivación a funciones exponenciales y trigonométricas"], "preguntas": [{"c": "dominio", "t": "¿Qué diferencia hay entre una función definida en forma explícita y una en forma implícita? ¿Toda ecuación en x e y define una función?"}, {"c": "dominio", "t": "¿Por qué al derivar y³ respecto de x aparece el factor y′? ¿Qué regla se aplica?"}, {"c": "planteo", "t": "Obtener y′ y la recta tangente en (3, 3)."}, {"c": "planteo", "t": "Derivar f, resolver f′(x) = 0 en [0, π] y calcular ∫₀^π f(x) dx integrando dos veces por partes."}, {"c": "lenguaje", "t": "Escribir y′ con notación de Leibniz y explicar qué representa en el punto (3, 3)."}], "articulacion": {"eje": "4", "t": "Para f(x) = e^(−x)·sen(2x), ¿qué tipo de extremo hay en el primer punto crítico de [0, π]? Justificar con un criterio adecuado."}, "clave": "y′ = (2y − x²)/(y² − 2x); en (3, 3): y′ = −1, tangente y = −x + 6. Tangente horizontal: y = x²/2 ⇒ x³ = 16 ⇒ (2,52; 3,17). f′(x) = e^(−x)·(2cos 2x − sen 2x) = 0 ⇔ tan 2x = 2 ⇒ x ≈ 0,554 y x ≈ 2,124: máximo relativo en x ≈ 0,554. ∫₀^π e^(−x)·sen(2x) dx = (2/5)·(1 − e^(−π)) ≈ 0,383.", "ref": "Zill, Matemáticas 1, §4.7 y §4.9"}, {"id": "AM-46", "eje": "3", "origen": "T-08", "tipo": "Problema aplicado", "titulo": "Linealización de un sensor de presión", "temas": ["Diferencial", "Recta tangente", "Polinomio de Taylor", "Valor medio"], "consigna": "Un sensor de presión no lineal responde según f(x) = √(1 + x), con x la señal de entrada en voltios. Obtener la linealización de f en x₀ = 0 mediante la derivada y el diferencial, y el polinomio de Taylor de grado 3 en x₀ = 0. Acotar el error de ambas aproximaciones en [0; 0,2] y calcular la respuesta media del sensor en ese rango con una integral definida, en forma exacta y con la linealización.", "teorema": {"nombre": "Diferenciabilidad y aproximación lineal", "consigna": "Definir función diferenciable y diferencial, y justificar que la recta tangente es la mejor aproximación lineal de f cerca de x₀."}, "capacidades": ["Linealizar una función y estimar el error cometido", "Construir y acotar un polinomio de Taylor"], "preguntas": [{"c": "dominio", "t": "Definir el diferencial df e interpretar Δf − df en la gráfica. ¿Qué signo tiene ese error para una función cóncava?"}, {"c": "dominio", "t": "Enunciar el teorema de Taylor con resto de Lagrange. ¿Cómo varía la precisión del polinomio al alejarse de x₀?"}, {"c": "planteo", "t": "Obtener la linealización y el polinomio de grado 3 y acotar el error de cada uno en [0; 0,2]."}, {"c": "planteo", "t": "Calcular la respuesta media (1/0,2)·∫₀^0,2 √(1 + x) dx y compararla con la que da la linealización."}, {"c": "lenguaje", "t": "Escribir el polinomio de Taylor y la cota del resto con notación correcta."}], "articulacion": {"eje": "7", "t": "¿Para qué valores de x converge la serie binómica de √(1 + x)? Justificar con el criterio del cociente."}, "clave": "f′(0) = 1/2: L(x) = 1 + x/2. P₃(x) = 1 + x/2 − x²/8 + x³/16. Error de L: |f″(ξ)|·x²/2 ≤ (1/4)·0,04/2 = 0,005. Error de P₃: |f⁽⁴⁾(ξ)|·x⁴/24 ≤ (15/16)·0,2⁴/24 ≈ 6,3·10⁻⁵. Media exacta: (2/3)·(1,2^(3/2) − 1)/0,2 ≈ 1,0485; con L: 1,05 (la tangente queda por encima). Radio de convergencia 1.", "ref": ""}, {"id": "AM-19", "eje": "4", "tipo": "Problema aplicado", "titulo": "Tanque de mínimo material", "temas": ["Extremos absolutos y relativos", "Valores críticos", "Criterio de la derivada segunda", "Problemas de optimización"], "consigna": "Una cooperativa de agua rural necesita un tanque cilíndrico cerrado de chapa con capacidad de 10 m³. El costo depende del área total de chapa, de modo que interesa la combinación de radio y altura que la minimice. El proveedor ofrece también un modelo abierto, sin tapa. El tanque cerrado óptimo se llena con un caudal Q(t) = 0,05·t m³/min: calcular con una integral el tiempo de llenado y la velocidad de ascenso del nivel al completarse.", "teorema": {"nombre": "Teorema de Fermat", "consigna": "Enunciar el teorema de Fermat sobre extremos locales de funciones derivables, demostrarlo y explicar por qué f′(x) = 0 es condición necesaria pero no suficiente."}, "capacidades": ["Plantear función objetivo y restricción en un problema de optimización", "Justificar que un punto crítico es mínimo absoluto en un dominio no acotado"], "preguntas": [{"c": "dominio", "t": "Definir valor crítico. ¿Todo valor crítico es un extremo? Dar un contraejemplo."}, {"c": "dominio", "t": "¿Qué diferencia hay entre mínimo relativo y absoluto? ¿Qué argumentos aseguran que el mínimo hallado es absoluto en r > 0?"}, {"c": "planteo", "t": "Expresar el área total en función del radio y hallar las dimensiones óptimas del tanque cerrado y del abierto. ¿Qué relación entre altura y radio resulta en cada caso?"}, {"c": "planteo", "t": "Calcular el tiempo de llenado a partir de ∫₀ᵀ Q(t) dt = 10 m³ y la velocidad de ascenso del nivel al final, derivando V = πr²h respecto del tiempo."}, {"c": "lenguaje", "t": "Presentar la solución como especificación de compra, con dimensiones redondeadas a una precisión constructiva razonable."}], "articulacion": {"eje": "6", "t": "Si el fondo del tanque fuera curvo, generado por la rotación de una curva, ¿cómo se calcularía su volumen con integrales?"}, "clave": "Cerrado: A(r) = 2πr² + 20/r; r = (10/2π)^(1/3) ≈ 1,17 m; h = 2r ≈ 2,34 m; A ≈ 25,7 m². Abierto: A(r) = πr² + 20/r; h = r ≈ 1,47 m. A → +∞ en ambos extremos de (0, +∞) ⇒ mínimo absoluto. Llenado: 0,025·T² = 10 ⇒ T = 20 min. dh/dt = Q/(πr²) = 1/(π·1,1675²) ≈ 0,23 m/min al final.", "ref": "Zill, Matemáticas 1, §5.2 y §5.7"}, {"id": "AM-20", "eje": "4", "tipo": "Problema aplicado", "titulo": "Falla en una cámara de frío", "temas": ["Teorema de Rolle", "Teorema del valor medio de Lagrange", "Teorema de Cauchy", "Interpretación de la derivada"], "consigna": "Tras una falla del compresor, el registrador de una cámara de frío indica 2 °C a las 8:00 y 8 °C a las 10:00; solo almacena valores cada dos horas. El protocolo de inocuidad obliga a descartar el lote si en algún instante la temperatura aumentó a razón superior a 2,5 °C/h. El responsable de calidad sostiene que, sin registros intermedios, no puede demostrarse el incumplimiento. Fundamentar la conclusión también con la integral: expresar T(10) − T(8) como ∫₈¹⁰ T′(t) dt y analizar qué ocurriría si T′(t) ≤ 2,5 °C/h en todo el intervalo.", "teorema": {"nombre": "Teorema del valor medio de Lagrange", "consigna": "Enunciar el teorema de Lagrange con sus hipótesis, demostrarlo a partir del teorema de Rolle y justificar por qué resuelve la controversia."}, "capacidades": ["Aplicar el teorema del valor medio para extraer información instantánea de dos registros", "Evaluar si las hipótesis de un teorema son razonables en un fenómeno físico"], "preguntas": [{"c": "dominio", "t": "Enunciar el teorema de Rolle y explicar geométricamente por qué Lagrange lo generaliza."}, {"c": "dominio", "t": "¿Qué afirma y qué no afirma Lagrange? ¿Permite saber en qué instante se superó la tasa admitida?"}, {"c": "planteo", "t": "Verificar las hipótesis de Lagrange para T(t) y concluir. Llegar a la misma conclusión acotando ∫₈¹⁰ T′(t) dt: ¿qué propiedad de la integral se usa?"}, {"c": "planteo", "t": "Si la temperatura hubiera vuelto a 2 °C a las 12:00, ¿qué podría afirmarse sobre T′(t) en [8, 12]? ¿Qué teorema se usa?"}, {"c": "articulacion", "t": "El teorema de Cauchy generaliza el de Lagrange a dos funciones. Enunciarlo y explicar qué podría afirmarse si también se registrara la humedad en los mismos instantes."}], "articulacion": {"eje": "5", "t": "El teorema del valor medio del cálculo integral garantiza que la función alcanza su valor medio. Enunciarlo y explicar qué representaría para la temperatura de la cámara."}, "clave": "Tasa media 3 °C/h > 2,5 °C/h ⇒ existe c ∈ (8, 10) con T′(c) = 3 °C/h: el lote se descarta. El teorema no indica el instante. Con T(12) = 2 °C, Rolle asegura T′(c) = 0 para algún c ∈ (8, 12). Si T′ ≤ 2,5 en [8, 10], por monotonía de la integral T(10) − T(8) = ∫₈¹⁰ T′ dt ≤ 5 °C, contra los 6 °C registrados.", "ref": "Zill, Matemáticas 1, §5.3"}, {"id": "AM-21", "eje": "4", "tipo": "Problema aplicado", "titulo": "Descarga de una tolva de granos", "temas": ["Razones de cambio relacionadas", "Derivación implícita", "Regla de la cadena"], "consigna": "Un acopio almacena maíz en una tolva cónica con el vértice hacia abajo, de 2 m de radio superior y 4 m de altura. Por la boca inferior se descargan 0,5 m³/min. El operario observa que el nivel baja cada vez más rápido a medida que la tolva se vacía y pregunta si se trata de una falla de la compuerta. Obtener dh/dt en función de h y calcular, integrando la relación entre dh y dt, el tiempo que tarda en vaciarse la tolva llena.", "teorema": {"nombre": "Derivación respecto del tiempo de una relación entre variables", "consigna": "Explicar por qué, si V y h se relacionan por una ecuación y ambas dependen del tiempo, puede derivarse la relación respecto de t, y justificar el procedimiento con la regla de la cadena."}, "capacidades": ["Relacionar razones de cambio mediante una ecuación geométrica", "Interpretar el signo y la variación de una razón de cambio"], "preguntas": [{"c": "dominio", "t": "Explicar qué es una razón de cambio relacionada y por qué la regla de la cadena es su fundamento."}, {"c": "planteo", "t": "Separar variables en (πh²/4)·dh = −0,5·dt e integrar para obtener el tiempo de vaciado desde h = 4 m. ¿Coincide con el cociente entre volumen y caudal?"}, {"c": "planteo", "t": "Expresar el volumen de grano en función de la altura h y calcular dh/dt cuando h = 2 m y cuando h = 1 m."}, {"c": "planteo", "t": "Explicar al operario, con el modelo, por qué el nivel desciende cada vez más rápido aunque la descarga sea constante."}, {"c": "lenguaje", "t": "Escribir el resultado con unidades y signo, e indicar qué significa físicamente el signo negativo."}], "articulacion": {"eje": "1", "t": "Despejar h en función del tiempo a partir de V(h) = V₀ − 0,5t. ¿Qué tipo de función es h(t) y cuál es su dominio con sentido físico?"}, "clave": "r = h/2 ⇒ V = πh³/12; dV/dt = (πh²/4)·dh/dt ⇒ dh/dt = −2/(πh²): −0,159 m/min en h = 2 m y −0,637 m/min en h = 1 m. No es una falla: la sección disminuye. ∫₀⁴ (πh²/4) dh = 16π/3 ≈ 16,76 m³ ⇒ vaciado en ≈ 33,5 min, igual a V/Q. h(t) = (12·(16π/3 − 0,5t)/π)^(1/3), con t ∈ [0; 33,5].", "ref": "Zill, Matemáticas 1, §5.6"}, {"id": "AM-22", "eje": "4", "tipo": "Consigna matemática", "titulo": "Análisis completo de una función polinómica", "temas": ["Valores críticos", "Crecimiento y decrecimiento", "Concavidad y puntos de inflexión", "Gráfica aproximada"], "consigna": "Realizar el análisis completo de f(x) = 3x⁴ − 4x³: dominio, ceros, ordenada al origen, valores críticos, intervalos de crecimiento y decrecimiento, extremos, concavidad, puntos de inflexión y representación gráfica coherente con el análisis. Fundamentar el análisis con f′ y f″, y calcular con una integral definida el área de la región limitada por la gráfica de f y el eje x.", "teorema": {"nombre": "Criterio de la derivada primera", "consigna": "Enunciar el criterio de la derivada primera para extremos relativos y justificarlo a partir de la relación entre el signo de f′ y la monotonía de f."}, "capacidades": ["Realizar el estudio completo de una función y representarla", "Distinguir valores críticos que son extremos de los que no lo son"], "preguntas": [{"c": "dominio", "t": "¿Qué relación hay entre el signo de f′ y la monotonía de f? ¿Qué teorema la fundamenta?"}, {"c": "dominio", "t": "x = 0 es valor crítico. ¿Es extremo? ¿Qué muestra este caso sobre el teorema de Fermat?"}, {"c": "planteo", "t": "Obtener los valores críticos, los intervalos de monotonía y los extremos de f."}, {"c": "planteo", "t": "Analizar la concavidad, obtener los puntos de inflexión y calcular el área entre la gráfica y el eje x en [0, 4/3]."}, {"c": "lenguaje", "t": "Presentar los resultados en un cuadro de signos de f′ y f″ con notación de intervalos."}], "articulacion": {"eje": "7", "t": "Escribir el polinomio de Taylor de grado 2 de f en x = 1 y explicar por qué confirma que allí hay un mínimo."}, "clave": "Ceros x = 0 y x = 4/3. f′ = 12x²(x − 1): críticos 0 y 1; decrece en (−∞, 1) y crece en (1, +∞); mínimo absoluto f(1) = −1; x = 0 no es extremo. f″ = 12x(3x − 2): inflexiones en (0, 0) y (2/3, −16/27). Área = |∫₀^(4/3) f| = 256/405 ≈ 0,632. Taylor en x = 1: −1 + 6·(x − 1)², pues f′(1) = 0 y f″(1) = 12 > 0.", "ref": "Zill, Matemáticas 1, §5.4–5.5"}, {"id": "AM-23", "eje": "4", "tipo": "Consigna matemática", "titulo": "Límites indeterminados", "temas": ["Formas indeterminadas", "Regla de L'Hôpital", "Teorema de Cauchy"], "consigna": "Calcular los límites: (a) lím (eˣ − 1 − x)/x² cuando x → 0; (b) lím x·ln x cuando x → 0⁺; (c) lím (1 + 2/x)ˣ cuando x → +∞; (d) lím (x − sen x)/x³ cuando x → 0; (e) lím (1/x³)·∫₀ˣ sen(t²) dt cuando x → 0. Luego analizar por qué la regla de L'Hôpital no permite calcular lím (x + sen x)/x cuando x → +∞, aunque el límite existe.", "teorema": {"nombre": "Regla de L'Hôpital", "consigna": "Enunciar la regla de L'Hôpital con sus hipótesis, indicar en qué teorema del valor medio se apoya su demostración y explicar qué ocurre cuando el límite del cociente de derivadas no existe."}, "capacidades": ["Reconocer y transformar formas indeterminadas para aplicar L'Hôpital", "Verificar las hipótesis de un teorema antes de aplicarlo"], "preguntas": [{"c": "dominio", "t": "Enumerar las formas indeterminadas. ¿Por qué 0·∞ y 1^∞ deben transformarse antes de aplicar la regla?"}, {"c": "dominio", "t": "Enunciar el teorema de Cauchy y explicar su papel en la demostración de L'Hôpital."}, {"c": "planteo", "t": "Calcular (a), (d) y (e), aplicando la regla las veces necesarias y verificando las hipótesis; en (e), justificar con el teorema fundamental del cálculo integral la derivada del numerador."}, {"c": "planteo", "t": "Calcular (b) y (c) mediante las transformaciones adecuadas."}, {"c": "lenguaje", "t": "Redactar con precisión por qué el último límite no contradice la regla."}], "articulacion": {"eje": "7", "t": "Obtener el límite (a) usando el desarrollo de Maclaurin de eˣ y comparar ambos procedimientos."}, "clave": "(a) 1/2. (b) 0. (c) e². (d) 1/6. lím (x + sen x)/x = 1, pero (1 + cos x)/1 no tiene límite: la regla da una condición suficiente, no necesaria. (e) 1/3: por el teorema fundamental, la derivada del numerador es sen(x²), y sen(x²)/(3x²) → 1/3.", "ref": "Zill, Matemáticas 1, §5.9"}, {"id": "AM-24", "eje": "4", "tipo": "Problema aplicado", "titulo": "Concentración de un medicamento", "temas": ["Extremos absolutos en un intervalo cerrado", "Concavidad y puntos de inflexión", "Asíntota horizontal"], "consigna": "La concentración de un medicamento en sangre, t horas después de su administración, se modela con C(t) = 20t/(t² + 4) mg/L. El médico necesita saber en qué momento la concentración es máxima durante las primeras 6 horas, cuánto vale, y en qué instante la concentración disminuye con mayor rapidez. Obtener C′(t) y C″(t) para responder, y calcular con una integral definida la concentración media durante las primeras 6 horas.", "teorema": {"nombre": "Extremos absolutos de funciones continuas en un intervalo cerrado", "consigna": "Enunciar el teorema que garantiza la existencia de máximo y mínimo absolutos de una función continua en [a, b] y justificar el procedimiento para hallarlos."}, "capacidades": ["Calcular extremos absolutos de una función en un intervalo cerrado", "Interpretar la concavidad y los puntos de inflexión en un modelo"], "preguntas": [{"c": "dominio", "t": "¿Qué hipótesis garantiza la existencia de extremos absolutos? Dar un ejemplo en que falla y no hay máximo."}, {"c": "planteo", "t": "Calcular la concentración media (1/6)·∫₀⁶ C(t) dt por sustitución. ¿En qué instantes la concentración iguala ese valor y qué teorema garantiza que exista al menos uno?"}, {"c": "planteo", "t": "Derivar C y hallar sus extremos absolutos en [0, 6]."}, {"c": "planteo", "t": "Determinar el punto de inflexión e interpretarlo como el instante de descenso más rápido."}, {"c": "lenguaje", "t": "Redactar la respuesta al médico con unidades y precisión adecuada."}], "articulacion": {"eje": "2", "t": "Calcular lím C(t) cuando t → +∞ e interpretar la asíntota en el contexto."}, "clave": "C′ = 20(4 − t²)/(t² + 4)²: máximo absoluto C(2) = 5 mg/L; mínimo absoluto C(0) = 0; C(6) = 3 mg/L. C″ = −40t(12 − t²)/(t² + 4)³: inflexión en t = √12 ≈ 3,46 h. Asíntota horizontal C = 0. Media en [0, 6]: (1/6)·10·ln(40/4) = (5/3)·ln 10 ≈ 3,84 mg/L, alcanzada en t ≈ 0,94 h y t ≈ 4,28 h.", "ref": "Zill, Matemáticas 1, §5.2 y §5.5"}, {"id": "AM-47", "eje": "4", "origen": "T-03", "tipo": "Problema aplicado", "titulo": "Límite de una tasa de transferencia", "temas": ["Formas indeterminadas", "Regla de L'Hôpital", "Límite notable", "Teorema fundamental"], "consigna": "La tasa de transferencia de un enlace óptico se modela cerca de x = 0 con R(x) = sen(3x)/(x·cos x), donde x es la frecuencia normalizada de la señal. Analizar la indeterminación de R en x = 0 y calcular su límite con el límite notable de sen u/u y con la regla de L'Hôpital; estudiar el comportamiento de R cuando x → (π/2)⁻. Calcular además lím (1/x²)·∫₀ˣ sen(3t) dt cuando x → 0.", "teorema": {"nombre": "Regla de L'Hôpital", "consigna": "Enunciar la regla de L'Hôpital con sus hipótesis y verificarlas en el cálculo de lím R(x) cuando x → 0."}, "capacidades": ["Resolver indeterminaciones por límites notables y por derivación", "Combinar el teorema fundamental con la regla de L'Hôpital"], "preguntas": [{"c": "dominio", "t": "Explicar las condiciones de aplicabilidad de la regla de L'Hôpital. ¿Por qué no se aplica al límite de R cuando x → π/2?"}, {"c": "dominio", "t": "Demostrar con el teorema de intercalación que sen(x)/x → 1 cuando x → 0."}, {"c": "planteo", "t": "Calcular lím R(x) cuando x → 0 por los dos caminos y comparar. ¿Qué valor debe asignarse a R(0) para que sea continua?"}, {"c": "planteo", "t": "Calcular lím (1/x²)·∫₀ˣ sen(3t) dt con el teorema fundamental y la regla de L'Hôpital, y verificarlo calculando la integral."}, {"c": "lenguaje", "t": "Escribir con notación correcta el comportamiento de R cuando x → (π/2)⁻."}], "articulacion": {"eje": "7", "t": "Usar los desarrollos de Maclaurin de sen(3x) y de cos x para obtener R(x) ≈ 3 + a·x² cerca de 0. ¿Qué indica el coeficiente a?"}, "clave": "lím R = lím [3·sen(3x)/(3x)]·[1/cos x] = 3; por L'Hôpital, 3·cos(3x)/(cos x − x·sen x) → 3. Se redefine R(0) = 3. Si x → (π/2)⁻, el numerador tiende a −1 y x·cos x → 0⁺: R → −∞. lím (1 − cos 3x)/(3x²) = 3/2. Maclaurin: R ≈ 3 − 3x² (máximo local en 0).", "ref": ""}, {"id": "AM-48", "eje": "4", "origen": "T-05", "tipo": "Problema aplicado", "titulo": "Depósito cilíndrico de costo mínimo", "temas": ["Optimización", "Criterio de la derivada segunda", "Integral definida"], "consigna": "Se proyecta un depósito cilíndrico cerrado de 10 m³. La chapa de las bases cuesta $150/m² y la lateral, $100/m². Plantear el costo total C(r) en función del radio y determinar con derivadas las dimensiones que lo minimizan, verificando con el criterio de la derivada segunda que el mínimo es absoluto. Luego, si el costo de la chapa lateral aumenta con la altura según p(y) = 100 + 10y $/m² por el uso de andamios, calcular con una integral el nuevo costo de la pared del depósito óptimo.", "teorema": {"nombre": "Teorema de Fermat", "consigna": "Enunciar el teorema de Fermat sobre extremos locales y justificar por qué el radio óptimo anula C′(r)."}, "capacidades": ["Modelar un problema de diseño con una función de una variable y optimizarla", "Integrar un costo que varía con la posición"], "preguntas": [{"c": "dominio", "t": "Enunciar el teorema de Rolle y explicar su relación con el teorema del valor medio de Lagrange."}, {"c": "dominio", "t": "¿Por qué C″(r) > 0 en todo r > 0, junto con el comportamiento de C en los extremos del dominio, asegura un mínimo absoluto?"}, {"c": "planteo", "t": "Obtener r, h y el costo mínimo. ¿Qué relación h/r resulta y cómo depende de la razón entre los precios?"}, {"c": "planteo", "t": "Plantear el costo de la pared con p(y) como ∫₀ʰ 2πr·p(y) dy y calcularlo para el depósito óptimo. ¿Sigue siendo óptimo el mismo radio?"}, {"c": "lenguaje", "t": "Presentar la especificación del depósito con dimensiones redondeadas y el costo estimado."}], "articulacion": {"eje": "2", "t": "Calcular lím C(r) cuando r → 0⁺ y cuando r → +∞. ¿Qué indican sobre la existencia del mínimo?"}, "clave": "C(r) = 300πr² + 2 000/r; C′ = 600πr − 2 000/r² = 0 ⇔ r = (10/(3π))^(1/3) ≈ 1,02 m; h ≈ 3,06 m = 3r (h/r = 2·150/100). C_mín ≈ $2 941. C″ = 600π + 4 000/r³ > 0. Con p(y): ∫₀ʰ 2πr·(100 + 10y) dy = 2πr·(100h + 5h²) ≈ $2 261, frente a $1 961: el óptimo se desplaza hacia depósitos más bajos. C → +∞ en ambos extremos.", "ref": ""}, {"id": "AM-49", "eje": "4", "origen": "T-06", "tipo": "Problema aplicado", "titulo": "Vaciado de un depósito cónico", "temas": ["Razones de cambio relacionadas", "Regla de la cadena", "Volumen por secciones"], "consigna": "Un depósito cónico con el vértice hacia abajo, de radio superior R = 4 m y altura H = 10 m, pierde agua por una fisura en el vértice a razón constante de 0,5 m³/min. Obtener el volumen de agua V(h) como integral de las secciones horizontales, ∫₀ʰ π·r(y)² dy, usando semejanza de triángulos, y calcular con la regla de la cadena la velocidad con que baja el nivel cuando h = 3 m. Calcular también cuánto tarda en vaciarse desde ese nivel.", "teorema": {"nombre": "Regla de la cadena", "consigna": "Enunciar la regla de la cadena y justificar con ella la relación entre dV/dt y dh/dt."}, "capacidades": ["Relacionar tasas de variación de magnitudes vinculadas", "Obtener un volumen como integral de secciones"], "preguntas": [{"c": "dominio", "t": "¿Cuál es la interpretación geométrica de la derivada en un punto? ¿Qué representa dh/dt en la gráfica de h(t)?"}, {"c": "dominio", "t": "¿Por qué el volumen de una capa delgada es aproximadamente π·r(y)²·dy? ¿Qué justifica pasar de la suma de capas a la integral?"}, {"c": "planteo", "t": "Obtener V(h) y dh/dt cuando h = 3 m y cuando h = 1 m. ¿Por qué el nivel baja cada vez más rápido?"}, {"c": "planteo", "t": "Calcular el tiempo de vaciado desde h = 3 m y desde el depósito lleno."}, {"c": "lenguaje", "t": "Escribir los resultados con unidades y signo, e interpretar el signo negativo."}], "articulacion": {"eje": "5", "t": "Si la pérdida por la fisura dependiera del nivel, dV/dt = −c·√h, ¿qué ecuación diferencial cumpliría h? Clasificarla."}, "clave": "r = 0,4h; V(h) = ∫₀ʰ π·(0,4y)² dy = 0,16πh³/3. dV/dt = 0,16πh²·dh/dt ⇒ dh/dt = −0,5/(0,16πh²): ≈ −0,111 m/min en h = 3 m y ≈ −0,995 m/min en h = 1 m. Vaciado: V(3)/0,5 ≈ 9,0 min; lleno, V(10) ≈ 167,6 m³ ⇒ ≈ 335 min. Con dV/dt = −c·√h: h^(3/2)·dh/dt = −c/(0,16π), de primer orden y variables separables.", "ref": ""}, {"id": "AM-50", "eje": "4", "origen": "T-07", "tipo": "Problema aplicado", "titulo": "Trayectoria de un vehículo autónomo", "temas": ["Monotonía y extremos", "Concavidad", "Teorema de Lagrange", "Área entre curvas"], "consigna": "La trayectoria de prueba de un vehículo autónomo, vista en planta, sigue y(x) = x³ − 6x² + 9x + 2, con x e y en decenas de metros y 0 ≤ x ≤ 4. Hallar con y′ los puntos críticos, los intervalos de monotonía y los extremos relativos, y con y″ la concavidad y el punto de inflexión. Calcular con una integral definida la ordenada media de la trayectoria en [0, 3] y compararla con la ordenada del punto de inflexión.", "teorema": {"nombre": "Teorema del valor medio de Lagrange", "consigna": "Enunciar el teorema de Lagrange con sus hipótesis y aplicarlo a y(x) en [0, 3]: ¿qué punto c garantiza?"}, "capacidades": ["Realizar el análisis completo de una función polinómica", "Interpretar el valor medio de una función en un contexto"], "preguntas": [{"c": "dominio", "t": "¿Qué condición necesaria y qué condición suficiente garantizan un punto de inflexión en una función dos veces derivable?"}, {"c": "dominio", "t": "¿Por qué en [0, 3] el punto de Lagrange coincide con un punto crítico? ¿Qué caso particular del teorema se obtiene?"}, {"c": "planteo", "t": "Obtener extremos relativos, monotonía, concavidad e inflexión, y representar la trayectoria."}, {"c": "planteo", "t": "Calcular la ordenada media en [0, 3] y el área entre la trayectoria y la recta y = 2 en ese intervalo."}, {"c": "lenguaje", "t": "Presentar los resultados en un cuadro de signos de y′ e y″."}], "articulacion": {"eje": "1", "t": "Factorizar y(x) − 2 y explicar qué indica la multiplicidad de la raíz x = 3 sobre la gráfica."}, "clave": "y′ = 3(x − 1)(x − 3): crece en (0, 1) y (3, 4), decrece en (1, 3); máximo relativo (1, 6), mínimo relativo (3, 2). y″ = 6x − 12: inflexión en (2, 4). y(0) = y(3) = 2 ⇒ Rolle: c = 1. Media en [0, 3]: 12,75/3 = 4,25. y − 2 = x·(x − 3)²: raíz doble en x = 3 (tangencia); área ∫₀³ x·(x − 3)² dx = 27/4.", "ref": ""}, {"id": "AM-25", "eje": "5", "tipo": "Problema aplicado", "titulo": "Volumen entregado en un turno de riego", "temas": ["Sumas de Riemann", "Integral definida", "Interpretación geométrica"], "consigna": "Durante un turno de riego se registra cada hora el caudal que ingresa a una finca: en t = 0, 1, 2, 3, 4, 5 y 6 h, los caudales son 0, 120, 200, 240, 220, 150 y 80 L/s. Hay que informar el volumen total entregado, y el productor cuestiona el método de cálculo. Estimar además, con cocientes incrementales, la tasa de variación del caudal a las 2 h y a las 5 h, e indicar en qué momento del turno el caudal es aproximadamente máximo.", "teorema": {"nombre": "Integrabilidad de las funciones continuas", "consigna": "Definir la integral definida como límite de sumas de Riemann, enunciar que toda función continua en [a, b] es integrable y justificar por qué el volumen entregado es ∫ Q(t) dt."}, "capacidades": ["Aproximar una integral definida a partir de datos tabulados", "Interpretar la integral de una tasa como cantidad acumulada"], "preguntas": [{"c": "dominio", "t": "Definir suma de Riemann y explicar qué ocurre con ella cuando la norma de la partición tiende a cero."}, {"c": "dominio", "t": "¿Por qué el volumen es el área bajo la curva Q(t)? ¿Qué unidades tiene esa «área»?"}, {"c": "planteo", "t": "Calcular el volumen con sumas por izquierda, por derecha y con la regla del trapecio. ¿Cuál conviene informar?"}, {"c": "planteo", "t": "Estimar Q′(2) y Q′(5) con cocientes incrementales centrados. ¿Qué indica el cambio de signo de Q′ sobre el caudal máximo del turno?"}, {"c": "lenguaje", "t": "Redactar el resultado con unidades y criterio de redondeo, como figuraría en el informe del turno."}], "articulacion": {"eje": "3", "t": "El caudal es la derivada del volumen acumulado respecto del tiempo. ¿En qué intervalo creció más rápido el volumen y cómo se refleja en la gráfica del volumen acumulado?"}, "clave": "Con Δt = 3 600 s: izquierda 3 348 m³; derecha 3 636 m³; trapecio 3 492 m³. Si Q es creciente, la suma por izquierda subestima y la suma por derecha sobreestima. Q′(2) ≈ (240 − 120)/2 = 60 L/s por hora; Q′(5) ≈ (80 − 220)/2 = −70 L/s por hora. Q′ cambia de signo cerca de t = 3 h: caudal máximo ≈ 240 L/s.", "ref": ""}, {"id": "AM-26", "eje": "5", "tipo": "Problema aplicado", "titulo": "Llenado de un tanque pulmón", "temas": ["Teorema fundamental del cálculo", "Regla de Barrow", "Función integral", "Primitivas"], "consigna": "Un tanque pulmón de una planta potabilizadora recibe un caudal que varía a lo largo del día según Q(t) = 2 + sen(πt/12) m³/h, con t en horas desde la medianoche. Sin extracción, el volumen almacenado es V(x) = 30 + ∫₀ˣ Q(t) dt, en m³, donde 30 m³ es el volumen inicial. Obtener V′(x) a partir del teorema fundamental y calcular el volumen almacenado al cabo de 24 horas.", "teorema": {"nombre": "Teorema fundamental del cálculo integral", "consigna": "Enunciar las dos partes del teorema fundamental del cálculo con sus hipótesis y justificar por qué V′(x) = Q(x)."}, "capacidades": ["Interpretar una función definida por una integral y derivarla mediante el teorema fundamental", "Calcular integrales definidas con la regla de Barrow"], "preguntas": [{"c": "dominio", "t": "¿Qué afirma la primera parte del teorema fundamental y qué afirma la regla de Barrow? ¿Por qué son resultados distintos?"}, {"c": "dominio", "t": "¿Por qué la continuidad de Q es hipótesis del teorema? ¿Qué ocurriría con V′ si el caudal tuviera un salto?"}, {"c": "planteo", "t": "Calcular V(24) con la regla de Barrow e interpretar por qué el término senoidal no aporta volumen neto en 24 h."}, {"c": "planteo", "t": "Sin calcular V(x) explícitamente, determinar dónde crece V y dónde cambia su concavidad."}, {"c": "lenguaje", "t": "Expresar V(x) en forma explícita y describir con precisión la diferencia entre caudal y volumen acumulado."}], "articulacion": {"eje": "4", "t": "¿En qué instante es máxima la tasa de llenado y qué representa ese instante en la gráfica de V(x)?"}, "clave": "V(x) = 30 + 2x + (12/π)·(1 − cos(πx/12)); V(24) = 78 m³. V crece siempre (Q ≥ 1). Inflexiones de V en t = 6 h (tasa máxima) y t = 18 h (tasa mínima).", "ref": ""}, {"id": "AM-27", "eje": "5", "tipo": "Problema aplicado", "titulo": "Vaciado de un tanque por un orificio", "temas": ["Ecuaciones diferenciales a variables separables", "Primitivas", "Condición inicial", "Solución general y particular"], "consigna": "Un tanque cilíndrico de agua se vacía por un orificio en el fondo. Según la ley de Torricelli, la altura del agua cumple dh/dt = −k·√h, con k = 0,02 m^(1/2)/min y h(0) = 4 m. El encargado de mantenimiento necesita saber cuándo podrá ingresar al tanque para limpiarlo. Integrar la ecuación para obtener h(t) y calcular la velocidad de descenso del nivel a los 100 min.", "teorema": {"nombre": "Primitivas de una misma función", "consigna": "Enunciar y demostrar, a partir del teorema de Lagrange, que dos primitivas de una misma función en un intervalo difieren en una constante, y justificar su papel en la obtención de la solución particular."}, "capacidades": ["Resolver una ecuación diferencial a variables separables con condición inicial", "Interpretar la solución general y la solución particular de un modelo"], "preguntas": [{"c": "dominio", "t": "Verificar por derivación que h(t) satisface la ecuación y calcular dh/dt a los 100 min. ¿Por qué la velocidad de descenso disminuye?"}, {"c": "dominio", "t": "¿Por qué la integral indefinida incluye una constante arbitraria? ¿Qué teorema lo garantiza?"}, {"c": "planteo", "t": "Separar variables, integrar y obtener h(t) con la condición inicial. ¿En qué instante se vacía el tanque?"}, {"c": "planteo", "t": "¿En qué intervalo tiene sentido físico la solución? ¿Qué ocurre si se la evalúa después del vaciado?"}, {"c": "lenguaje", "t": "Escribir el procedimiento de separación de variables con notación correcta, indicando dónde interviene cada hipótesis."}], "articulacion": {"eje": "2", "t": "¿Es derivable √h en h = 0? ¿Qué dice eso sobre la velocidad de descenso del nivel en el instante final?"}, "clave": "2√h = 4 − 0,02t ⇒ h(t) = (2 − 0,01t)², válida en [0, 200] min. El tanque se vacía a los 200 min (3 h 20 min). Fuera de ese intervalo la fórmula vuelve a crecer y carece de sentido físico. h(100) = 1 m; dh/dt = −0,02·√1 = −0,02 m/min, menor en módulo que al inicio (−0,04 m/min).", "ref": ""}, {"id": "AM-28", "eje": "5", "tipo": "Consigna matemática", "titulo": "Métodos de integración", "temas": ["Integración por partes", "Sustitución", "Fracciones simples", "Integrales trigonométricas"], "consigna": "Calcular: (a) ∫ x·eˣ dx; (b) ∫ x/(x² + 1) dx; (c) ∫ (5x + 1)/((x − 1)(x + 2)) dx; (d) ∫ sen²x dx. Justificar en cada caso la elección del método y verificar los resultados por derivación.", "teorema": {"nombre": "Fórmula de integración por partes", "consigna": "Deducir la fórmula ∫ u dv = u·v − ∫ v du a partir de la regla de derivación del producto y explicar el criterio para elegir u y dv."}, "capacidades": ["Seleccionar y aplicar el método de integración adecuado a cada integrando", "Verificar una primitiva mediante derivación"], "preguntas": [{"c": "dominio", "t": "¿Qué es una primitiva? ¿Por qué el resultado de cada integral indefinida incluye una constante?"}, {"c": "dominio", "t": "Deducir la fórmula de integración por partes. ¿Qué ocurre en (a) si se eligen u = eˣ y dv = x dx?"}, {"c": "planteo", "t": "Resolver (b) por sustitución y (c) por descomposición en fracciones simples."}, {"c": "planteo", "t": "Resolver (d) con la identidad sen²x = (1 − cos 2x)/2 y verificar el resultado derivando."}, {"c": "lenguaje", "t": "Escribir el cambio de variable de (b) con notación completa, incluido el diferencial."}], "articulacion": {"eje": "6", "t": "Usar el resultado de (d) para calcular el área bajo y = sen²x entre 0 y π, e interpretar el valor obtenido."}, "clave": "(a) eˣ·(x − 1) + C. (b) ½·ln(x² + 1) + C. (c) 2·ln|x − 1| + 3·ln|x + 2| + C. (d) x/2 − sen(2x)/4 + C. Área en [0, π]: π/2.", "ref": ""}, {"id": "AM-29", "eje": "5", "tipo": "Consigna matemática", "titulo": "Función integral y valor medio", "temas": ["Teorema fundamental del cálculo", "Teorema del valor medio del cálculo integral", "Función integral", "Regla de la cadena"], "consigna": "Dadas f(x) = x² en [0, 3], G(x) = ∫₀ˣ (t² − 4) dt y F(x) = ∫₁^(x²) √(1 + t³) dt: calcular el valor medio de f en [0, 3] y el punto c donde f lo alcanza; hallar los extremos relativos de G sin calcular la integral; y obtener F′(x).", "teorema": {"nombre": "Teorema del valor medio del cálculo integral", "consigna": "Enunciar el teorema del valor medio del cálculo integral con sus hipótesis, interpretarlo geométricamente y aplicarlo a f en [0, 3]."}, "capacidades": ["Calcular el valor medio de una función y su interpretación geométrica", "Derivar funciones definidas por integrales con límites variables"], "preguntas": [{"c": "dominio", "t": "Interpretar el teorema del valor medio del cálculo integral como un rectángulo de área equivalente. ¿Qué hipótesis garantiza el punto c?"}, {"c": "dominio", "t": "¿Qué afirma el teorema fundamental sobre G(x)? ¿Por qué permite hallar sus extremos sin integrar?"}, {"c": "planteo", "t": "Calcular el valor medio de f en [0, 3] y el punto c."}, {"c": "planteo", "t": "Hallar los extremos relativos de G y obtener F′(x) combinando el teorema fundamental con la regla de la cadena."}, {"c": "lenguaje", "t": "Escribir F′(x) e indicar con notación correcta en qué paso interviene cada resultado."}], "articulacion": {"eje": "4", "t": "Clasificar los extremos de G con el criterio de la derivada segunda."}, "clave": "Valor medio de f: (1/3)·∫₀³ x² dx = 3; c = √3. G′(x) = x² − 4: máximo relativo en x = −2 y mínimo relativo en x = 2 (G″ = 2x). F′(x) = 2x·√(1 + x⁶).", "ref": ""}, {"id": "AM-30", "eje": "5", "tipo": "Problema aplicado", "titulo": "Crecimiento de un cultivo de levaduras", "temas": ["Ecuaciones diferenciales", "Problema de valor inicial", "Función exponencial", "Separación de variables"], "consigna": "En el laboratorio de una bodega, un cultivo de levaduras crece a una velocidad proporcional a su tamaño: dN/dt = k·N. Al inicio hay 2 millones de células y a las 3 horas, 5 millones. Para inocular un tanque se necesitan 50 millones de células. Calcular con una integral definida el tamaño medio del cultivo durante las primeras 3 horas y la velocidad de crecimiento a las 3 horas.", "teorema": {"nombre": "Soluciones de la ecuación y′ = k·y", "consigna": "Demostrar que toda solución de y′ = k·y es de la forma y = C·e^(kx), analizando la derivada de y·e^(−kx), y justificar cómo la condición inicial determina C."}, "capacidades": ["Resolver un problema de valor inicial y calibrar el modelo con un dato", "Interpretar parámetros de un modelo de crecimiento exponencial"], "preguntas": [{"c": "dominio", "t": "Clasificar la ecuación y explicar qué es un problema de valor inicial."}, {"c": "dominio", "t": "¿Por qué la derivada de y·e^(−kx) igual a cero implica que esa función es constante? ¿Qué teorema se usa?"}, {"c": "planteo", "t": "Resolver separando variables e integrando, calcular k y el tamaño medio del cultivo en [0, 3] con la integral definida."}, {"c": "planteo", "t": "Calcular el tiempo de duplicación, el instante en que se alcanzan 50 millones y la velocidad de crecimiento dN/dt a las 3 h."}, {"c": "articulacion", "t": "¿Qué limitación tiene el modelo para tiempos largos? ¿Qué tipo de función describiría un crecimiento que se estabiliza?"}], "articulacion": {"eje": "1", "t": "Despejar t en función de N y explicar qué propiedades del logaritmo se usan."}, "clave": "N(t) = 2·e^(kt) con k = ln(2,5)/3 ≈ 0,305 h⁻¹. Duplicación: ln 2/k ≈ 2,27 h. N = 50 ⇔ t = ln 25/k ≈ 10,5 h. Para tiempos largos conviene un modelo con techo (logístico). dN/dt(3) = 5k ≈ 1,53 millones/h. Tamaño medio en [0, 3]: (1/3)·∫₀³ 2e^(kt) dt = (2/(3k))·(2,5 − 1) = 1/k ≈ 3,27 millones.", "ref": ""}, {"id": "AM-51", "eje": "5", "origen": "T-12", "tipo": "Problema aplicado", "titulo": "Energía consumida por un parque industrial", "temas": ["Teorema fundamental del cálculo", "Función integral", "Valor medio", "Regla de Barrow"], "consigna": "La potencia consumida por un parque industrial varía a lo largo del día según P(t) = 10 + 4·cos(πt/12) MW, con t en horas desde la medianoche. Calcular la energía consumida en el día como ∫₀²⁴ P(t) dt y la potencia media. Obtener la energía acumulada E(t) = ∫₀ᵗ P(s) ds, derivarla y determinar con P′(t) en qué hora la demanda cae más rápido.", "teorema": {"nombre": "Teorema fundamental del cálculo integral", "consigna": "Enunciar el teorema con sus hipótesis y aplicarlo para justificar que E′(t) = P(t)."}, "capacidades": ["Interpretar la integral de una potencia como energía acumulada", "Derivar una función definida por una integral"], "preguntas": [{"c": "dominio", "t": "Justificar por qué toda función continua en un intervalo cerrado es integrable y por qué P lo es."}, {"c": "dominio", "t": "Explicar la derivación de una función integral con límite superior variable, d/dx ∫ₐ^(g(x)) f(t) dt, y deducirla de la regla de la cadena."}, {"c": "planteo", "t": "Calcular la energía diaria, la potencia media y E(t) en forma explícita."}, {"c": "planteo", "t": "Calcular P′(t) y la hora de máxima caída de la demanda. ¿Dónde tiene E un punto de inflexión?"}, {"c": "lenguaje", "t": "Expresar la energía en MWh y en GJ y explicar con precisión la diferencia entre potencia y energía."}], "articulacion": {"eje": "7", "t": "P es periódica. ¿Qué período tiene y cómo se relaciona su expresión con un término de una serie de Fourier?"}, "clave": "E = ∫₀²⁴ (10 + 4·cos(πt/12)) dt = 240 MWh (864 GJ); potencia media 10 MW. E(t) = 10t + (48/π)·sen(πt/12); E′ = P. P′(t) = −(π/3)·sen(πt/12): caída máxima a las 6 h, ≈ −1,05 MW/h. Inflexión de E en t = 12 h (mínimo de P). Período 24 h.", "ref": ""}, {"id": "AM-52", "eje": "5", "origen": "T-16", "tipo": "Problema aplicado", "titulo": "Enfriamiento de piezas fundidas", "temas": ["Ecuaciones diferenciales de variables separables", "Problema de valor inicial", "Valor medio"], "consigna": "Una pieza fundida sale del horno a 300 °C y se coloca en un taller a 20 °C. La tasa de enfriamiento es proporcional a la diferencia de temperatura: dT/dt = −k·(T − 20). Clasificar la ecuación, resolverla integrando por separación de variables con T(0) = 300 °C y determinar k sabiendo que a los 10 minutos la pieza está a 160 °C. Calcular la velocidad de enfriamiento inicial, el instante en que la pieza puede manipularse a 50 °C y, con una integral definida, la temperatura media durante los primeros 30 minutos.", "teorema": {"nombre": "Separación de variables y problema de valor inicial", "consigna": "Definir solución general, solución particular y problema de valor inicial, y justificar el método de separación de variables mediante la regla de la cadena."}, "capacidades": ["Resolver un problema de valor inicial de primer orden", "Interpretar la derivada y la integral de la solución en el contexto"], "preguntas": [{"c": "dominio", "t": "Clasificar la ecuación (orden, linealidad) y explicar qué condición determina la constante de integración."}, {"c": "dominio", "t": "¿Por qué T(t) = 20 es solución de la ecuación? ¿Qué representa y por qué la solución del problema nunca la alcanza?"}, {"c": "planteo", "t": "Obtener T(t), k y el instante en que T = 50 °C."}, {"c": "planteo", "t": "Calcular T′(0) y la temperatura media en [0, 30] con la integral definida."}, {"c": "lenguaje", "t": "Escribir el procedimiento de separación de variables con notación correcta, incluidos los diferenciales y la constante."}], "articulacion": {"eje": "2", "t": "Calcular lím T(t) cuando t → +∞ e interpretar la asíntota horizontal."}, "clave": "T(t) = 20 + 280·e^(−kt); 140 = 280·e^(−10k) ⇒ k = ln 2/10 ≈ 0,0693 min⁻¹ (la diferencia se reduce a la mitad cada 10 min). T′(0) = −280k ≈ −19,4 °C/min. T = 50 °C en t = ln(28/3)/k ≈ 32,2 min. Media en [0, 30]: 20 + 280·(1 − 1/8)/(3·ln 2) ≈ 137,8 °C. lím T = 20 °C.", "ref": ""}, {"id": "AM-53", "eje": "5", "origen": "T-17", "tipo": "Problema aplicado", "titulo": "Respuesta de un circuito RL", "temas": ["Ecuaciones diferenciales de primer orden", "Constante de tiempo", "Integral definida"], "consigna": "Un circuito serie RL con R = 10 Ω, L = 2 H y una fuente de continua V₀ = 100 V cumple L·di/dt + R·i = V₀, con i(0) = 0. Clasificar la ecuación, resolverla por separación de variables y calcular la corriente de régimen. Calcular la velocidad inicial de crecimiento de la corriente y la carga que atraviesa el circuito en el primer segundo, q = ∫₀¹ i(t) dt.", "teorema": {"nombre": "Primitivas de una misma función", "consigna": "Enunciar que dos primitivas de una misma función en un intervalo difieren en una constante y justificar con ello la solución general de la ecuación."}, "capacidades": ["Resolver una ecuación diferencial lineal de coeficientes constantes por separación de variables", "Interpretar la derivada y la integral de la corriente"], "preguntas": [{"c": "dominio", "t": "Clasificar la ecuación. ¿Por qué, con V₀ constante, puede resolverse por separación de variables?"}, {"c": "dominio", "t": "¿Cómo afecta la constante de tiempo τ = L/R a la velocidad de respuesta? Interpretarla con la recta tangente a i(t) en t = 0."}, {"c": "planteo", "t": "Obtener i(t), la corriente de régimen y el instante en que i alcanza el 95 % de ese valor."}, {"c": "planteo", "t": "Calcular di/dt en t = 0 y la carga del primer segundo, q = ∫₀¹ i(t) dt."}, {"c": "lenguaje", "t": "Expresar τ, la corriente de régimen y la carga con unidades del SI."}], "articulacion": {"eje": "7", "t": "Desarrollar e^(−5t) en serie de Maclaurin y obtener una aproximación polinómica de i(t) para t pequeño."}, "clave": "i(t) = (V₀/R)·(1 − e^(−Rt/L)) = 10·(1 − e^(−5t)) A; τ = 0,2 s; régimen 10 A; 95 % en t = ln 20/5 ≈ 0,60 s. di/dt(0) = V₀/L = 50 A/s: la tangente en 0 alcanza 10 A en t = τ. q = 10·(1 − (1 − e^(−5))/5) ≈ 8,01 C. Maclaurin: i ≈ 50t − 125t².", "ref": ""}, {"id": "AM-54", "eje": "5", "origen": "T-18", "tipo": "Problema aplicado", "titulo": "Balance de sal en un tanque de mezcla", "temas": ["Ecuaciones diferenciales de variables separables", "Regla de Barrow", "Balance de masa"], "consigna": "Un tanque contiene 500 L de salmuera con 10 kg de sal disuelta. Ingresa agua pura a 5 L/min y la mezcla homogénea sale al mismo caudal. Plantear la ecuación dQ/dt = tasa de entrada − tasa de salida para la masa de sal Q(t), resolverla integrando por separación de variables y calcular el tiempo en que la sal se reduce a la mitad. Calcular la velocidad inicial de pérdida de sal y la masa que sale en la primera hora como ∫₀⁶⁰ (5·Q(t)/500) dt.", "teorema": {"nombre": "Regla de Barrow", "consigna": "Enunciar la regla de Barrow y justificar con ella que la sal que sale en [0, 60] es Q(0) − Q(60)."}, "capacidades": ["Plantear un balance de masa como ecuación diferencial", "Relacionar la integral de una tasa con la variación de la cantidad"], "preguntas": [{"c": "dominio", "t": "Explicar la diferencia entre una ecuación diferencial homogénea y una no homogénea. ¿De qué tipo es esta?"}, {"c": "dominio", "t": "Justificar la validez del método de separación de variables. ¿Qué ocurre con la división por Q si Q = 0?"}, {"c": "planteo", "t": "Obtener Q(t) y el tiempo en que la sal se reduce a la mitad."}, {"c": "planteo", "t": "Calcular Q′(0) y la sal que sale en la primera hora, por integración y por diferencia Q(0) − Q(60)."}, {"c": "lenguaje", "t": "Escribir el balance de masa con unidades en cada término."}], "articulacion": {"eje": "1", "t": "Despejar t de Q(t) = q con logaritmos y explicar por qué el tiempo de reducción a la mitad no depende de la masa inicial."}, "clave": "dQ/dt = −5·Q/500 = −Q/100; Q(t) = 10·e^(−t/100) kg. Mitad en t = 100·ln 2 ≈ 69,3 min. Q′(0) = −0,1 kg/min. Sal que sale en 60 min: ∫₀⁶⁰ 0,1·e^(−t/100) dt = 10·(1 − e^(−0,6)) ≈ 4,51 kg = Q(0) − Q(60). t(q) = 100·ln(10/q).", "ref": ""}, {"id": "AM-55", "eje": "5", "origen": "T-19", "tipo": "Problema aplicado", "titulo": "Drenaje de un depósito por un orificio", "temas": ["Ecuaciones diferenciales de variables separables", "Valor medio", "Integral definida"], "consigna": "Un depósito cilíndrico de sección A_T con un orificio de área A_o en el fondo se vacía según dh/dt = −(A_o/A_T)·√(2gh). Separar variables e integrar para obtener h(t) y el tiempo de vaciado desde una altura H₀; aplicar a A_o/A_T = 0,01, H₀ = 2 m y g = 9,8 m/s², calculando la velocidad inicial de descenso del nivel y la altura media durante el vaciado. Plantear la integral que da el tiempo de vaciado si la sección variara con la altura, A_T(h).", "teorema": {"nombre": "Teorema del valor medio del cálculo integral", "consigna": "Enunciar el teorema y aplicarlo a h(t) en [0, t_f]: ¿en qué instante el nivel iguala su altura media?"}, "capacidades": ["Resolver una ecuación diferencial no lineal de variables separables", "Plantear un tiempo de vaciado como integral"], "preguntas": [{"c": "dominio", "t": "Clasificar la ecuación. ¿Por qué h = 0 también la satisface y qué significa físicamente?"}, {"c": "dominio", "t": "¿Es derivable √h en h = 0? ¿Qué consecuencia tiene sobre la velocidad de descenso al final del vaciado?"}, {"c": "planteo", "t": "Obtener h(t), el tiempo de vaciado y dh/dt en t = 0 para los datos numéricos."}, {"c": "planteo", "t": "Calcular la altura media en [0, t_f], el instante en que el nivel la iguala, y plantear el tiempo de vaciado con A_T(h)."}, {"c": "lenguaje", "t": "Escribir la separación de variables con notación correcta y con los límites de integración."}], "articulacion": {"eje": "6", "t": "Si el depósito fuera cónico con el vértice hacia abajo, ¿cómo se expresaría A_T(h) y cómo se calcularía su volumen con una integral?"}, "clave": "2√h = 2√H₀ − (A_o/A_T)·√(2g)·t ⇒ h(t) = H₀·(1 − t/t_f)², con t_f = (A_T/A_o)·√(2H₀/g) ≈ 63,9 s. dh/dt(0) = −0,01·√(2·9,8·2) ≈ −0,063 m/s. Altura media H₀/3 ≈ 0,67 m, alcanzada en t = t_f·(1 − 1/√3) ≈ 27,0 s. Sección variable: t_f = (1/(A_o·√(2g)))·∫₀^H₀ A_T(h)·h^(−1/2) dh. h ≡ 0 también es solución: depósito vacío.", "ref": ""}, {"id": "AM-31", "eje": "6", "tipo": "Problema aplicado", "titulo": "Fondo de un silo de granos", "temas": ["Volumen de sólidos de revolución", "Método de los discos", "Integral definida"], "consigna": "Un fabricante de silos ofrece un fondo en forma de paraboloide, generado al rotar alrededor del eje y la curva y = x²/2 para 0 ≤ y ≤ 2 (en metros), apoyado sobre un cuerpo cilíndrico de 2 m de radio. El comprador quiere saber cuánto grano entra en el fondo y compararlo con un fondo cónico de igual radio y profundidad. Calcular por integración el volumen de cada fondo y, si el fondo se llena con un caudal constante Q, calcular la velocidad de ascenso del nivel en función de la altura.", "teorema": {"nombre": "Volumen por secciones transversales", "consigna": "Justificar la fórmula V = ∫ A(y) dy como límite de sumas de Riemann de volúmenes de discos y enunciar las hipótesis sobre A(y)."}, "capacidades": ["Plantear el volumen de un sólido de revolución por el método de los discos", "Comparar recipientes de distinta forma mediante cálculo integral"], "preguntas": [{"c": "dominio", "t": "Explicar el procedimiento de partir el sólido, aproximar cada parte, sumar y pasar al límite que fundamenta la fórmula de volumen."}, {"c": "dominio", "t": "¿Por qué conviene integrar respecto de y en este caso?"}, {"c": "planteo", "t": "Calcular el volumen del fondo paraboloidal y del fondo cónico. ¿Qué relación guardan con el cilindro circunscripto?"}, {"c": "planteo", "t": "Plantear el volumen V(h) para h ≤ 2 m y obtener dh/dt para un caudal constante Q. ¿Por qué el nivel sube cada vez más lento?"}, {"c": "lenguaje", "t": "Expresar la comparación entre ambos fondos en términos porcentuales, como información técnica para el catálogo."}], "articulacion": {"eje": "2", "t": "¿Qué ocurre con dh/dt cuando h → 0⁺? Interpretar ese límite al iniciar el llenado."}, "clave": "Paraboloide: V = π·∫₀² 2y dy = 4π ≈ 12,6 m³ (la mitad del cilindro, 8π). Cono: 8π/3 ≈ 8,4 m³ (un tercio). El paraboloide contiene 50 % más. V(h) = πh²; dh/dt = Q/(2πh), decreciente. dh/dt → +∞ si h → 0⁺: el primer grano eleva el nivel muy rápido.", "ref": ""}, {"id": "AM-32", "eje": "6", "tipo": "Problema aplicado", "titulo": "Bombeo para vaciar una cisterna", "temas": ["Aplicaciones físicas de la integral", "Trabajo de una fuerza variable", "Sumas de Riemann", "Propiedades de la integral definida"], "consigna": "Una cisterna cilíndrica enterrada, de 1 m de radio y 3 m de profundidad, está llena de agua hasta el nivel del terreno. Para limpiarla hay que bombear toda el agua hasta la superficie. El encargado debe elegir entre dos bombas y necesita conocer el trabajo mínimo requerido (ρ = 1 000 kg/m³, g = 9,8 m/s²). Expresar como integral, W(h), el trabajo necesario para bajar el nivel h metros y calcular W′(h); interpretar su valor para h = 1 m y h = 3 m.", "teorema": {"nombre": "Linealidad y aditividad de la integral definida", "consigna": "Enunciar las propiedades de linealidad y de aditividad respecto del intervalo de la integral definida y justificar cómo permiten sumar el trabajo de las capas de agua."}, "capacidades": ["Modelizar un trabajo variable como integral mediante una partición del sólido", "Interpretar físicamente las propiedades de la integral definida"], "preguntas": [{"c": "dominio", "t": "¿Por qué no puede calcularse el trabajo como peso total por profundidad total? ¿Qué cambia de una capa a otra?"}, {"c": "dominio", "t": "Obtener W(h) = ρgπ·∫₀ʰ y dy y su derivada W′(h). ¿Qué teorema justifica W′(h) y qué significa físicamente?"}, {"c": "planteo", "t": "Plantear el trabajo de una capa genérica de espesor dy y calcular el trabajo total."}, {"c": "planteo", "t": "Mostrar que el resultado coincide con elevar todo el peso desde la profundidad del centro de masa."}, {"c": "lenguaje", "t": "Expresar el trabajo en kJ y en kWh, con el redondeo adecuado para comparar bombas."}], "articulacion": {"eje": "3", "t": "La potencia es la derivada del trabajo respecto del tiempo. Si la bomba entrega 0,5 kW efectivos, ¿cuánto tarda el vaciado como mínimo?"}, "clave": "W = ρgπ·∫₀³ y dy = 1 000·9,8·π·4,5 ≈ 138,5 kJ ≈ 0,038 kWh. Equivale a elevar el peso total (≈ 92,4 kN) desde 1,5 m. Con 0,5 kW: ≈ 277 s ≈ 4,6 min. W(h) = ρgπh²/2; W′(h) = ρgπh: ≈ 30,8 kJ/m para h = 1 m y ≈ 92,4 kJ/m para h = 3 m (las capas profundas cuestan más).", "ref": ""}, {"id": "AM-33", "eje": "6", "tipo": "Problema aplicado", "titulo": "Longitud de un cable colgante", "temas": ["Longitud de arco", "Función exponencial", "Integral definida"], "consigna": "Un cable tendido entre dos postes de igual altura separados 200 m cuelga, con el origen en su punto más bajo, según y = 250·(e^(x/500) + e^(−x/500)) − 500 para −100 ≤ x ≤ 100, en metros. Se necesita la longitud de cable a encargar y la flecha en el centro del vano. Calcular la longitud con la fórmula integral de longitud de arco y, derivando y(x), la pendiente del cable en el apoyo x = 100 m y el ángulo que forma con la horizontal.", "teorema": {"nombre": "Fórmula de longitud de arco", "consigna": "Deducir la fórmula L = ∫ √(1 + (y′)²) dx a partir de la aproximación por poligonales y justificar el uso del teorema de Lagrange en esa deducción."}, "capacidades": ["Plantear y calcular la longitud de una curva", "Simplificar integrandos con propiedades de la función exponencial"], "preguntas": [{"c": "dominio", "t": "Explicar cómo se obtiene la fórmula de longitud de arco a partir de una poligonal inscripta. ¿Dónde interviene el teorema del valor medio?"}, {"c": "dominio", "t": "¿Qué condición debe cumplir y(x) para que la fórmula sea aplicable?"}, {"c": "planteo", "t": "Mostrar que 1 + (y′)² es un cuadrado perfecto y calcular la longitud del cable."}, {"c": "planteo", "t": "Calcular la flecha en el centro del vano, la pendiente y el ángulo en el apoyo, y comparar la longitud del cable con la distancia entre postes."}, {"c": "lenguaje", "t": "Presentar el pedido de cable con longitud, flecha y criterio de redondeo."}], "articulacion": {"eje": "7", "t": "Usar el desarrollo de Maclaurin de eᵘ para mostrar que, cerca del punto más bajo, la curva se aproxima por una parábola. Escribir esa parábola."}, "clave": "y′ = ½·(e^(x/500) − e^(−x/500)); 1 + (y′)² = ¼·(e^(x/500) + e^(−x/500))². L = 500·(e^0,2 − e^(−0,2)) ≈ 201,34 m (+0,67 %). Flecha = 250·(e^0,2 + e^(−0,2)) − 500 ≈ 10,03 m. Parábola: y ≈ x²/1 000. y′(100) = ½·(e^0,2 − e^(−0,2)) ≈ 0,201: ángulo ≈ 11,4°.", "ref": ""}, {"id": "AM-34", "eje": "6", "tipo": "Consigna matemática", "titulo": "Áreas entre curvas", "temas": ["Área entre curvas", "Regla de Barrow", "Signo de la integral definida"], "consigna": "Calcular el área de la región limitada por y = x² e y = 2x + 3. Luego calcular ∫₋₁¹ (x³ − x) dx y el área entre la curva y = x³ − x y el eje x en [−1, 1], y explicar por qué los resultados difieren. Determinar el punto de la parábola y = x² en que la recta tangente es paralela a y = 2x + 3 y relacionarlo con la máxima distancia vertical entre ambas curvas.", "teorema": {"nombre": "Regla de Barrow", "consigna": "Enunciar la regla de Barrow con sus hipótesis, justificarla a partir del teorema fundamental y explicar por qué el área entre dos curvas es ∫ (f − g) dx con f ≥ g."}, "capacidades": ["Plantear y calcular el área de una región entre curvas", "Distinguir integral definida y área cuando la función cambia de signo"], "preguntas": [{"c": "dominio", "t": "¿Cuándo la integral definida representa un área y cuándo no?"}, {"c": "dominio", "t": "¿Por qué ∫₋₁¹ (x³ − x) dx vale cero sin calcular? ¿Qué propiedad de la función y del intervalo se usa?"}, {"c": "planteo", "t": "Hallar las intersecciones y el área. Derivar d(x) = 2x + 3 − x² para hallar dónde la distancia vertical es máxima y comprobar que allí la tangente a la parábola es paralela a la recta."}, {"c": "planteo", "t": "Calcular el área entre y = x³ − x y el eje x en [−1, 1]."}, {"c": "lenguaje", "t": "Escribir la integral que da cada área indicando con claridad qué función queda por encima en cada intervalo."}], "articulacion": {"eje": "1", "t": "Analizar la paridad de x³ − x y su signo en [−1, 1]. ¿Qué relación tiene con el resultado de la integral?"}, "clave": "Intersecciones x = −1 y x = 3; área = ∫₋₁³ (2x + 3 − x²) dx = 32/3 ≈ 10,67. ∫₋₁¹ (x³ − x) dx = 0 por ser impar; el área es 2·∫₀¹ (x − x³) dx = 1/2. d′(x) = 2 − 2x = 0 en x = 1: distancia vertical máxima 4; en (1, 1) la tangente a y = x² tiene pendiente 2.", "ref": ""}, {"id": "AM-35", "eje": "6", "tipo": "Consigna matemática", "titulo": "Sólidos de revolución", "temas": ["Volumen de sólidos de revolución", "Método de los discos y arandelas", "Integral definida"], "consigna": "La región R está limitada por y = √x e y = x, con 0 ≤ x ≤ 1. Calcular el volumen del sólido que se genera al rotar R alrededor del eje x y el del que se genera al rotarla alrededor del eje y. Representar R y una sección típica en cada caso. Hallar, mediante la derivada, el punto de R en que la distancia vertical entre ambas curvas es máxima.", "teorema": {"nombre": "Volumen por secciones transversales", "consigna": "Justificar la fórmula de volumen por arandelas, V = π·∫ (R² − r²) dx, como límite de sumas de Riemann."}, "capacidades": ["Plantear volúmenes de revolución con discos y arandelas", "Elegir la variable de integración según el eje de giro"], "preguntas": [{"c": "dominio", "t": "¿Qué diferencia hay entre el método de los discos y el de las arandelas? ¿Cuándo corresponde cada uno?"}, {"c": "dominio", "t": "Al girar alrededor del eje y, ¿por qué conviene expresar las curvas como x = g(y)?"}, {"c": "planteo", "t": "Calcular el volumen al rotar R alrededor del eje x y hallar, derivando √x − x, dónde la región tiene su mayor altura."}, {"c": "planteo", "t": "Calcular el volumen al rotar R alrededor del eje y."}, {"c": "lenguaje", "t": "Escribir cada integral indicando radio exterior, radio interior y límites de integración."}], "articulacion": {"eje": "1", "t": "Determinar los puntos de intersección de y = √x e y = x y justificar cuál de las dos funciones es mayor en (0, 1)."}, "clave": "Eje x: V = π·∫₀¹ (x − x²) dx = π/6 ≈ 0,524. Eje y: V = π·∫₀¹ (y² − y⁴) dy = 2π/15 ≈ 0,419. En (0, 1), √x > x. (√x − x)′ = 1/(2√x) − 1 = 0 en x = 1/4: altura máxima 1/4.", "ref": ""}, {"id": "AM-36", "eje": "6", "tipo": "Problema aplicado", "titulo": "Superficie de un lote junto a un arroyo", "temas": ["Cálculo de áreas", "Integral definida", "Valor medio de una función"], "consigna": "Un lote rural tiene un frente recto de 100 m sobre un camino (eje x) y el fondo limitado por un arroyo cuyo borde sigue y = 30 + 5·sen(πx/50), con 0 ≤ x ≤ 100 m. Se necesita la superficie para la escritura y el ancho medio del lote. Calcular la superficie con una integral definida y, derivando la función del borde, determinar dónde el ancho es máximo y mínimo y la pendiente del borde en x = 0.", "teorema": {"nombre": "Teorema del valor medio del cálculo integral", "consigna": "Enunciar el teorema del valor medio del cálculo integral e interpretar el ancho medio del lote como el valor medio de la función en [0, 100]."}, "capacidades": ["Calcular superficies de figuras planas con bordes curvos", "Interpretar el valor medio de una función en un problema"], "preguntas": [{"c": "dominio", "t": "Enunciar el teorema del valor medio del cálculo integral e interpretarlo geométricamente."}, {"c": "dominio", "t": "¿Por qué la parte senoidal del borde no modifica la superficie total? Justificar con propiedades de la integral."}, {"c": "planteo", "t": "Calcular la superficie y el ancho medio. Derivar el borde para hallar los anchos máximo y mínimo con su ubicación y la inclinación en x = 0."}, {"c": "planteo", "t": "Estimar la superficie con una suma de Riemann de cuatro rectángulos usando el punto medio de cada subintervalo y comparar con el valor exacto."}, {"c": "lenguaje", "t": "Redactar el dato de superficie como figuraría en un plano de mensura, con unidades."}], "articulacion": {"eje": "7", "t": "El borde del arroyo es una función periódica. ¿Qué período tiene? ¿Qué relación tiene su expresión con un término de una serie de Fourier?"}, "clave": "A = ∫₀¹⁰⁰ (30 + 5·sen(πx/50)) dx = 3 000 m²; el término senoidal integra 0 en un período completo. Ancho medio 30 m. Punto medio con 4 rectángulos: 3 000 m² (los aportes senoidales se cancelan). Máximo ancho 35 m en x = 25 m; mínimo 25 m en x = 75 m. y′(0) = π/10 ≈ 0,314 (≈ 17,4°). Período 100 m.", "ref": ""}, {"id": "AM-56", "eje": "6", "origen": "T-09", "tipo": "Problema aplicado", "titulo": "Trabajo de extracción en un pozo", "temas": ["Trabajo de una fuerza variable", "Sumas de Riemann", "Valor medio", "Derivada"], "consigna": "Para extraer fluido de un pozo, la fuerza que debe ejercer el equipo varía con la profundidad x según F(x) = 3 000 + 50·√x N, para 0 ≤ x ≤ 100 m. Calcular el trabajo total como integral definida, obtener la fuerza media y la profundidad en que la fuerza la iguala, y analizar con F′(x) cómo varía la fuerza con la profundidad.", "teorema": {"nombre": "Teorema del valor medio del cálculo integral", "consigna": "Enunciar el teorema con sus hipótesis, interpretarlo geométricamente y aplicarlo a F en [0, 100]."}, "capacidades": ["Calcular el trabajo de una fuerza variable", "Interpretar el valor medio de una función en un contexto"], "preguntas": [{"c": "dominio", "t": "Definir la integral definida como límite de sumas de Riemann y justificar la integrabilidad de F por ser continua en [0, 100]."}, {"c": "dominio", "t": "Enunciar el teorema fundamental del cálculo y explicar por qué W′(x) = F(x) si W(x) es el trabajo hasta la profundidad x."}, {"c": "planteo", "t": "Calcular W, la fuerza media y la profundidad c en que F(c) iguala la media."}, {"c": "planteo", "t": "Calcular F′(x) e interpretar su comportamiento cuando x → 0⁺. ¿Es derivable F en x = 0?"}, {"c": "lenguaje", "t": "Expresar el trabajo en J, kJ y kWh con el redondeo adecuado."}], "articulacion": {"eje": "1", "t": "Obtener la función inversa x = F⁻¹(f) y usarla para determinar a qué profundidad la fuerza alcanza 3 400 N."}, "clave": "W = ∫₀¹⁰⁰ (3 000 + 50√x) dx = 300 000 + (100/3)·1 000 ≈ 333 333 J ≈ 333 kJ ≈ 0,093 kWh. Fuerza media ≈ 3 333 N; F(c) = 3 333,3 ⇔ c = (20/3)² ≈ 44,4 m. F′(x) = 25/√x → +∞ si x → 0⁺: F no es derivable en 0 (tangente vertical). F⁻¹(f) = ((f − 3 000)/50)²: 3 400 N a 64 m.", "ref": ""}, {"id": "AM-57", "eje": "6", "origen": "T-10", "tipo": "Problema aplicado", "titulo": "Cara parabólica de una presa", "temas": ["Área de regiones planas", "Sólidos de revolución", "Regla de Barrow", "Pendiente"], "consigna": "La cortina de una presa tiene una cara vertical con forma parabólica: su borde sigue y = 4 − x², con x e y en metros y 0 ≤ y ≤ 4. Calcular con una integral definida el área de la cara y el ancho medio de la cortina entre las cotas 0 y 4 m, y con la derivada la inclinación del borde en su apoyo sobre el terreno. Calcular además el volumen del sólido que se genera al rotar la región alrededor del eje y.", "teorema": {"nombre": "Regla de Barrow", "consigna": "Enunciar la regla de Barrow con sus hipótesis y aplicarla al cálculo del área de la cara de la cortina."}, "capacidades": ["Calcular áreas planas integrando respecto de x o de y", "Calcular volúmenes de sólidos de revolución"], "preguntas": [{"c": "dominio", "t": "Explicar el concepto de función integrable en el sentido de Riemann. ¿Por qué 4 − x² lo es en [−2, 2]?"}, {"c": "dominio", "t": "¿Por qué el área puede calcularse integrando respecto de x o respecto de y? Plantear ambas integrales."}, {"c": "planteo", "t": "Calcular el área, el ancho medio y la pendiente del borde en x = 2 con el ángulo correspondiente."}, {"c": "planteo", "t": "Calcular el volumen del sólido de revolución alrededor del eje y por el método de los discos."}, {"c": "lenguaje", "t": "Escribir cada integral indicando con claridad la variable, los límites y el integrando."}], "articulacion": {"eje": "1", "t": "Expresar el ancho de la cortina w en función de la cota y. ¿Qué tipo de función es? ¿Es invertible?"}, "clave": "Área: ∫₋₂² (4 − x²) dx = 32/3 ≈ 10,67 m² = ∫₀⁴ 2√(4 − y) dy. Ancho medio en [0, 4]: (32/3)/4 = 8/3 ≈ 2,67 m. y′(2) = −4: ángulo ≈ 76,0° con la horizontal. Volumen: π·∫₀⁴ (4 − y) dy = 8π ≈ 25,1 m³. w(y) = 2√(4 − y), decreciente; inversa y = 4 − w²/4.", "ref": ""}, {"id": "AM-58", "eje": "6", "origen": "T-11", "tipo": "Problema aplicado", "titulo": "Pieza de revolución para un motor", "temas": ["Sólidos de revolución", "Método de los discos", "Método de las arandelas", "Teorema fundamental"], "consigna": "Una pieza de motor se obtiene al girar alrededor del eje x la región limitada por y = √x, y = 0 y x = 4, en centímetros. Calcular su volumen por el método de los discos. Expresar el volumen V(a) de la pieza recortada a una longitud a ≤ 4, derivarlo e interpretar V′(a). Calcular también el volumen que se genera al girar la misma región alrededor del eje y por el método de las arandelas.", "teorema": {"nombre": "Volumen por secciones transversales", "consigna": "Justificar la fórmula del volumen como integral del área de las secciones y enunciar las condiciones que debe cumplir la función de área para aplicarla."}, "capacidades": ["Calcular volúmenes de revolución por discos y por arandelas", "Relacionar la derivada de un volumen acumulado con el área de la sección"], "preguntas": [{"c": "dominio", "t": "Enunciar las condiciones de integrabilidad de una función acotada en [a, b]. ¿Cuáles cumple el área de la sección A(x) = πx?"}, {"c": "dominio", "t": "¿Qué relación hay entre la derivada de un volumen acumulado y el área de la sección? ¿Qué teorema la establece?"}, {"c": "planteo", "t": "Calcular el volumen alrededor del eje x y obtener V(a) y V′(a)."}, {"c": "planteo", "t": "Calcular el volumen alrededor del eje y por arandelas, indicando radio exterior e interior. Comparar ambos métodos."}, {"c": "lenguaje", "t": "Representar la región y una sección típica en cada caso, con notación completa de los límites."}], "articulacion": {"eje": "1", "t": "¿Por qué conviene expresar la curva como x = y² para girar alrededor del eje y? ¿Qué relación hay entre y = √x y x = y²?"}, "clave": "V = π·∫₀⁴ x dx = 8π ≈ 25,1 cm³. V(a) = πa²/2; V′(a) = πa, área de la sección en x = a. Eje y: π·∫₀² (16 − y⁴) dy = 128π/5 ≈ 80,4 cm³. √x y y² (con y ≥ 0) son funciones inversas.", "ref": ""}, {"id": "AM-59", "eje": "6", "origen": "T-20", "tipo": "Problema aplicado", "titulo": "Carga de un estanque de decantación", "temas": ["Límites", "Extremos absolutos", "Función integral", "Carga acumulada"], "consigna": "La concentración de contaminante que ingresa a un estanque de decantación varía según C(t) = 8t/(t² + 4) ppm, con t en horas. Analizar los límites de C cuando t → 0⁺ y cuando t → +∞, determinar con la derivada el instante de concentración máxima y calcular la carga acumulada L(x) = ∫₀ˣ C(t) dt. Calcular L(6), estudiar la concavidad de L sin volver a integrar y analizar el comportamiento de L(x) cuando x crece.", "teorema": {"nombre": "Teorema fundamental del cálculo integral", "consigna": "Enunciar el teorema y usarlo para obtener L′ y L″ sin calcular la integral."}, "capacidades": ["Integrar límites, derivadas e integrales en el estudio de una función", "Analizar una función definida por una integral"], "preguntas": [{"c": "dominio", "t": "¿Qué información aporta cada herramienta —límites, derivadas e integrales— sobre C y sobre L?"}, {"c": "dominio", "t": "Enunciar los resultados que sostienen cada paso: existencia del máximo absoluto de C en [0, 6] y derivación de L."}, {"c": "planteo", "t": "Calcular t_máx, C_máx y L(6) por sustitución."}, {"c": "planteo", "t": "Obtener L′ y L″ y ubicar el punto de inflexión de L. ¿Por qué L crece sin cota aunque C → 0?"}, {"c": "lenguaje", "t": "Expresar la carga acumulada con unidades (ppm·h) e interpretar su significado."}], "articulacion": {"eje": "7", "t": "Analizar la convergencia de la serie Σ C(n), n ≥ 1, por comparación con la serie armónica."}, "clave": "lím C = 0 cuando t → 0⁺ y cuando t → +∞ (asíntota C = 0). C′ = 8(4 − t²)/(t² + 4)² = 0 en t = 2 h: C_máx = 2 ppm. L(x) = 4·ln((x² + 4)/4); L(6) = 4·ln 10 ≈ 9,21 ppm·h. L′ = C y L″ = C′: inflexión de L en x = 2. L(x) ≈ 8·ln x → +∞. C(n) ≥ 8/(5n) para n ≥ 1: Σ C(n) diverge.", "ref": ""}, {"id": "AM-37", "eje": "7", "tipo": "Problema aplicado", "titulo": "Cloración de un tanque de reserva", "temas": ["Sucesiones", "Sucesiones monótonas y acotadas", "Serie geométrica", "Límite de una sucesión"], "consigna": "En un tanque de reserva de agua potable se agrega cada mañana una dosis de 0,6 mg/L de cloro. A lo largo de cada día se consume el 30 % del cloro presente, de modo que la concentración inmediatamente después de cada dosis cumple cₙ₊₁ = 0,7·cₙ + 0,6, con c₁ = 0,6 mg/L. El protocolo de la planta fija un máximo de 1,8 mg/L tras la dosificación. Dentro de cada día el cloro decae según c(t) = cₙ·e^(−kt), con t en días y e^(−k) = 0,7: una vez alcanzado el equilibrio, calcular la velocidad de consumo inmediatamente después de la dosis y la concentración media diaria como integral de c(t) en [0, 1].", "teorema": {"nombre": "Convergencia de las sucesiones monótonas y acotadas", "consigna": "Enunciar el teorema de convergencia de las sucesiones monótonas y acotadas y justificar con él que la concentración tiende a un valor de equilibrio."}, "capacidades": ["Analizar una sucesión definida por recurrencia: monotonía, acotación y límite", "Relacionar sucesiones recurrentes con series geométricas"], "preguntas": [{"c": "dominio", "t": "Definir sucesión convergente. ¿Qué diferencia hay entre una sucesión acotada y una convergente? Dar un ejemplo acotado y no convergente."}, {"c": "dominio", "t": "Mostrar que cₙ es creciente y está acotada superiormente por 2. ¿Qué permite concluir el teorema?"}, {"c": "planteo", "t": "Calcular el valor de equilibrio L y, con c(t) = L·e^(−kt), la velocidad de consumo c′(0) y la concentración media diaria ∫₀¹ c(t) dt."}, {"c": "planteo", "t": "¿A partir de qué día se supera el máximo del protocolo? ¿Qué dosis diaria garantiza no superarlo nunca?"}, {"c": "lenguaje", "t": "Explicar al operador, con precisión y sin fórmulas, qué significa que la concentración «tienda» a 2 mg/L."}], "articulacion": {"eje": "1", "t": "Escribir cₙ = 2·(1 − 0,7ⁿ) y despejar n en cₙ = 1,8 con logaritmos. ¿Qué propiedad de la función logarítmica se utiliza?"}, "clave": "cₙ = 0,6·(1 + 0,7 + … + 0,7ⁿ⁻¹) = 2·(1 − 0,7ⁿ); L = 0,6/0,3 = 2 mg/L. cₙ > 1,8 desde n = 7 (c₇ ≈ 1,84). Para no superar 1,8 mg/L: dosis ≤ 0,54 mg/L. Con L = 2 mg/L y k = −ln 0,7 ≈ 0,357 día⁻¹: c′(0) = −kL ≈ −0,71 mg/(L·día); media diaria 2·(1 − 0,7)/k ≈ 1,68 mg/L. cₙ = 1,8 ⇔ n = ln 0,1/ln 0,7 ≈ 6,5.", "ref": ""}, {"id": "AM-38", "eje": "7", "tipo": "Problema aplicado", "titulo": "Cálculo del seno sin calculadora científica", "temas": ["Series de Taylor y de Maclaurin", "Resto de Lagrange", "Series de potencias", "Radio de convergencia"], "consigna": "Una planilla de cálculo debe evaluar sen θ para ángulos entre −30° y 30° usando solo sumas y productos. Se propone sen θ ≈ θ, pero el control de calidad exige un error menor que 10⁻⁴ en todo el rango y sugiere agregar términos del desarrollo de Maclaurin. Obtener los coeficientes del desarrollo a partir de las derivadas sucesivas de sen θ en 0 e integrar término a término el polinomio elegido para aproximar ∫₀^(π/6) sen θ dθ, comparando con el valor exacto.", "teorema": {"nombre": "Teorema de Taylor con resto de Lagrange", "consigna": "Enunciar el teorema de Taylor con resto en la forma de Lagrange y justificar cómo permite acotar el error de la aproximación en todo el intervalo."}, "capacidades": ["Construir polinomios de Maclaurin y acotar su error", "Determinar el radio de convergencia de una serie de potencias"], "preguntas": [{"c": "dominio", "t": "¿Qué diferencia hay entre el polinomio de Taylor de grado n y la serie de Taylor? Obtener los coeficientes a partir de las derivadas sucesivas de sen θ en 0."}, {"c": "dominio", "t": "Aplicar el criterio del cociente para hallar el radio de convergencia de la serie de sen x. ¿Qué significa el resultado?"}, {"c": "planteo", "t": "Acotar el error de sen θ ≈ θ en θ = π/6. ¿Cumple la exigencia? ¿Cuántos términos hacen falta para garantizar 10⁻⁴?"}, {"c": "planteo", "t": "Integrar término a término el polinomio de grado 5 en [0, π/6] y comparar con 1 − cos(π/6). ¿Por qué el error de la integral resulta menor que el de la función?"}, {"c": "lenguaje", "t": "Escribir el polinomio elegido y la cota de error con notación correcta."}], "articulacion": {"eje": "3", "t": "¿Qué relación hay entre el polinomio de Taylor de grado 1, la recta tangente y el diferencial de la función?"}, "clave": "θ = π/6 ≈ 0,5236. Error de θ: ≈ 0,024 (no cumple). Con θ − θ³/6: cota θ⁵/120 ≈ 3,3·10⁻⁴ (no cumple). Con θ − θ³/6 + θ⁵/120: cota θ⁷/5 040 ≈ 2,1·10⁻⁶ (cumple). Radio de convergencia infinito. Coeficientes f⁽ⁿ⁾(0)/n!: 0, 1, 0, −1/6, 0, 1/120. ∫₀^(π/6) (θ − θ³/6 + θ⁵/120) dθ ≈ 0,1339747, frente a 1 − cos(π/6) ≈ 0,1339746.", "ref": ""}, {"id": "AM-39", "eje": "7", "tipo": "Consigna matemática", "titulo": "Serie de Fourier de una onda cuadrada", "temas": ["Series funcionales", "Serie de Fourier", "Series alternadas", "Funciones pares e impares"], "consigna": "La función periódica f de período 2π que vale 1 en (0, π) y −1 en (−π, 0) tiene serie de Fourier f(t) = (4/π)·(sen t + sen 3t/3 + sen 5t/5 + …). Analizar qué valor toma la serie en t = π/2 y en t = 0, y qué resultado numérico se obtiene de esa evaluación. Verificar que el coeficiente de sen t es b₁ = (1/π)·∫₋π^π f(t)·sen t dt y analizar si la serie puede derivarse término a término.", "teorema": {"nombre": "Criterio de Leibniz para series alternadas", "consigna": "Enunciar el criterio de Leibniz y usarlo para justificar que la serie 1 − 1/3 + 1/5 − 1/7 + … converge; relacionarla con f(π/2)."}, "capacidades": ["Reconocer una serie funcional y analizar su convergencia en puntos particulares", "Interpretar la serie de Fourier como descomposición de una función periódica"], "preguntas": [{"c": "dominio", "t": "Calcular b₁ con la integral de los coeficientes. ¿Por qué los coeficientes de los cosenos son nulos?"}, {"c": "dominio", "t": "Evaluar la serie en t = π/2 y aplicar el criterio de Leibniz. ¿Qué valor debe tener la suma para que f(π/2) = 1?"}, {"c": "planteo", "t": "¿Qué valor da la serie en t = 0? Derivar término a término: ¿converge la serie obtenida? ¿Qué relación tiene con f′(t) = 0 fuera de los saltos?"}, {"c": "planteo", "t": "Calcular la suma parcial de los tres primeros términos en t = π/2 y acotar el error con el criterio de Leibniz."}, {"c": "lenguaje", "t": "Explicar con lenguaje preciso qué significa que la serie «represente» a f."}], "articulacion": {"eje": "1", "t": "¿Por qué una función impar tiene solo términos en seno en su serie de Fourier? Definir función par e impar y verificar que f es impar."}, "clave": "En t = π/2: (4/π)·(1 − 1/3 + 1/5 − …) = 1 ⇒ 1 − 1/3 + 1/5 − … = π/4. En t = 0 la serie vale 0, promedio de los límites laterales. Suma parcial de 3 términos: (4/π)·(1 − 1/3 + 1/5) ≈ 1,103; error en la serie entre paréntesis ≤ 1/7. b₁ = (2/π)·∫₀^π sen t dt = 4/π; los coeficientes de los cosenos son nulos por ser f impar. La serie derivada (4/π)·(cos t + cos 3t + …) no converge: su término general no tiende a 0.", "ref": ""}, {"id": "AM-40", "eje": "7", "tipo": "Consigna matemática", "titulo": "Criterios de convergencia", "temas": ["Series de términos positivos", "Criterio del cociente", "Criterio de comparación", "Serie armónica"], "consigna": "Analizar la convergencia de las series: (a) Σ n/2ⁿ; (b) Σ 1/√n; (c) Σ 1/(n² + 1); (d) Σ 3ⁿ/n!, con n desde 1. Justificar la elección del criterio en cada caso. Calcular la suma de (a) derivando la serie geométrica Σ xⁿ y acotar inferiormente la suma parcial de (b) con ∫₁^(N+1) x^(−1/2) dx.", "teorema": {"nombre": "Criterio del cociente (D'Alembert)", "consigna": "Enunciar el criterio del cociente, indicar qué ocurre cuando el límite vale 1 y aplicarlo a las series (a) y (d)."}, "capacidades": ["Seleccionar y aplicar criterios de convergencia para series de términos positivos", "Reconocer los casos en que un criterio no decide"], "preguntas": [{"c": "dominio", "t": "Definir serie convergente a partir de la sucesión de sumas parciales. ¿Basta que el término general tienda a cero?"}, {"c": "dominio", "t": "Enunciar el criterio de comparación. ¿Con qué serie conviene comparar (b) y (c)?"}, {"c": "planteo", "t": "Aplicar el criterio del cociente a (a) y (d) y calcular la suma de (a) a partir de la derivada de Σ xⁿ = 1/(1 − x)."}, {"c": "planteo", "t": "Decidir (b) y (c) por comparación y acotar la suma parcial S_N de (b) con ∫₁^(N+1) x^(−1/2) dx. ¿Qué muestra la cota?"}, {"c": "lenguaje", "t": "Escribir la conclusión de cada caso con la notación de límite que corresponde a cada criterio."}], "articulacion": {"eje": "4", "t": "Usar la regla de L'Hôpital para calcular lím n/2ⁿ cuando n → ∞, considerando la función x/2ˣ."}, "clave": "(a) Cociente → 1/2 < 1: converge (suma 2). (b) 1/√n ≥ 1/n y la armónica diverge: diverge. (c) 1/(n² + 1) < 1/n²: converge. (d) Cociente = 3/(n + 1) → 0: converge (suma e³ − 1). lím n/2ⁿ = 0. Σ n·xⁿ = x/(1 − x)² para |x| < 1 ⇒ Σ n/2ⁿ = 2. S_N de (b) ≥ ∫₁^(N+1) x^(−1/2) dx = 2·(√(N + 1) − 1) → +∞.", "ref": ""}, {"id": "AM-41", "eje": "7", "tipo": "Consigna matemática", "titulo": "Monotonía y límite de sucesiones", "temas": ["Sucesiones", "Monotonía y acotación", "Límite de una sucesión", "Sucesiones oscilantes"], "consigna": "Analizar monotonía, acotación y convergencia de aₙ = (2n + 1)/(n + 3), bₙ = (−1)ⁿ·n/(n + 1), cₙ = n/2ⁿ y dₙ = (1 + 1/n)ⁿ. Para las convergentes, calcular el límite. Estudiar la monotonía de cₙ con la derivada de f(x) = x/2ˣ y calcular el límite de eₙ = (1/n)·Σₖ₌₁ⁿ (k/n)², interpretándolo como una suma de Riemann.", "teorema": {"nombre": "Límite de una función y límite de una sucesión", "consigna": "Justificar que si lím f(x) = L cuando x → +∞, entonces lím f(n) = L, y explicar por qué el recíproco no vale."}, "capacidades": ["Determinar monotonía, acotación y límite de sucesiones", "Usar límites de funciones para calcular límites de sucesiones"], "preguntas": [{"c": "dominio", "t": "Interpretar eₙ como suma de Riemann de f(x) = x² en [0, 1] y calcular su límite. ¿Qué resultado garantiza la convergencia?"}, {"c": "dominio", "t": "¿Por qué bₙ no converge aunque |bₙ| tiende a 1? ¿Qué subsucesiones conviene observar?"}, {"c": "planteo", "t": "Escribir aₙ = 2 − 5/(n + 3) y deducir su monotonía, sus cotas y su límite."}, {"c": "planteo", "t": "Calcular los límites de cₙ y dₙ pasando a funciones de variable real, y estudiar la monotonía de cₙ con la derivada de x/2ˣ."}, {"c": "lenguaje", "t": "Expresar la definición de límite de una sucesión con ε y N, y aplicarla a aₙ con ε = 0,01."}], "articulacion": {"eje": "4", "t": "Calcular lím (1 + 1/x)ˣ cuando x → +∞ mediante logaritmos y la regla de L'Hôpital."}, "clave": "aₙ creciente, 3/4 ≤ aₙ < 2, límite 2 (|aₙ − 2| < 0,01 si n > 497). bₙ oscila entre valores cercanos a −1 y 1: no converge. cₙ decreciente desde n = 2, límite 0. dₙ creciente y acotada, límite e. (x/2ˣ)′ = 2^(−x)·(1 − x·ln 2) < 0 para x > 1/ln 2 ≈ 1,44. lím eₙ = ∫₀¹ x² dx = 1/3, por la integrabilidad de x² en [0, 1].", "ref": ""}, {"id": "AM-42", "eje": "7", "tipo": "Problema aplicado", "titulo": "Rebotes de una pelota", "temas": ["Sucesión geométrica", "Serie geométrica", "Suma de una serie", "Modelos discretos"], "consigna": "Una pelota cae desde 2 m de altura y, en cada rebote, sube hasta el 75 % de la altura anterior. Un estudiante afirma que, como rebota infinitas veces, recorre una distancia infinita; otro sostiene que la distancia total es finita y se puede calcular. Durante cada caída la altura es y(t) = h − 4,9·t²: obtener la velocidad de impacto derivando y(t) y verificar, integrando la velocidad, que el tiempo de caída desde h es √(2h/g).", "teorema": {"nombre": "Convergencia de la serie geométrica", "consigna": "Enunciar la condición de convergencia de la serie geométrica, demostrarla a partir de la fórmula de la suma parcial y aplicarla a la distancia total recorrida."}, "capacidades": ["Modelizar un proceso repetido con sucesiones y series geométricas", "Calcular e interpretar la suma de una serie convergente"], "preguntas": [{"c": "dominio", "t": "Enunciar la condición de convergencia de Σ rⁿ y deducir la fórmula de su suma."}, {"c": "dominio", "t": "¿Cómo puede una suma de infinitos términos positivos tener un valor finito? ¿Qué condición sobre los términos es necesaria y cuál suficiente?"}, {"c": "planteo", "t": "Escribir la distancia total como una serie y calcular su suma."}, {"c": "planteo", "t": "Derivar y(t) para obtener la velocidad de impacto desde 2 m; verificar el tiempo de caída integrando la velocidad y mostrar que el tiempo total también es una serie geométrica."}, {"c": "lenguaje", "t": "Redactar la respuesta a ambos estudiantes con lenguaje matemático preciso."}], "articulacion": {"eje": "2", "t": "Relacionar la suma de la serie con el límite de la sucesión de sumas parciales. ¿Qué tipo de límite es?"}, "clave": "Distancia: 2 + 2·Σ 2·0,75ⁿ (n ≥ 1) = 2 + 4·3 = 14 m. Tiempos: razón √0,75 ≈ 0,866; t₀ = √(4/9,8) ≈ 0,639 s; total = t₀·(1 + 2·0,866/(1 − 0,866)) ≈ 8,9 s. y′(t) = −9,8t; impacto desde 2 m a √(2·9,8·2) ≈ 6,26 m/s. ∫₀ᵀ 9,8t dt = 4,9T² = h ⇒ T = √(2h/g).", "ref": ""}, {"id": "AM-60", "eje": "7", "origen": "T-13", "tipo": "Problema aplicado", "titulo": "Convergencia de un algoritmo iterativo", "temas": ["Sucesiones monótonas y acotadas", "Límite de una sucesión", "Valor medio"], "consigna": "Un algoritmo iterativo genera las aproximaciones aₙ = (2n + 1)/(3n + 5), n ≥ 1. Demostrar que la sucesión es estrictamente creciente y acotada estudiando la derivada de f(x) = (2x + 1)/(3x + 5), calcular su límite y determinar desde qué iteración el error es menor que 10⁻³. Calcular además el valor medio de f en [0, 10] con una integral definida y analizar a qué tiende el valor medio en [0, N] cuando N → ∞.", "teorema": {"nombre": "Convergencia de las sucesiones monótonas y acotadas", "consigna": "Enunciar el teorema de convergencia de las sucesiones monótonas y acotadas y aplicarlo a aₙ."}, "capacidades": ["Estudiar monotonía, acotación y límite de una sucesión", "Relacionar el límite de una sucesión con el de una función real"], "preguntas": [{"c": "dominio", "t": "¿Qué relación hay entre el límite de una sucesión y el límite de una función real? ¿Por qué el signo de f′ decide la monotonía de aₙ?"}, {"c": "dominio", "t": "Definir límite de una sucesión con ε y N. ¿Qué diferencia hay entre una sucesión acotada y una convergente?"}, {"c": "planteo", "t": "Escribir aₙ = 2/3 − 7/(3(3n + 5)), deducir cotas y límite, y hallar N para ε = 10⁻³."}, {"c": "planteo", "t": "Calcular el valor medio de f en [0, 10] y su límite cuando el intervalo crece. ¿Por qué tiende al mismo valor que la sucesión?"}, {"c": "lenguaje", "t": "Expresar el resultado de convergencia con notación de límite y de cotas."}], "articulacion": {"eje": "1", "t": "Obtener la inversa de f y usarla para calcular desde qué n se cumple aₙ > 0,66."}, "clave": "f′(x) = 7/(3x + 5)² > 0: aₙ creciente; a₁ = 3/8 ≤ aₙ < 2/3; lím aₙ = 2/3. |aₙ − 2/3| = 7/(3(3n + 5)) < 10⁻³ ⇔ n ≥ 777. Valor medio en [0, 10]: 2/3 − (7/90)·ln 7 ≈ 0,515; en [0, N]: 2/3 − (7/(9N))·ln((3N + 5)/5) → 2/3. f⁻¹(y) = (5y − 1)/(2 − 3y): aₙ > 0,66 desde n = 116.", "ref": ""}, {"id": "AM-61", "eje": "7", "origen": "T-14", "tipo": "Problema aplicado", "titulo": "Integral no elemental en el diseño de antenas", "temas": ["Serie de Maclaurin", "Integración término a término", "Series alternadas"], "consigna": "En el diseño de antenas se necesita I = ∫₀¹ e^(−x²) dx, que no tiene primitiva elemental. Desarrollar f(x) = e^(−x²) en serie de Maclaurin a partir de la serie de eᵘ, integrar término a término para aproximar I con los cuatro primeros términos y acotar el error. Verificar el desarrollo derivando la serie término a término y comparando con f′(x) = −2x·e^(−x²).", "teorema": {"nombre": "Criterio de Leibniz para series alternadas", "consigna": "Enunciar el criterio de Leibniz y la cota del error de las sumas parciales, y aplicarlos a la serie obtenida para I."}, "capacidades": ["Obtener un desarrollo en serie por sustitución", "Aproximar una integral integrando término a término y acotar el error"], "preguntas": [{"c": "dominio", "t": "Enunciar el criterio del cociente para series numéricas y de potencias, y aplicarlo para hallar el radio de convergencia de la serie de e^(−x²)."}, {"c": "dominio", "t": "Explicar los conceptos de radio e intervalo de convergencia. ¿Por qué la integración término a término es válida en [0, 1]?"}, {"c": "planteo", "t": "Obtener la serie, la aproximación con cuatro términos y la cota del error. ¿Cuántos términos garantizan un error menor que 10⁻⁴?"}, {"c": "planteo", "t": "Derivar la serie término a término y verificar que coincide con el desarrollo de −2x·e^(−x²)."}, {"c": "lenguaje", "t": "Escribir la serie con notación de sumatoria, su término general y la cota del resto."}], "articulacion": {"eje": "4", "t": "Hallar los puntos de inflexión de f(x) = e^(−x²) con f″. ¿Qué forma tiene su gráfica?"}, "clave": "e^(−x²) = Σ (−1)ⁿ·x²ⁿ/n!, radio infinito. I = Σ (−1)ⁿ/(n!·(2n + 1)) ≈ 1 − 1/3 + 1/10 − 1/42 ≈ 0,7429; error ≤ 1/216 ≈ 0,0046 (valor ≈ 0,7468). Error < 10⁻⁴: sumar de n = 0 a n = 6 (el término n = 7 vale 1/75 600). f″ = (4x² − 2)·e^(−x²): inflexiones en x = ±1/√2.", "ref": ""}, {"id": "AM-62", "eje": "7", "origen": "T-15", "tipo": "Problema aplicado", "titulo": "Depreciación de un equipo industrial", "temas": ["Serie geométrica", "Condición necesaria de convergencia", "Modelo exponencial", "Valor medio"], "consigna": "El valor de rescate de un equipo industrial, de 1 000 miles de pesos, se deprecia un 10 % anual, de modo que al cabo de k años vale 1 000·0,9ᵏ. Analizar la convergencia de la serie S = Σₖ₌₀^∞ 1 000·0,9ᵏ y calcular su suma. Con el modelo continuo V(t) = 1 000·0,9ᵗ, calcular la velocidad de depreciación V′(t) al inicio y, con una integral definida, el valor medio del equipo en los primeros 10 años.", "teorema": {"nombre": "Convergencia de la serie geométrica", "consigna": "Enunciar la condición de convergencia de Σ rᵏ, deducir la fórmula de su suma y aplicarla a S."}, "capacidades": ["Analizar la convergencia de una serie geométrica y calcular su suma", "Comparar un modelo discreto con uno continuo"], "preguntas": [{"c": "dominio", "t": "Enunciar la condición necesaria de convergencia (aₖ → 0) y mostrar con la serie armónica que no es suficiente."}, {"c": "dominio", "t": "Enunciar el criterio de comparación directa. ¿Qué diferencia hay entre convergencia absoluta y condicional?"}, {"c": "planteo", "t": "Calcular la suma S y la suma parcial de los primeros 10 términos. ¿Qué fracción de S representa?"}, {"c": "planteo", "t": "Calcular V′(0), V′(10) y el valor medio de V en [0, 10]. ¿Por qué el valor medio es distinto del promedio entre V(0) y V(10)?"}, {"c": "lenguaje", "t": "Escribir S con notación de sumatoria y como límite de sumas parciales."}], "articulacion": {"eje": "1", "t": "Despejar t en V(t) = 500 con logaritmos. ¿En cuántos años el equipo pierde la mitad de su valor?"}, "clave": "Razón 0,9 < 1: S = 1 000/(1 − 0,9) = 10 000. S₁₀ = 10 000·(1 − 0,9¹⁰) ≈ 6 513 (≈ 65 %). Armónica: término → 0 y diverge. V′(t) = 1 000·ln 0,9·0,9ᵗ: V′(0) ≈ −105,4 y V′(10) ≈ −36,7 miles de pesos por año. Media en [0, 10]: 1 000·(1 − 0,9¹⁰)/(10·(−ln 0,9)) ≈ 618, menor que (1 000 + 348,7)/2 ≈ 674 porque V es convexa. Mitad del valor: t = ln 0,5/ln 0,9 ≈ 6,6 años.", "ref": ""}, {"id": "AM-63", "eje": "7", "origen": "T-21", "tipo": "Problema aplicado", "titulo": "Respuesta de una suspensión automotriz", "temas": ["Polinomio de Taylor", "Ecuaciones diferenciales", "Extremos", "Integral definida"], "consigna": "La respuesta de una suspensión ante un bache se modela con dy/dt + 2y = e^(−t), y(0) = 0, y se propone la solución y(t) = e^(−t) − e^(−2t). Verificar por derivación que es la solución del problema, hallar el instante de desplazamiento máximo y desarrollar y(t) en serie de Taylor alrededor de t = 0 hasta el grado 3. Comparar la integral exacta ∫₀^0,5 y(t) dt con la que se obtiene integrando el polinomio y analizar el error.", "teorema": {"nombre": "Teorema de Taylor con resto de Lagrange", "consigna": "Enunciar el teorema de Taylor con resto de Lagrange y explicar qué controla el tamaño del error de la aproximación de y(t)."}, "capacidades": ["Obtener un polinomio de Taylor y evaluar su precisión", "Relacionar una ecuación diferencial con su solución y su desarrollo en serie"], "preguntas": [{"c": "dominio", "t": "¿Cómo pueden obtenerse los coeficientes de Taylor de y a partir de la propia ecuación diferencial y de la condición inicial?"}, {"c": "dominio", "t": "Enunciar el teorema de Taylor con resto de Lagrange. ¿Por qué la aproximación empeora al alejarse de t = 0?"}, {"c": "planteo", "t": "Verificar la solución, hallar el desplazamiento máximo y obtener el polinomio de grado 3."}, {"c": "planteo", "t": "Calcular ∫₀^0,5 y(t) dt en forma exacta y con el polinomio, y comparar."}, {"c": "lenguaje", "t": "Justificar con lenguaje técnico la utilidad de las aproximaciones polinómicas en un controlador digital."}], "articulacion": {"eje": "2", "t": "Calcular lím y(t) cuando t → +∞ e interpretar el regreso de la suspensión al equilibrio."}, "clave": "y′ = −e^(−t) + 2e^(−2t); y′ + 2y = e^(−t) e y(0) = 0. Máximo en t = ln 2 ≈ 0,69: y = 1/4. P₃(t) = t − (3/2)t² + (7/6)t³ (y′(0) = 1, y″(0) = −3, y‴(0) = 7). ∫₀^0,5 y dt = (1 − e^(−0,5)) − (1 − e^(−1))/2 ≈ 0,0774; con P₃: ≈ 0,0807 (error ≈ 0,0033). lím y = 0.", "ref": ""}, {"id": "RC-01", "eje": "R", "carrera": "CIV", "integra": ["3", "4", "5"], "tipo": "Tarjeta roja de especialidad", "titulo": "Momento máximo en una viga", "temas": ["Primitivas y condiciones de borde", "Extremos de funciones", "Teorema fundamental del cálculo"], "consigna": "Una viga de hormigón armado de 6 m de luz, simplemente apoyada, soporta una carga uniformemente distribuida q = 10 kN/m. Para dimensionar la armadura hay que ubicar la sección de momento flector máximo, sabiendo que la carga, el esfuerzo de corte V y el momento M se relacionan por dV/dx = −q y dM/dx = V. Obtener V(x) y M(x) integrando esas relaciones.", "teorema": {"nombre": "Teorema de Fermat", "consigna": "Enunciar el teorema de Fermat y justificar con él por qué el momento flector máximo se produce donde se anula el esfuerzo de corte."}, "capacidades": ["Obtener esfuerzos internos de una viga por integración sucesiva con condiciones de borde", "Localizar el extremo de una función a partir del anulamiento de su derivada"], "preguntas": [{"c": "dominio", "t": "¿Por qué al integrar dV/dx = −q aparece una constante? ¿Qué información física la determina?"}, {"c": "dominio", "t": "¿Qué garantiza que el punto donde V = 0 sea máximo y no mínimo del momento? Usar el criterio de la derivada segunda."}, {"c": "planteo", "t": "Integrar para obtener V(x) y M(x) con las condiciones M(0) = M(6) = 0 y calcular el momento máximo."}, {"c": "planteo", "t": "Si la carga fuera triangular, q(x) = q₀·x/L, ¿se desplazaría la sección crítica? Plantear cómo encontrarla."}, {"c": "lenguaje", "t": "Describir la forma de los diagramas de corte y de momento justificándola con el grado de las funciones."}], "articulacion": {"eje": "7", "t": "Si la carga fuera una función complicada, podría aproximarse por un polinomio de Taylor. ¿Qué ventaja tendría al integrar para obtener M(x)?"}, "clave": "V(x) = 30 − 10x kN; M(x) = 30x − 5x² kN·m; V = 0 en x = 3 m; M_máx = qL²/8 = 45 kN·m. Carga triangular: V = q₀L/6 − q₀x²/(2L) = 0 en x = L/√3 ≈ 3,46 m.", "ref": ""}, {"id": "RC-02", "eje": "R", "carrera": "CIV", "integra": ["3", "5"], "tipo": "Tarjeta roja de especialidad", "titulo": "Flecha de un alero en voladizo", "temas": ["Ecuaciones diferenciales por integración directa", "Condiciones de borde", "Primitivas"], "consigna": "Un alero de acero empotrado en un muro, de longitud L = 2 m, soporta en su extremo libre una carga puntual P = 5 kN. Con x medido desde el empotramiento y la deflexión y(x) positiva hacia abajo, la elástica cumple E·I·y″ = P·(L − x), con E·I = 2 000 kN·m². El reglamento limita la flecha admisible a L/250. Obtener la elástica integrando dos veces y verificar la flecha.", "teorema": {"nombre": "Primitivas de una misma función", "consigna": "Enunciar y demostrar, a partir del teorema de Lagrange, que dos primitivas de una misma función difieren en una constante, y justificar por qué la elástica requiere dos condiciones de borde."}, "capacidades": ["Resolver una ecuación diferencial de segundo orden por doble integración", "Traducir vínculos estructurales a condiciones matemáticas"], "preguntas": [{"c": "dominio", "t": "¿Qué orden tiene la ecuación de la elástica? ¿Por qué la solución general contiene dos constantes?"}, {"c": "dominio", "t": "¿Qué significan físicamente y(0) = 0 e y′(0) = 0 en un empotramiento?"}, {"c": "planteo", "t": "Integrar dos veces, aplicar las condiciones de borde y obtener la flecha en el extremo. ¿Cumple el reglamento?"}, {"c": "planteo", "t": "¿Cómo varía la flecha si se duplica la longitud del alero con la misma carga? ¿Qué indica el exponente para el diseño?"}, {"c": "lenguaje", "t": "Redactar la verificación de flecha como figuraría en una memoria de cálculo."}], "articulacion": {"eje": "4", "t": "¿Dónde es máxima la pendiente de la elástica? Justificar con el análisis de y′ y de su derivada."}, "clave": "y(x) = P·x²·(3L − x)/(6EI); flecha y(L) = PL³/(3EI) ≈ 6,7 mm < L/250 = 8 mm: cumple. Duplicar L multiplica la flecha por 8. y′ = P·x·(2L − x)/(2EI), creciente: pendiente máxima en x = L.", "ref": ""}, {"id": "RC-03", "eje": "R", "carrera": "CIV", "integra": ["1", "3", "4"], "tipo": "Tarjeta roja de especialidad", "titulo": "Curva vertical de una ruta", "temas": ["Función cuadrática", "Derivada como pendiente", "Extremos", "Concavidad"], "consigna": "En el proyecto de una ruta, una rampa de pendiente +3 % debe empalmarse con una pendiente de −2 % mediante una curva vertical parabólica de 200 m de longitud horizontal. Con el origen al inicio de la curva, la cota relativa es y(x) = 0,03·x − (0,05/400)·x², con x e y en metros. Para ubicar un desagüe y verificar la visibilidad se necesita el punto más alto de la curva. Calcular además, con una integral definida, la cota media de la rasante a lo largo de la curva.", "teorema": {"nombre": "Criterio de la derivada segunda", "consigna": "Enunciar el criterio de la derivada segunda para extremos relativos, justificarlo y explicar qué ocurre cuando la derivada segunda se anula."}, "capacidades": ["Interpretar la derivada como pendiente de un trazado y verificar condiciones de empalme", "Localizar extremos de una función cuadrática y justificar su naturaleza"], "preguntas": [{"c": "dominio", "t": "¿Por qué y′(x) representa la pendiente longitudinal del camino? ¿Cómo se expresa en porcentaje?"}, {"c": "dominio", "t": "Calcular la cota media de la curva con la integral definida. ¿Qué teorema garantiza que existe una progresiva donde la cota coincide con ese valor medio?"}, {"c": "planteo", "t": "Verificar que y′(0) = 0,03 e y′(200) = −0,02, hallar la abscisa y la cota del punto más alto y justificar que es máximo con el signo de y″."}, {"c": "planteo", "t": "¿Cómo cambia la ubicación del punto alto si la curva se alarga a 300 m? Generalizar para pendientes g₁ y g₂."}, {"c": "lenguaje", "t": "Indicar la progresiva y la cota relativa del punto alto como figurarían en el plano de perfil longitudinal."}], "articulacion": {"eje": "5", "t": "La cota y(x) puede obtenerse integrando la pendiente y′(x), que varía linealmente entre 0,03 y −0,02. Plantear esa integral y explicar por qué hace falta un dato adicional."}, "clave": "y′ = 0,03 − 0,05x/200 = 0 en x = 120 m; y(120) = 1,8 m. y″ = −0,00025 < 0: máximo (curva convexa). En general x = g₁·L/(g₁ − g₂) = 0,6·L ⇒ 180 m para L = 300 m. Cota media: (1/200)·∫₀²⁰⁰ y dx = 4/3 ≈ 1,33 m.", "ref": ""}, {"id": "RC-04", "eje": "R", "carrera": "CIV", "integra": ["5", "6"], "tipo": "Tarjeta roja de especialidad", "titulo": "Cubicación de una excavación", "temas": ["Volumen por secciones transversales", "Sumas de Riemann", "Aproximación de integrales"], "consigna": "Para excavar un tramo de canal se relevaron perfiles transversales cada 20 m. Las áreas de excavación resultaron 12, 15, 19, 16 y 10 m² en las progresivas 0, 20, 40, 60 y 80 m. El contratista certificó 1 220 m³ con el método de las áreas medias y la inspección propone verificar con una aproximación parabólica (regla de Simpson). Estimar además la tasa de variación del área de excavación, dA/dx, en la progresiva 40 m, e interpretar su signo.", "teorema": {"nombre": "Integral definida como límite de sumas de Riemann", "consigna": "Definir la integral definida como límite de sumas de Riemann y justificar por qué el volumen de excavación es ∫ A(x) dx y por qué las reglas de aproximación lo estiman."}, "capacidades": ["Calcular volúmenes por secciones a partir de datos de campo", "Comparar métodos de aproximación de la integral"], "preguntas": [{"c": "dominio", "t": "¿Por qué el volumen de excavación puede escribirse como ∫ A(x) dx? ¿Qué se supone sobre la variación del área entre perfiles?"}, {"c": "dominio", "t": "¿Qué tipo de función reemplaza a A(x) en la regla del trapecio y cuál en la de Simpson?"}, {"c": "planteo", "t": "Verificar el volumen del contratista con la regla del trapecio y calcularlo con Simpson. ¿Qué diferencia porcentual hay?"}, {"c": "planteo", "t": "¿Qué sugieren los datos sobre la concavidad de A(x)? Estimar dA/dx en la progresiva 40 m con un cociente centrado. ¿El trapecio sobreestima o subestima?"}, {"c": "lenguaje", "t": "Redactar la observación de la inspección al certificado, con criterio técnico y unidades."}], "articulacion": {"eje": "7", "t": "Si la separación entre perfiles se reduce a la mitad, el error de la regla del trapecio se reduce aproximadamente a la cuarta parte. Expresar los errores sucesivos como una sucesión y analizar su límite."}, "clave": "Trapecio: 20·(6 + 15 + 19 + 16 + 5) = 1 220 m³. Simpson: (20/3)·(12 + 60 + 38 + 64 + 10) ≈ 1 226,7 m³ (+0,55 %). Datos de forma cóncava: el trapecio subestima. Tasa en 40 m ≈ (16 − 15)/40 = 0,025 m²/m. Errores eₖ ≈ e₀/4ᵏ: sucesión geométrica de razón 1/4, con límite 0.", "ref": ""}, {"id": "RC-05", "eje": "R", "carrera": "CIV", "integra": ["1", "2", "4"], "tipo": "Tarjeta roja de especialidad", "titulo": "Resistencia del hormigón y desencofrado", "temas": ["Función racional", "Límite al infinito y asíntota horizontal", "Función inversa", "Crecimiento y concavidad"], "consigna": "La resistencia a compresión de un hormigón curado en condiciones normales se estima con f(t) = f₂₈·t/(4 + 0,85·t), con t en días y f₂₈ la resistencia especificada a 28 días. La obra necesita desencofrar una losa cuando el hormigón alcance el 70 % de f₂₈, y la dirección de obra pregunta qué resistencia puede esperarse si se deja curar indefinidamente. Calcular la velocidad de ganancia de resistencia a los 7 días y, con una integral definida, la resistencia media durante los primeros 28 días.", "teorema": {"nombre": "Límite al infinito y asíntota horizontal", "consigna": "Enunciar la definición de límite cuando t → +∞ y la de asíntota horizontal, y justificar con ellas la resistencia límite del modelo."}, "capacidades": ["Interpretar el comportamiento asintótico de un modelo empírico", "Usar la función inversa para resolver un problema de plazos"], "preguntas": [{"c": "dominio", "t": "Calcular lím f(t) para t → +∞. ¿Qué significa que ese límite supere a f₂₈?"}, {"c": "planteo", "t": "Calcular la resistencia media en [0, 28] escribiendo f(t) = (f₂₈/0,85)·[1 − 4/(4 + 0,85t)] e integrando."}, {"c": "planteo", "t": "Hallar el plazo de desencofrado despejando t de f(t) = 0,7·f₂₈. Verificar que f(28) ≈ f₂₈."}, {"c": "planteo", "t": "Calcular f′(t) y f′(7), y mostrar que f es creciente y cóncava hacia abajo para t > 0. ¿Qué significa para la ganancia diaria de resistencia?"}, {"c": "lenguaje", "t": "Redactar la respuesta a la dirección de obra con plazo y resistencia límite, y con las salvedades del modelo."}], "articulacion": {"eje": "5", "t": "La resistencia ganada entre los días 7 y 28 puede expresarse como integral de la tasa f′(t). Plantear esa integral y explicar por qué su valor es f(28) − f(7)."}, "clave": "lím f = f₂₈/0,85 ≈ 1,18·f₂₈. f = 0,7·f₂₈ ⇔ t = 2,8/0,405 ≈ 6,9 días. f(28) = (28/27,8)·f₂₈ ≈ 1,007·f₂₈. f′(t) = 4f₂₈/(4 + 0,85t)² > 0 y f″ < 0. Asíntota vertical en t ≈ −4,7, fuera del dominio. f′(7) ≈ 0,040·f₂₈ por día. Resistencia media en [0, 28]: (f₂₈/0,85)·[1 − (4/23,8)·ln 6,95] ≈ 0,79·f₂₈.", "ref": ""}, {"id": "RC-06", "eje": "R", "carrera": "CIV", "integra": ["3", "5", "6"], "tipo": "Tarjeta roja de especialidad", "titulo": "Curva altura–volumen de un embalse", "temas": ["Teorema fundamental del cálculo", "Volumen por secciones", "Razones de cambio relacionadas"], "consigna": "Para un pequeño embalse de regulación, la topografía del vaso indica que el área del espejo de agua crece con la profundidad según S(h) = 400·h² m², con h en metros desde el punto más bajo. Durante un turno ingresa un caudal neto constante de 2 m³/s. El operador necesita la curva altura–volumen y la velocidad de ascenso del nivel cuando h = 5 m. Obtener V(h) como ∫₀ʰ S(u) du.", "teorema": {"nombre": "Teorema fundamental del cálculo integral", "consigna": "Enunciar el teorema fundamental y justificar con él que, si V(h) = ∫₀ʰ S(s) ds, entonces dV/dh = S(h)."}, "capacidades": ["Construir la curva altura–volumen de un embalse por integración", "Combinar el teorema fundamental con la regla de la cadena para obtener razones de cambio"], "preguntas": [{"c": "dominio", "t": "¿Por qué el volumen almacenado es la integral del área del espejo respecto de la profundidad? ¿Qué supuesto geométrico implica?"}, {"c": "dominio", "t": "Explicar el teorema fundamental en este contexto: ¿qué significa físicamente que dV/dh = S(h)?"}, {"c": "planteo", "t": "Obtener V(h) y calcular el volumen almacenado a 5 m de profundidad."}, {"c": "planteo", "t": "Calcular la velocidad de ascenso del nivel para h = 5 m y explicar por qué el nivel sube cada vez más lento."}, {"c": "lenguaje", "t": "Presentar la curva altura–volumen en una tabla para h = 1, 2, …, 6 m, como la usaría el operador."}], "articulacion": {"eje": "1", "t": "Obtener la función inversa h(V). ¿Qué tipo de función es y en qué dominio está definida?"}, "clave": "V(h) = 400h³/3; V(5) ≈ 16 667 m³. dV/dt = S(h)·dh/dt ⇒ dh/dt = 2/10 000 = 2·10⁻⁴ m/s ≈ 0,72 m/h. h(V) = (3V/400)^(1/3), V ≥ 0.", "ref": ""}, {"id": "RC-07", "eje": "R", "carrera": "CIV", "integra": ["3", "6"], "tipo": "Tarjeta roja de especialidad", "titulo": "Sección de un canal parabólico", "temas": ["Área entre curvas", "Integral definida", "Derivada como pendiente", "Simetría"], "consigna": "Un canal de riego revestido en hormigón tiene sección transversal parabólica: el perfil interior es y = x²/2 y el borde superior está en y = 2, con x e y en metros. La inspección necesita el área mojada para distintos tirantes h (altura del agua) y la inclinación de las paredes en el borde, para verificar la estabilidad del revestimiento. Calcular el área mediante una integral definida y la inclinación mediante la derivada del perfil.", "teorema": {"nombre": "Regla de Barrow", "consigna": "Enunciar la regla de Barrow con sus hipótesis, justificarla a partir del teorema fundamental y explicar por qué el área entre dos curvas es ∫ (f − g) dx."}, "capacidades": ["Plantear el área de una sección hidráulica como área entre curvas", "Interpretar la derivada como pendiente de una superficie construida"], "preguntas": [{"c": "dominio", "t": "¿Cuándo la integral definida representa un área? ¿Qué propiedad permite calcular el área como el doble de la integral entre 0 y el borde?"}, {"c": "dominio", "t": "¿Qué relación hay entre y′(x) y el ángulo que forma la pared con la horizontal?"}, {"c": "planteo", "t": "Calcular el área de la sección llena y el área mojada A(h) para un tirante genérico h ≤ 2 m."}, {"c": "planteo", "t": "Calcular la pendiente de la pared en el borde superior y el ángulo correspondiente."}, {"c": "lenguaje", "t": "Comparar la sección llena con un rectángulo de igual ancho y profundidad y expresar la relación en lenguaje técnico."}], "articulacion": {"eje": "1", "t": "Expresar el ancho del pelo de agua b en función del tirante h. ¿Qué tipo de función es y cuál es su inversa?"}, "clave": "Sección llena: 2·∫₀² (2 − x²/2) dx = 16/3 ≈ 5,33 m² (2/3 del rectángulo de 4 × 2). A(h) = (4/3)·h·√(2h). Pendiente en x = 2: y′ = 2, ángulo ≈ 63,4°. b(h) = 2√(2h); inversa h = b²/8.", "ref": ""}, {"id": "RC-08", "eje": "R", "carrera": "CIV", "integra": ["2", "3"], "tipo": "Tarjeta roja de especialidad", "titulo": "Empalme de un camino rural", "temas": ["Derivadas laterales", "Continuidad y derivabilidad", "Derivadas de orden superior"], "consigna": "Un tramo recto de un camino rural, representado en planta por y = 0 para x < 0, se empalma en x = 0 con una curva. Se evalúan dos alternativas para x ≥ 0: la alternativa 1 es y = 0,002·x² y la alternativa 2, la recta y = 0,05·x (x e y en metros). Un vehículo que circula por el empalme no debe experimentar un cambio brusco de dirección. Analizar el empalme con las derivadas laterales en x = 0 y, para la alternativa 1, calcular con una integral la longitud del eje del camino entre x = 0 y x = 100 m.", "teorema": {"nombre": "Continuidad y derivabilidad", "consigna": "Enunciar que toda función derivable es continua, mostrar que el recíproco es falso y justificar qué condición sobre las derivadas laterales garantiza la derivabilidad en el empalme."}, "capacidades": ["Analizar continuidad y derivabilidad en un punto de cambio de fórmula", "Interpretar la derivabilidad como ausencia de quiebre en un trazado"], "preguntas": [{"c": "dominio", "t": "Definir derivada lateral por izquierda y por derecha. ¿Qué condición deben cumplir para que exista la derivada en x = 0?"}, {"c": "dominio", "t": "Ambas alternativas son continuas en x = 0. ¿Por qué eso no alcanza para un trazado vial seguro?"}, {"c": "planteo", "t": "Calcular las derivadas laterales en x = 0 para cada alternativa e interpretar el resultado en términos de la dirección del vehículo."}, {"c": "planteo", "t": "Para la alternativa 1, calcular las derivadas segundas laterales en x = 0 y la longitud del eje entre 0 y 100 m con la integral de longitud de arco."}, {"c": "lenguaje", "t": "Redactar la recomendación distinguiendo con precisión continuidad, derivabilidad y continuidad de la derivada segunda."}], "articulacion": {"eje": "7", "t": "El polinomio de Taylor de orden 2 en x = 0 usa f(0), f′(0) y f″(0). ¿Qué polinomio se obtiene por izquierda y por derecha en la alternativa 1 y qué muestra la diferencia?"}, "clave": "Alt. 1: f′₋(0) = f′₊(0) = 0 (derivable, sin quiebre); f″₋(0) = 0 ≠ f″₊(0) = 0,004 (salto de curvatura). Alt. 2: f′₋(0) = 0 ≠ f′₊(0) = 0,05 (quiebre). En la práctica se usan curvas de transición. Longitud: ∫₀¹⁰⁰ √(1 + (0,004x)²) dx ≈ 102,61 m (con software o por sustitución).", "ref": ""}, {"id": "RI-01", "eje": "R", "carrera": "IND", "integra": ["2", "3", "4"], "tipo": "Tarjeta roja de especialidad", "titulo": "Costo medio mínimo de una envasadora", "temas": ["Costo marginal", "Asíntota oblicua", "Optimización", "Derivada de un cociente"], "consigna": "Una planta de envasado estima su costo total diario como C(q) = 2 000 + 10·q + 0,02·q², en miles de pesos, con q la producción en cientos de unidades. La gerencia quiere el nivel de producción que minimiza el costo medio por unidad, y el ingeniero de procesos sostiene que en ese punto el costo marginal coincide con el costo medio. Calcular además el costo de pasar de 300 a 400 cientos de unidades como ∫₃₀₀⁴⁰⁰ C′(q) dq.", "teorema": {"nombre": "Teorema de Fermat", "consigna": "Enunciar el teorema de Fermat y usarlo para demostrar que, en un mínimo del costo medio c(q) = C(q)/q, se cumple C′(q) = c(q)."}, "capacidades": ["Optimizar una función de costo medio y justificar la naturaleza del extremo", "Interpretar las asíntotas de una función económica"], "preguntas": [{"c": "dominio", "t": "Definir costo marginal como derivada. ¿Por qué ∫₃₀₀⁴⁰⁰ C′(q) dq da el costo incremental exacto y 100·C′(300) solo una aproximación?"}, {"c": "dominio", "t": "Derivar c(q) = C(q)/q con la regla del cociente y demostrar la afirmación del ingeniero."}, {"c": "planteo", "t": "Hallar el nivel de producción que minimiza el costo medio y su valor. Justificar que es mínimo absoluto en q > 0."}, {"c": "planteo", "t": "Determinar las asíntotas de c(q). ¿Qué representa la asíntota oblicua para producciones muy grandes?"}, {"c": "lenguaje", "t": "Presentar el resultado a la gerencia distinguiendo sin ambigüedad costo medio y costo marginal."}], "articulacion": {"eje": "7", "t": "Si la producción mensual comenzara en 300 cientos de unidades y creciera un 5 % por mes, ¿qué producción se acumularía en un año? Expresarla como suma de una progresión geométrica."}, "clave": "c(q) = 2 000/q + 10 + 0,02q; c′ = 0 en q = √100 000 ≈ 316 (cientos de unidades); c_mín ≈ 22,65 = C′(316). Asíntota vertical q = 0 y oblicua c = 10 + 0,02q. ∫₃₀₀⁴⁰⁰ C′(q) dq = C(400) − C(300) = 2 400 miles de $; 100·C′(300) = 2 200. Acumulado anual: 300·(1,05¹² − 1)/0,05 ≈ 4 775 cientos de unidades.", "ref": ""}, {"id": "RI-02", "eje": "R", "carrera": "IND", "integra": ["1", "4"], "tipo": "Tarjeta roja de especialidad", "titulo": "Lote económico de compra", "temas": ["Modelos de optimización", "Criterio de la derivada segunda", "Función racional"], "consigna": "Un depósito de repuestos tiene una demanda anual de D = 12 000 unidades de un componente. Cada pedido cuesta S = 600 u.m. entre gestión y flete, y mantener una unidad en stock durante un año cuesta H = 4 u.m. Si se pide un lote de Q unidades cada vez, el costo anual relevante es CT(Q) = D·S/Q + H·Q/2. Hoy se piden 1 000 unidades por vez. Minimizar CT(Q) con la derivada y justificar el término H·Q/2 calculando el inventario medio de un ciclo como valor medio de I(t) = Q·(1 − t/T) en [0, T].", "teorema": {"nombre": "Criterio de la derivada segunda", "consigna": "Enunciar el criterio de la derivada segunda, justificarlo y aplicarlo para asegurar que el lote óptimo minimiza el costo."}, "capacidades": ["Obtener en forma general una fórmula de optimización (lote económico)", "Analizar la sensibilidad del costo frente a apartamientos del óptimo"], "preguntas": [{"c": "dominio", "t": "¿Qué representan los dos términos de CT(Q)? Mostrar con la integral definida que el inventario medio de un ciclo es Q/2."}, {"c": "dominio", "t": "¿Qué garantiza el signo de CT″ en todo el dominio? ¿Alcanza para afirmar que el mínimo es absoluto?"}, {"c": "planteo", "t": "Deducir Q* = √(2DS/H) y calcularlo. ¿Cuánto cuesta la política actual frente a la óptima?"}, {"c": "planteo", "t": "Mostrar que en el óptimo ambos términos del costo son iguales."}, {"c": "lenguaje", "t": "Redactar la recomendación de compras con el ahorro anual estimado."}], "articulacion": {"eje": "3", "t": "Usar el diferencial para estimar el cambio en CT si el lote se redondea de Q* a 2 000 unidades. ¿Por qué el resultado es tan pequeño?"}, "clave": "Q* = √3 600 000 ≈ 1 897 unidades; CT(Q*) ≈ 7 589 u.m.; CT(1 000) = 9 200 u.m.: ahorro ≈ 1 611 u.m. por año. Como CT′(Q*) = 0, dCT ≈ 0; exacto: CT(2 000) = 7 600 u.m. (1/T)·∫₀ᵀ Q·(1 − t/T) dt = Q/2.", "ref": ""}, {"id": "RI-03", "eje": "R", "carrera": "IND", "integra": ["1", "5", "7"], "tipo": "Tarjeta roja de especialidad", "titulo": "Curva de aprendizaje en una línea de montaje", "temas": ["Función potencial y logarítmica", "Series", "Aproximación de sumas por integrales", "Criterio de comparación"], "consigna": "En una línea de montaje de tableros eléctricos, el primer tablero demandó 10 horas-hombre. Cada vez que se duplica la cantidad producida, el tiempo unitario se reduce al 80 %, lo que se modela como T(n) = 10·n^(−b) horas para el n-ésimo tablero, con b = −log₂ 0,8. Para cotizar un pedido de 100 tableros se necesita el tiempo total. Estimar el tiempo total con una integral definida y calcular la tasa de reducción del tiempo unitario, T′(n), para el tablero 10.", "teorema": {"nombre": "Criterio de comparación para series de términos positivos", "consigna": "Enunciar el criterio de comparación y usarlo para justificar que la serie Σ n^(−b) diverge cuando 0 < b < 1."}, "capacidades": ["Expresar el parámetro de un modelo potencial mediante logaritmos", "Aproximar sumas extensas mediante integrales"], "preguntas": [{"c": "dominio", "t": "Calcular b y explicar por qué la condición T(2n) = 0,8·T(n) conduce a un modelo potencial."}, {"c": "dominio", "t": "¿Por qué la serie Σ T(n) diverge aunque T(n) → 0? ¿Qué significa para un pedido ilimitado?"}, {"c": "planteo", "t": "Aproximar el tiempo total de 100 tableros con ∫₁¹⁰⁰ T(x) dx y explicar si la integral sobreestima o subestima la suma."}, {"c": "planteo", "t": "Calcular T(100), qué porcentaje del primero representa, y T′(10). ¿Por qué |T′(n)| disminuye a medida que crece n?"}, {"c": "lenguaje", "t": "Redactar el dato de horas-hombre para la cotización, con el método de cálculo y su margen de error."}], "articulacion": {"eje": "2", "t": "¿Qué ocurre con T(n) cuando n → ∞? ¿Tiene T asíntota horizontal? ¿Qué significa para la producción?"}, "clave": "b ≈ 0,322. ∫₁¹⁰⁰ 10·x^(−b) dx ≈ 320 h; suma exacta ≈ 326,5 h: la integral subestima (T decreciente). T(100) ≈ 2,27 h (22,7 % del primero). T′(n) = −10b·n^(−b−1); T′(10) ≈ −0,15 h por tablero. T(n) → 0: asíntota horizontal T = 0, sin sentido físico estricto.", "ref": ""}, {"id": "RI-04", "eje": "R", "carrera": "IND", "integra": ["1", "4", "5"], "tipo": "Tarjeta roja de especialidad", "titulo": "Producción con demanda estacional", "temas": ["Función integral", "Teorema fundamental del cálculo", "Valor medio de una función", "Extremos"], "consigna": "Una fábrica de envases para la industria vitivinícola enfrenta una demanda D(t) = 500 + 200·sen(πt/6) miles de unidades por mes, con t en meses desde el inicio de enero. La planta produce a ritmo constante P y el inventario es I(x) = I₀ + ∫₀ˣ (P − D(t)) dt. Se busca el ritmo P que deje el inventario igual al cabo de 12 meses y el inventario inicial mínimo que evite faltantes. Usar I′(x) para ubicar el inventario mínimo.", "teorema": {"nombre": "Teorema fundamental del cálculo integral", "consigna": "Enunciar el teorema fundamental, justificar con él que I′(x) = P − D(x) y explicar la consecuencia sobre los extremos del inventario."}, "capacidades": ["Modelar un inventario como función integral y analizar sus extremos", "Usar el valor medio de una función para dimensionar un ritmo de producción"], "preguntas": [{"c": "dominio", "t": "¿Qué representa I′(x)? ¿Cómo se deduce del teorema fundamental?"}, {"c": "dominio", "t": "¿Qué es el valor medio de una función en un intervalo? ¿Por qué el ritmo P buscado es el valor medio de la demanda?"}, {"c": "planteo", "t": "Calcular P y obtener I(x) en forma explícita."}, {"c": "planteo", "t": "Determinar en qué momento del año el inventario es mínimo y el inventario inicial necesario para que nunca sea negativo."}, {"c": "lenguaje", "t": "Presentar la política de producción e inventario al directorio, con unidades y supuestos."}], "articulacion": {"eje": "7", "t": "Si la demanda tuviera además una componente con período de 3 meses, ¿cómo se escribiría? ¿Qué relación tiene con la idea de serie de Fourier?"}, "clave": "P = 500 miles/mes (valor medio). I(x) = I₀ − (1 200/π)·(1 − cos(πx/6)). Mínimo en x = 6 (fin de junio): I₀ ≥ 2 400/π ≈ 764 miles de unidades.", "ref": ""}, {"id": "RI-05", "eje": "R", "carrera": "IND", "integra": ["2", "3", "4"], "tipo": "Tarjeta roja de especialidad", "titulo": "Localización de un centro de transferencia", "temas": ["Derivada de funciones compuestas", "Optimización", "Teorema de Bolzano"], "consigna": "Dos plantas industriales están a 3 km y a 5 km de una ruta recta, y sus proyecciones sobre la ruta distan 10 km. Se construirá un centro de transferencia sobre la ruta, unido a cada planta por un camino recto, con longitud total mínima. Si x es la distancia del centro a la proyección de la primera planta, la longitud es L(x) = √(x² + 9) + √((10 − x)² + 25). Minimizar L(x) con la derivada. El costo de construcción por kilómetro crece con la distancia s al centro de transferencia según c(s) = 10 + s miles de USD/km: calcular con una integral el costo de cada camino en la solución de longitud mínima.", "teorema": {"nombre": "Teorema de Bolzano", "consigna": "Enunciar el teorema de Bolzano y usarlo para garantizar que L′(x) se anula en algún punto de (0, 10) antes de calcularlo."}, "capacidades": ["Optimizar una función con raíces cuadradas aplicando la regla de la cadena", "Garantizar la existencia de un punto crítico antes de calcularlo"], "preguntas": [{"c": "dominio", "t": "Derivar L(x) explicando cada aplicación de la regla de la cadena. ¿En qué puntos es L derivable?"}, {"c": "dominio", "t": "Verificar las hipótesis de Bolzano para L′ en [0, 10]. ¿Qué asegura y qué no?"}, {"c": "planteo", "t": "Resolver L′(x) = 0 y calcular la longitud mínima. Interpretar la condición de óptimo con los ángulos de los caminos respecto de la ruta."}, {"c": "planteo", "t": "Calcular el costo de cada camino como ∫₀^ℓ (10 + s) ds y el costo total de la solución. Acotar el punto crítico con dos pasos de bisección sobre L′."}, {"c": "lenguaje", "t": "Indicar la ubicación del centro y la longitud de caminos como en un informe de localización."}], "articulacion": {"eje": "6", "t": "Si el camino a la segunda planta debiera seguir una curva y = f(x) en lugar de una recta, ¿qué fórmula daría su longitud y qué condición debe cumplir f?"}, "clave": "L′(x) = x/√(x² + 9) − (10 − x)/√((10 − x)² + 25); L′(0) < 0 < L′(10). L′ = 0 ⇔ x/3 = (10 − x)/5 ⇔ x = 3,75 km (ángulos iguales con la ruta). L_mín = √(10² + 8²) ≈ 12,81 km. Bisección: L′(5) > 0 ⇒ raíz en (0, 5); L′(2,5) < 0 ⇒ raíz en (2,5; 5). Costo de un camino de longitud ℓ: ∫₀^ℓ (10 + s) ds = 10ℓ + ℓ²/2; ℓ₁ ≈ 4,80 km y ℓ₂ ≈ 8,00 km ⇒ ≈ 59,6 + 112,1 ≈ 171,6 miles de USD.", "ref": ""}, {"id": "RI-06", "eje": "R", "carrera": "IND", "integra": ["2", "4", "5"], "tipo": "Tarjeta roja de especialidad", "titulo": "Adopción de un sistema de riego", "temas": ["Límite al infinito", "Puntos de inflexión", "Ecuación diferencial logística", "Razón de cambio"], "consigna": "Una empresa lanza un sistema de riego por goteo para pequeños productores. Las ventas acumuladas se modelan con N(t) = 50 000/(1 + 49·e^(−0,5t)), con t en meses desde el lanzamiento. Producción necesita saber cuándo será máximo el ritmo de ventas, y el área comercial, cuál es el techo del mercado. Calcular las ventas del segundo semestre como ∫₆¹² N′(t) dt.", "teorema": {"nombre": "Condiciones para punto de inflexión", "consigna": "Definir punto de inflexión, enunciar la condición necesaria y una condición suficiente basadas en la derivada segunda, y justificar por qué el máximo de N′ ocurre en la inflexión de N."}, "capacidades": ["Analizar el comportamiento asintótico y la concavidad de un modelo logístico", "Relacionar un modelo explícito con su ecuación diferencial"], "preguntas": [{"c": "dominio", "t": "Calcular N(0) y lím N(t) para t → +∞. ¿Qué representa cada valor para la empresa?"}, {"c": "dominio", "t": "¿Por qué el instante de máxima velocidad de ventas es un punto de inflexión de N? ¿Qué condición sobre el cambio de signo de N″ lo confirma?"}, {"c": "planteo", "t": "Hallar el instante de inflexión y las ventas acumuladas en ese momento. ¿Cuál es el ritmo máximo de ventas?"}, {"c": "planteo", "t": "Verificar que N satisface dN/dt = 0,5·N·(1 − N/50 000) y calcular las ventas del segundo semestre como ∫₆¹² N′(t) dt."}, {"c": "lenguaje", "t": "Redactar las respuestas para producción y para el área comercial, con unidades y horizonte temporal."}], "articulacion": {"eje": "1", "t": "Obtener la función inversa t(N) y usarla para calcular cuándo se alcanzan 40 000 unidades vendidas."}, "clave": "N(0) = 1 000; techo 50 000. Inflexión en t = 2·ln 49 ≈ 7,8 meses, con N = 25 000. N′_máx = 0,5·50 000/4 = 6 250 unidades/mes. t(N) = 2·ln(49N/(50 000 − N)); t(40 000) = 2·ln 196 ≈ 10,6 meses. ∫₆¹² N′(t) dt = N(12) − N(6) ≈ 44 585 − 14 537 ≈ 30 050 unidades.", "ref": ""}, {"id": "RI-07", "eje": "R", "carrera": "IND", "integra": ["1", "3"], "tipo": "Tarjeta roja de especialidad", "titulo": "Tolerancia de mecanizado", "temas": ["Valor absoluto y entornos", "Inecuaciones", "Diferencial de una función", "Propagación de errores"], "consigna": "Un taller mecaniza ejes de diámetro nominal 25,00 mm con tolerancia de ±0,05 mm. El eje se monta en un buje cuyo fabricante no especifica el diámetro sino la sección transversal: exige que el área A = πd²/4 no se aparte más de 0,4 % de su valor nominal. El jefe de taller sostiene que, si el diámetro está dentro de tolerancia, el área también lo está. Estimar con el diferencial la variación del área. Si los diámetros se distribuyen uniformemente en el intervalo de tolerancia, calcular el área media de la sección como valor medio de A(d) en [24,95; 25,05] y compararla con el área nominal.", "teorema": {"nombre": "Diferencial y aproximación lineal", "consigna": "Definir el diferencial dA, justificar por qué aproxima a ΔA y deducir que el error relativo del área es aproximadamente el doble del error relativo del diámetro."}, "capacidades": ["Traducir una especificación técnica a inecuaciones con valor absoluto", "Estimar la propagación de una tolerancia con el diferencial y contrastarla con el cálculo exacto"], "preguntas": [{"c": "planteo", "t": "Expresar la tolerancia del diámetro como inecuación con valor absoluto y calcular el valor medio de A(d) en [24,95; 25,05]. ¿Por qué supera levemente al área nominal?"}, {"c": "dominio", "t": "Definir el diferencial y explicar la diferencia entre ΔA y dA. ¿Qué término se desprecia?"}, {"c": "planteo", "t": "Resolver la inecuación |πd²/4 − A₀| ≤ 0,004·A₀ para d > 0 y compararla con [24,95; 25,05]. ¿Tiene razón el jefe de taller?"}, {"c": "planteo", "t": "Estimar con el diferencial la variación de la sección para dd = 0,05 mm y compararla con la variación exacta."}, {"c": "lenguaje", "t": "Redactar la especificación del área en notación de intervalos, con unidades y cifras significativas adecuadas para un plano."}], "articulacion": {"eje": "2", "t": "Relacionar el problema con la definición de continuidad mediante ε y δ: para ε = 0,4 % del área nominal, ¿qué δ en el diámetro garantiza |A(d) − A₀| < ε?"}, "clave": "El área cumple si d ∈ [25√0,996; 25√1,004] ≈ [24,94995; 25,04995] mm: 25,05 mm queda fuera por 0,05 µm, el jefe de taller no tiene razón en sentido estricto. dA/A ≈ 2·dd/d = 0,4 %. δ ≈ 0,0499 mm. Valor medio de A en [24,95; 25,05]: (1/0,1)·∫ πd²/4 dd ≈ 490,8745 mm², frente a 490,8739 mm² nominal: la diferencia (≈ 6,5·10⁻⁴ mm²) se debe a la convexidad de A.", "ref": ""}, {"id": "RI-08", "eje": "R", "carrera": "IND", "integra": ["1", "4"], "tipo": "Tarjeta roja de especialidad", "titulo": "Capitalización de un fondo de reserva", "temas": ["Función exponencial", "Formas indeterminadas", "Regla de L'Hôpital"], "consigna": "Una empresa constituye un fondo para reemplazo de equipos a una tasa nominal anual r = 0,12. El banco ofrece capitalizar los intereses n veces por año, de modo que el monto al cabo de un año por cada peso depositado es M(n) = (1 + r/n)ⁿ. El área de finanzas consulta si conviene capitalizar en forma mensual, diaria o «continua», y cuánto se gana en cada caso. Con capitalización continua, calcular la velocidad de crecimiento del monto M(t) = e^(0,12t) en t = 5 y el monto acumulado al cabo de 5 años de un depósito continuo de 1 peso por año, ∫₀⁵ e^(0,12·(5 − t)) dt.", "teorema": {"nombre": "Regla de L'Hôpital", "consigna": "Enunciar la regla de L'Hôpital con sus hipótesis y justificar cómo se aplica a una indeterminación del tipo 1^∞ mediante logaritmos."}, "capacidades": ["Reconocer y transformar formas indeterminadas para aplicar L'Hôpital", "Interpretar un límite como valor de referencia de un proceso discreto"], "preguntas": [{"c": "dominio", "t": "¿Por qué 1^∞ es una forma indeterminada si 1 elevado a cualquier número vale 1?"}, {"c": "dominio", "t": "La regla se aplica a funciones de variable real y n es natural. ¿Qué argumento permite usarla para el límite de la sucesión?"}, {"c": "planteo", "t": "Calcular lím M(n) cuando n → ∞ y compararlo con n = 12 y n = 365."}, {"c": "planteo", "t": "Expresar el monto con capitalización continua para t años, calcular M′(5) y el monto de un depósito continuo de 1 peso por año durante 5 años."}, {"c": "lenguaje", "t": "Redactar la recomendación para el área de finanzas con la diferencia entre modalidades."}], "articulacion": {"eje": "7", "t": "eʳ admite desarrollo en serie de Maclaurin. Escribir sus primeros términos y explicar por qué, para r pequeño, 1 + r es una buena aproximación."}, "clave": "lím M(n) = e^0,12 ≈ 1,12750; n = 12: 1,12683; n = 365: 1,12747. Diferencia del orden de 0,07 centavos por peso al año. Continua a 5 años: e^0,6 ≈ 1,8221. M′(t) = 0,12·e^(0,12t); M′(5) ≈ 0,219 por año. Depósito continuo: (e^0,6 − 1)/0,12 ≈ 6,85 pesos.", "ref": ""}, {"id": "RE-01", "eje": "R", "carrera": "EME", "integra": ["2", "3", "5"], "tipo": "Tarjeta roja de especialidad", "titulo": "Carga de un capacitor temporizador", "temas": ["Ecuación diferencial de primer orden", "Límite al infinito", "Recta tangente", "Integral definida"], "consigna": "En el temporizador de un tablero de comando, un capacitor C = 100 µF se carga a través de una resistencia R = 10 kΩ desde una fuente de continua E = 24 V. La tensión del capacitor cumple R·C·dv/dt + v = E con v(0) = 0. El técnico afirma que «a los 5τ el capacitor está cargado» y que la mitad de la energía entregada por la fuente se pierde en la resistencia. La energía entregada por la fuente hasta el instante T es W(T) = ∫₀ᵀ E·i(t) dt, con i = C·dv/dt.", "teorema": {"nombre": "Teorema fundamental del cálculo (regla de Barrow)", "consigna": "Enunciar la regla de Barrow y justificar cómo se usa para calcular la energía entregada por la fuente hasta un instante T, W(T) = ∫₀ᵀ E·i(t) dt."}, "capacidades": ["Resolver e interpretar la respuesta de un circuito RC", "Calcular energías mediante integrales definidas y analizar su límite"], "preguntas": [{"c": "dominio", "t": "Resolver la ecuación por separación de variables. ¿Qué representa τ = RC y qué unidades tiene?"}, {"c": "dominio", "t": "¿Llega el capacitor a la tensión E? Interpretar la afirmación del técnico sobre 5τ con la definición de límite."}, {"c": "planteo", "t": "Mostrar que la recta tangente a v(t) en t = 0 alcanza el valor E exactamente en t = τ."}, {"c": "planteo", "t": "Calcular W(T) = ∫₀ᵀ E·i(t) dt, su límite cuando T → +∞ y compararlo con la energía almacenada ½·C·E². ¿Tiene razón el técnico?"}, {"c": "lenguaje", "t": "Expresar τ, el tiempo práctico de carga y las energías en unidades del SI con redondeo adecuado."}], "articulacion": {"eje": "7", "t": "e^(−t/τ) admite desarrollo de Maclaurin. ¿Qué expresión aproximada de v(t) se obtiene para t mucho menor que τ y cómo se interpreta?"}, "clave": "v(t) = 24·(1 − e^(−t/τ)), τ = 1 s; v(5τ) ≈ 0,993·E. i = (E/R)·e^(−t/τ); W(T) = C·E²·(1 − e^(−T/τ)) → C·E² = 0,0576 J; almacenada 0,0288 J: se disipa la mitad. Para t ≪ τ: v ≈ E·t/τ.", "ref": ""}, {"id": "RE-02", "eje": "R", "carrera": "EME", "integra": ["1", "2", "4"], "tipo": "Tarjeta roja de especialidad", "titulo": "Máxima transferencia de potencia", "temas": ["Función racional", "Límites en 0 y en el infinito", "Extremos absolutos", "Derivada de un cociente"], "consigna": "Una batería de 12 V con resistencia interna R_s = 4 Ω alimenta una carga resistiva variable R_L. La potencia en la carga es P(R_L) = E²·R_L/(R_s + R_L)². Un estudiante sostiene que cuanto mayor sea la resistencia de carga, mayor será la potencia que recibe, porque P es proporcional a R_L. Maximizar P derivando respecto de R_L. En un ensayo, la resistencia de carga se varía con un reóstato según R_L(t) = 2t Ω, con 0 ≤ t ≤ 4 s: calcular la energía entregada a la carga durante el ensayo como integral de la potencia.", "teorema": {"nombre": "Teorema de Fermat y criterio de la derivada primera", "consigna": "Enunciar el teorema de Fermat y el criterio de la derivada primera, y justificar con ellos que existe una única resistencia de carga que maximiza la potencia."}, "capacidades": ["Analizar una función racional en todo su dominio para refutar una afirmación", "Determinar un máximo absoluto y su significado técnico"], "preguntas": [{"c": "dominio", "t": "Calcular P(0) y lím P(R_L) para R_L → +∞. ¿Qué indican sobre la afirmación del estudiante?"}, {"c": "dominio", "t": "¿Por qué la continuidad de P y su comportamiento en los extremos del dominio garantizan un máximo absoluto?"}, {"c": "planteo", "t": "Derivar P, hallar el punto crítico y calcular la potencia máxima. Verificar con el criterio de la derivada primera."}, {"c": "planteo", "t": "Calcular la energía del ensayo W = ∫₀⁴ P(R_L(t)) dt descomponiendo en fracciones simples. ¿En qué instante la potencia es máxima? ¿Qué rendimiento tiene allí el circuito?"}, {"c": "lenguaje", "t": "Explicar al estudiante su error con un argumento técnico breve y preciso."}], "articulacion": {"eje": "7", "t": "Para R_L pequeña frente a R_s, desarrollar P en serie de potencias de x = R_L/R_s y obtener una aproximación de primer orden. ¿Para qué valores de x converge el desarrollo?"}, "clave": "P(0) = 0; lím P = 0. P′ = E²·(R_s − R_L)/(R_s + R_L)³ = 0 ⇔ R_L = R_s = 4 Ω; P_máx = E²/(4R_s) = 9 W. Rendimiento 50 %: inadecuado para distribución. Ensayo: P(t) = 72t/(2 + t)²; W = 72·(ln 3 − 2/3) ≈ 31,1 J; potencia máxima en t = 2 s (R_L = 4 Ω). P ≈ (E²/R_s)·x·(1 − 2x + …), convergente para |x| < 1.", "ref": ""}, {"id": "RE-03", "eje": "R", "carrera": "EME", "integra": ["1", "2", "7"], "tipo": "Tarjeta roja de especialidad", "titulo": "Vibración de un motor sobre soportes", "temas": ["Sucesión geométrica", "Límite de una sucesión", "Funciones exponencial y trigonométrica", "Serie geométrica"], "consigna": "Un motor montado sobre soportes elásticos recibe un golpe y su desplazamiento vertical responde x(t) = 2·e^(−0,4t)·cos(4t) mm, con t en segundos. El mantenimiento predictivo registra solo las amplitudes de los picos sucesivos y la especificación exige que la vibración quede por debajo de 0,1 mm en menos de 10 s. Obtener la velocidad x′(t), ubicar los instantes de desplazamiento extremo y calcular con una integral definida el desplazamiento medio en el primer período de oscilación, [0, π/2] s.", "teorema": {"nombre": "Convergencia de la serie geométrica", "consigna": "Enunciar la condición de convergencia de la serie geométrica, demostrarla a partir de la suma parcial y justificar su uso para acotar el recorrido total del motor."}, "capacidades": ["Reconocer una sucesión geométrica en los extremos de una oscilación amortiguada", "Usar series geométricas para acotar magnitudes acumuladas"], "preguntas": [{"c": "dominio", "t": "Derivar x(t) y mostrar que los extremos verifican tan 4t = −0,1, separados π/4 s. ¿Por qué sus amplitudes forman una sucesión geométrica?"}, {"c": "dominio", "t": "Enunciar la condición de convergencia de Σ rⁿ y demostrarla con la fórmula de la suma parcial."}, {"c": "planteo", "t": "¿Cumple el soporte la especificación? Calcular a partir de qué instante la envolvente es menor que 0,1 mm."}, {"c": "planteo", "t": "Calcular el desplazamiento medio en [0, π/2] integrando por partes dos veces. ¿Por qué resulta casi nulo?"}, {"c": "lenguaje", "t": "Explicar el decremento logarítmico, ln(aₙ/aₙ₊₁), y su valor para este soporte, como en un informe de mantenimiento."}], "articulacion": {"eje": "5", "t": "La envolvente A(t) = 2·e^(−0,4t) es solución de una ecuación diferencial de primer orden. Escribirla, clasificarla y verificar la solución."}, "clave": "Extremos cada π/4 s; amplitudes aₖ ≈ 2·e^(−0,1πk), razón e^(−0,1π) ≈ 0,730. Envolvente < 0,1 mm para t > ln 20/0,4 ≈ 7,5 s: cumple. Decremento logarítmico 0,1π ≈ 0,314. Recorrido ≈ 2·Σaₖ − a₀ ≈ 12,8 mm. x′(t) = −2e^(−0,4t)·(0,4·cos 4t + 4·sen 4t). Desplazamiento medio en [0, π/2]: ≈ 0,015 mm. A′ = −0,4·A, lineal a variables separables.", "ref": ""}, {"id": "RE-04", "eje": "R", "carrera": "EME", "integra": ["1", "3", "7"], "tipo": "Tarjeta roja de especialidad", "titulo": "Linealización de un termistor", "temas": ["Funciones exponencial y logarítmica", "Diferencial y linealización", "Polinomio de Taylor", "Función inversa"], "consigna": "Un termistor NTC que protege el bobinado de un motor tiene resistencia R(T) = R₀·e^(β·(1/T − 1/T₀)), con R₀ = 10 kΩ a T₀ = 298,15 K (25 °C) y β = 3 950 K. El circuito de protección trabaja con una relación lineal, por lo que se quiere linealizar R alrededor de 25 °C y conocer el rango en que el error es aceptable. Linealizar R con la derivada dR/dT en T₀ y calcular con software, mediante una integral definida, la resistencia media del termistor entre 25 °C y 35 °C y compararla con el promedio de los valores extremos.", "teorema": {"nombre": "Teorema de Taylor de orden 1 con resto", "consigna": "Enunciar el teorema de Taylor de orden 1 con resto de Lagrange y justificar cómo permite estimar el error de la linealización."}, "capacidades": ["Linealizar un modelo exponencial alrededor de un punto de operación", "Estimar el error de una aproximación lineal y su rango de validez"], "preguntas": [{"c": "dominio", "t": "Calcular la sensibilidad dR/dT en T₀ con la regla de la cadena. ¿Qué signo tiene y qué significa «NTC»?"}, {"c": "dominio", "t": "¿Qué información aporta la derivada segunda sobre el error de la linealización?"}, {"c": "planteo", "t": "Escribir la aproximación lineal de R(T) en T₀ y compararla con el valor exacto a 35 °C y a 60 °C."}, {"c": "planteo", "t": "Obtener la inversa T(R) y calcular con software la resistencia media (1/10)·∫ R(T) dT entre 25 °C y 35 °C. ¿Por qué es menor que el promedio de R(25 °C) y R(35 °C)?"}, {"c": "lenguaje", "t": "Expresar la sensibilidad en Ω/K y en %/K e indicar el rango recomendado para la linealización."}], "articulacion": {"eje": "2", "t": "¿Qué valores toma R(T) cuando T → +∞ y cuando T → 0⁺? ¿Tienen sentido físico ambos límites?"}, "clave": "dR/dT(T₀) = −β·R₀/T₀² ≈ −444 Ω/K (≈ −4,4 %/K). A 35 °C: exacto ≈ 6 506 Ω, lineal ≈ 5 556 Ω (−14,6 %). A 60 °C la lineal da un valor negativo. Error < 1 % aproximadamente entre 22 °C y 27,5 °C. 1/T = 1/T₀ + ln(R/R₀)/β. Resistencia media en [298,15; 308,15] K: ≈ 8 109 Ω, menor que (10 000 + 6 506)/2 ≈ 8 253 Ω porque R es convexa.", "ref": ""}, {"id": "RE-05", "eje": "R", "carrera": "EME", "integra": ["1", "2", "5"], "tipo": "Tarjeta roja de especialidad", "titulo": "Corriente en una bobina con tensión rectangular", "temas": ["Función definida por partes", "Función integral", "Continuidad", "Teorema fundamental del cálculo"], "consigna": "Un convertidor aplica sobre una bobina de inductancia L = 10 mH una tensión rectangular: v(t) = +12 V para 0 ≤ t < 1 ms y v(t) = −12 V para 1 ≤ t < 2 ms, y se repite periódicamente. La corriente cumple i(t) = i(0) + (1/L)·∫₀ᵗ v(s) ds, con i(0) = 0. El técnico se pregunta cómo puede ser continua la corriente si la tensión «salta». Verificar que di/dt = v(t)/L en cada tramo.", "teorema": {"nombre": "Continuidad de la función integral", "consigna": "Enunciar y justificar que si f es integrable en [a, b], F(x) = ∫ₐˣ f es continua aun cuando f tenga discontinuidades de salto, e indicar dónde F es derivable."}, "capacidades": ["Integrar funciones definidas por partes y obtener la función acumulada", "Distinguir continuidad y derivabilidad de una función integral"], "preguntas": [{"c": "dominio", "t": "¿Es v(t) integrable aunque sea discontinua? ¿Qué discontinuidades admite la integral definida?"}, {"c": "dominio", "t": "¿En qué puntos i(t) es derivable y en cuáles no? Relacionar con las hipótesis del teorema fundamental."}, {"c": "planteo", "t": "Obtener i(t) por tramos en [0, 2 ms] y representarla. ¿Qué valor máximo alcanza la corriente?"}, {"c": "planteo", "t": "Calcular la corriente media en un período. ¿Qué cambia si la tensión positiva dura 1,2 ms y la negativa 0,8 ms?"}, {"c": "lenguaje", "t": "Explicar al técnico, en términos precisos, por qué la tensión puede saltar y la corriente no."}], "articulacion": {"eje": "7", "t": "La tensión rectangular puede escribirse como una serie de Fourier de senos. ¿Qué forma tendrán los términos de la serie de la corriente si se integra término a término?"}, "clave": "i(t) = 1 200·t A en [0; 1 ms] e i(t) = 1,2 − 1 200·(t − 0,001) A en [1; 2 ms]: onda triangular de 0 a 1,2 A, no derivable en los vértices. Media 0,6 A. Con 1,2 / 0,8 ms la corriente aumenta 0,48 A por período.", "ref": ""}, {"id": "RE-06", "eje": "R", "carrera": "EME", "integra": ["1", "4", "5"], "tipo": "Tarjeta roja de especialidad", "titulo": "Trabajo de compresión en un cilindro", "temas": ["Integral de 1/x y logaritmo", "Aplicaciones de la integral: trabajo", "Formas indeterminadas", "Regla de L'Hôpital"], "consigna": "Un compresor reduce el volumen de aire en un cilindro de V₁ = 2 L a V₂ = 0,5 L, partiendo de p₁ = 100 kPa. Si la compresión es isotérmica, pV = constante; si es politrópica, pVⁿ = constante con n > 1. El trabajo de compresión es W = −∫ p dV entre V₁ y V₂. El fabricante informa el trabajo politrópico con W = (p₂V₂ − p₁V₁)/(n − 1), y un técnico observa que esa fórmula «no funciona» para n = 1. Calcular además la tasa de variación de la presión respecto del volumen, dp/dV, al final de la compresión isotérmica.", "teorema": {"nombre": "Regla de Barrow", "consigna": "Enunciar la regla de Barrow y justificar por qué ∫ dV/V conduce al logaritmo natural, explicando por qué la fórmula de ∫ Vᵐ dV no se aplica cuando m = −1."}, "capacidades": ["Calcular trabajos de compresión mediante integrales definidas", "Resolver una indeterminación para conectar dos modelos"], "preguntas": [{"c": "dominio", "t": "¿Por qué la primitiva de V^(−n) es V^(1−n)/(1 − n) solo si n ≠ 1? ¿Qué primitiva corresponde a n = 1?"}, {"c": "dominio", "t": "Interpretar el trabajo como área en el diagrama p–V. ¿Por qué el proceso politrópico requiere más trabajo?"}, {"c": "planteo", "t": "Calcular el trabajo isotérmico y el politrópico para n = 1,4."}, {"c": "planteo", "t": "Mostrar, aplicando L'Hôpital, que el trabajo politrópico tiende al isotérmico cuando n → 1."}, {"c": "lenguaje", "t": "Presentar ambos resultados en J y explicar al técnico por qué la fórmula «no funciona» en n = 1."}], "articulacion": {"eje": "7", "t": "ln(1 + x) admite desarrollo en serie. ¿Para qué valores de x converge y cómo podría usarse para aproximar ln(V₁/V₂) en una compresión pequeña?"}, "clave": "Isotérmico: W = p₁V₁·ln(V₁/V₂) = 200·ln 4 ≈ 277 J. Politrópico (n = 1,4): p₂ = 100·4^1,4 ≈ 696 kPa; W ≈ (348,2 − 200)/0,4 ≈ 371 J. W(n) = p₁V₁·[(V₁/V₂)^(n−1) − 1]/(n − 1) → p₁V₁·ln(V₁/V₂). Isotérmica: dp/dV = −p₁V₁/V² = −800 kPa/L en V₂.", "ref": ""}, {"id": "RE-07", "eje": "R", "carrera": "EME", "integra": ["1", "5"], "tipo": "Tarjeta roja de especialidad", "titulo": "Valor eficaz de la tensión de red", "temas": ["Funciones trigonométricas", "Valor medio de una función", "Integración de funciones trigonométricas"], "consigna": "La tensión de la red domiciliaria es v(t) = 311·sen(100πt) V. Un instrumento de valor medio indica 0 V, mientras que uno de verdadero valor eficaz indica 220 V. El valor eficaz se define como V_ef = √((1/T)·∫₀ᵀ v²(t) dt), con T el período. Para un rectificador se necesita además el valor medio de la señal en medio período. Calcular también la máxima velocidad de variación de la tensión, dv/dt, e indicar en qué instantes se produce.", "teorema": {"nombre": "Teorema del valor medio del cálculo integral", "consigna": "Enunciar el teorema del valor medio del cálculo integral, interpretarlo geométricamente y justificar por qué el valor medio de v(t) en un período es nulo."}, "capacidades": ["Calcular el valor medio y el valor eficaz de una señal periódica", "Integrar funciones trigonométricas mediante identidades y sustitución"], "preguntas": [{"c": "dominio", "t": "Interpretar el teorema como un rectángulo de área equivalente. ¿Qué hipótesis garantiza la existencia del punto c?"}, {"c": "dominio", "t": "¿Por qué el valor medio en un período es cero? Justificarlo a partir de la simetría de la función."}, {"c": "planteo", "t": "Determinar el período y calcular el valor eficaz usando sen²u = (1 − cos 2u)/2."}, {"c": "planteo", "t": "Calcular el valor medio en medio período e interpretarlo para una señal rectificada. Obtener la máxima pendiente dv/dt de la señal y los instantes en que se produce."}, {"c": "lenguaje", "t": "Explicar con precisión qué mide cada instrumento y por qué ambos están bien calibrados."}], "articulacion": {"eje": "7", "t": "La serie de Fourier descompone una señal periódica en senos y cosenos cuyos coeficientes son integrales sobre un período. ¿Qué relación tienen con las integrales calculadas?"}, "clave": "T = 1/50 s = 20 ms. Valor medio en un período: 0. V_ef = 311/√2 ≈ 220 V. Valor medio en medio período: 2·311/π ≈ 198 V. dv/dt = 311·100π·cos(100πt): máximo ≈ 9,77·10⁴ V/s en los cruces por cero.", "ref": ""}, {"id": "RE-08", "eje": "R", "carrera": "EME", "integra": ["1", "7"], "tipo": "Tarjeta roja de especialidad", "titulo": "Armónicos de un inversor", "temas": ["Funciones periódicas, pares e impares", "Series funcionales", "Serie de Fourier", "Series alternadas"], "consigna": "Un inversor de baja calidad alimenta una bomba con una tensión de onda cuadrada que vale +1 y −1, en valores normalizados, en semiperíodos alternados. Un analizador de espectro muestra componentes en 1, 3, 5, 7… veces la frecuencia fundamental, con amplitudes decrecientes. El manual del analizador indica que la onda se representa como f(t) = (4/π)·(sen t + sen 3t/3 + sen 5t/5 + …). Calcular el coeficiente b₁ = (2/π)·∫₀^π f(t)·sen t dt y comparar la máxima pendiente de cada armónico (4/(nπ))·sen(nt).", "teorema": {"nombre": "Criterio de Leibniz para series alternadas", "consigna": "Enunciar el criterio de Leibniz y usarlo para justificar que la serie 1 − 1/3 + 1/5 − 1/7 + … converge; relacionarla con el valor de f(π/2)."}, "capacidades": ["Interpretar la serie de Fourier como descomposición de una señal periódica", "Analizar la convergencia de una serie funcional en puntos particulares"], "preguntas": [{"c": "dominio", "t": "Verificar que la onda cuadrada es impar. ¿Por qué eso explica que la serie contenga solo senos?"}, {"c": "dominio", "t": "Evaluar la serie en t = π/2 y aplicar el criterio de Leibniz. ¿Qué valor debe tener la suma?"}, {"c": "planteo", "t": "¿Qué valor da la serie en t = 0, punto de salto de la onda? ¿Cómo puede una suma de funciones continuas representar una función discontinua?"}, {"c": "planteo", "t": "Calcular b₁ con la integral. Derivar el armónico de orden n: ¿qué se observa sobre su máxima pendiente y qué indica sobre la serie derivada término a término?"}, {"c": "lenguaje", "t": "Explicar con lenguaje técnico, y sin fórmulas, qué muestra un analizador de espectro."}], "articulacion": {"eje": "6", "t": "El valor eficaz de la onda cuadrada es 1. ¿Cómo se calcula con una integral y cómo se compara con el valor eficaz de la fundamental, (4/π)/√2?"}, "clave": "En t = π/2: (4/π)·(1 − 1/3 + 1/5 − …) = 1 ⇒ 1 − 1/3 + 1/5 − … = π/4. En t = 0 la serie vale 0, promedio de los límites laterales. b₁ = (2/π)·∫₀^π sen t dt = 4/π. La pendiente máxima de (4/(nπ))·sen(nt) es 4/π para todo n: la serie derivada no converge. Valor eficaz de la fundamental ≈ 0,90.", "ref": ""}];
